export default [{"id":170,"question":"أُصلي والحمد لله، ولكن أحسّ بالضيق وعدم الراحة في الصلاة، فأرشدوني جزاكم الله خيرًا","title":"توجيه لمن لا يحس بالراحة في صلاته","answer":"الجواب: هذا مرضٌ من الأمراض القلبية، والغالب أنَّ سببه الذنوب والغفلة، فالذي لا ينشرح للصلاة إنما وقع له ذلك من غفلته وإعراضه وذنوبه، فليَتُبْ إلى الله، وليُجاهد نفسه، ويسأل ربَّه التوفيق، وليحضر بقلبه في الصلاة، فالصلاة راحة وقُرَّة عينٍ، يقول النبيُّ ﷺ: جُعِلَتْ قُرَّةُ عيني في الصَّلاة، فهي قُرَّة العين، ويقول لبلالٍ: أقم، أرحنا بالصلاة. فالصلاة راحة القلوب، وراحة الضَّمائر، وقُرَّة العين، إذا دخل فيها المؤمنُ ارتاح لها، واطمأنَّ قلبه، وقرَّت عينه؛ لأنَّها عمود الإسلام، ولأنه يُرضي فيها ربَّه، ويقوم بين يديه خاشعًا، فهي راحة القلوب، ونعيم الأرواح، وقُرَّة العين.\nفإذا أحسَّ الإنسانُ بالضيق فيها فليعلم أنَّ هذه مصيبة، وليُعالجها بالتوبة إلى الله، وسؤاله التوفيق والهداية والإعانة، والله يتوب على التَّائبين جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/3709/توجيه-لمن-لا-يحس-بالراحة-في-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0165.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها","الرقائق"]},{"id":225,"question":"أحد زملائي أُصيب في حادث سيارةٍ، وأُصيب إصابةً بالغةً، حيث مكث خمسةً وخمسين يومًا مُغْمى عليه، وبعدها أفاق من ذلك، وطلب من الأطباء إحضار ترابٍ ليتيمَّم به ليُصلي، فلم يفعلوا، وترك الصلاة ثلاثة أشهر غير الخمسين التي حصل فيها الإغماء.سؤالي: ما حكم عمله هذا؟ وهل يُعيد الصلاة في الإغماء وما بعده أم ماذا يفعل؟","title":"ما حكم ما يفوت من صلوات حال الإغماء؟","answer":"الجواب: هذا غلطٌ، الواجب عليه أن يُصلي على حسب حاله؛ لأنَّ الله قال: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وقد أجمع العلماء على أنَّ المؤمن يُصلي على حسب حاله، فإذا لم يجد ماءً ولا ترابًا، ولم يستطع التيمم ولا الوضوء؛ صلَّى على حسب حاله.\nوقد صلَّى الصحابةُ في عهد النبيِّ ﷺ لما بعثهم يلتمسون عِقد عائشة بغير وضوءٍ ولا تيممٍ، ما كان عندهم ماء، والتيمم لم يُشرع بعد، فصلّوا على حسب حالهم، ولم يُنكر عليهم النبيُّ ﷺ.\nفالواجب على المريض وعلى غيره من الناس أن يُصلي على حسب حاله، إن وجد ماءً صلَّى بالماء، وإن لم يجد ماءً تيمم، وإن مُنع من التيمم ولم يتيسر ما يتمم به صلَّى على حسب حاله، كالأسير الذي يُؤسر في الخشبة ونحوها، ما يتمكن من ماء ولا تراب؛ يُصلي على حسب حاله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ.\nوعليه القضاء؛ لأنه تركها بعذرٍ، ترك الصلاة يظن أنه معذورٌ، ما تركها عمدًا ومخالفةً لشرع الله، لو تركها هكذا كان كافرًا، لكنه تركها يظن أنه معذورٌ وأنه يجوز له الترك، فعليه القضاء، عليه أن يتوضأ ويقضي هذه الأيام التي تركها.\nأما أيام الإغماء فاختلف فيها العلماء، فإن قضاها فهو أحوط، وإن لم يقضها فلا بأس؛ لأنها مدة طويلة، والإغماء يُشبه الجنون، فلا قضاء عليه إن شاء الله، وإن قضى فلا حرج، لكن لو كان الإغماءُ قليلًا: يومين أو ثلاثًا؛ يقضي، فقد أُغمي على بعض الصحابة وقضى المدة اليسيرة، لكن إذا زاد على الثلاث وصار كثيرًا فالأصح فيه عدم القضاء؛ لأنه حينئذٍ أشبه بالمجنون والمعتوه، أما الإغماء ليومين أو ثلاث فهذا أشبه بالنَّائم فيقضي.","link":"https://binbaz.org.sa/fatwas/4069/ما-حكم-ما-يفوت-من-صلوات-حال-الاغماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0232.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":1001,"question":"إذا كنتُ مُسافرًا وحضرت صلاةُ العصر في جماعةٍ، ولم أُصلِّ الظهرَ، فهل أُصلي العصر ثم أُصلي الظهر بعدها، أم أُصلي العصر بنية الظهر؟ أم ماذا أفعل؟","title":"حكم من لم يُصَلِّ الظهر وحضرته العصر","answer":"الجواب: إذا حضر الإنسانُ جماعةً سيُصلون العصرَ في الحضر أو في السفر وهو ما صلَّى الظهر، فإنه يُصلي معهم بنية الظهر؛ من أجل الترتيب، ثم يُصلي العصر بعد ذلك، ولا حرج في ذلك؛ لأنَّ النية لا تُؤثر في هذا، فيُصلي معهم الظهر، ثم إذا سلَّموا صلَّى العصر بعد ذلك في المسجد، أو في بيته، وإن تيسرت جماعةٌ يُصلي معهم العصر صلَّى معهم العصر.\nوهكذا لو جاء وهم يُصلون العشاء، وهو ما صلَّى المغرب، يدخل معهم فيُصلي معهم المغرب بنية المغرب، ويجلس في الثالثة ينتظر، فإذا سلَّم الإمامُ سلَّم معهم، ثم بعد ذلك يُصلي العشاء في المسجد إن تيسر، أو في بيته، فيحصل الترتيبُ وفعل الجماعة، ويُصلي بعد ذلك الصلاة الحاضرة.","link":"https://binbaz.org.sa/fatwas/21054/حكم-من-لم-يصل-الظهر-وحضرته-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0850إذا كنت مسافراً وحضرت صلاة العصر في جماعة ولم أصلي الظهر فهل أصلي معهم العصر بية الظهر.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1232,"question":"إذا كان الإنسانُ نائمًا في الظهر ولم يستيقظ إلا بعد أذان المغرب، فصلَّى المغرب، فتذكَّر أنه لم يُصلِّ العصر: هل يُصليها أم لا؟","title":"حكم مَن صلى بعد نوم ثم تذكر فائتة قبلها","answer":"الجواب:\nنعم، إذا صلَّى المغرب ناسيًا للعصر، ثم ذكرها، يُصلي العصر، وصلاة المغرب مُجزئة، أما التَّعمد لا، لا يتعمَّد، يجب أن يبدأ بالعصر ثم بالمغرب، مثلما فعل النبيُّ ﷺ لما شُغل يوم الأحزاب في قتال الكفرة، شغلوه عن العصر، فصلَّاها بعد الغروب، ثم صلَّى المغرب بعدها، لكن لو نسي وصلَّى المغرب، ثم ذكر أنَّ عليه العصر أو غيرها، صلَّى الفائتة، وأجزأته التي صلَّاها لأجل النسيان: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، قال الله: قد فعلت.","link":"https://binbaz.org.sa/fatwas/21280/حكم-من-صلى-بعد-نوم-ثم-تذكر-فاىتة-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1023إذا كان الإنسان نائماً في الظهر ولم يستقظ إلا بعد أذان المغرب وتذكر أنه لم يصلي العصر هل يصليها؟.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1289,"question":"توفي والدي بسبب مرضٍ ألمَّ به، وقد كان يُعاني في أيامه الأخيرة من حالة غيبوبةٍ لفترات تطول أحيانًا، فأوصانا بأن نقوم بالصلاة عنه والصيام في الأيام التي لم يستطع الصلاةَ فيها ولا الصيام، فهل يلزمنا الصيام والصلاة عنه؟ أم ماذا يجب أن نفعل؟ علمًا بأنه قد مرَّ على وفاته حوالي ست سنوات؟","title":"هل يجوز الصلاة عن فاقد الوعي بعد موته؟","answer":"الجواب:\nليس عليكم صلاةٌ ولا صيامٌ، إذا كان مريضًا عجز عن الصيام فليس عليه قضاءٌ، وليس عليكم قضاءٌ أنتم؛ لأنه مات قبل أن يتمكن، فهو معذورٌ، وأنتم ليس عليكم شيءٌ؛ لأنه ما فرط، هو مات في مرضه.\nوأما الصلاة: فما يجوز له أن يُؤخِّر الصلاة، الواجب عليه أن يُصلي في الوقت، ولو على جنبه، ولو بالإيماء، ولو بالكلام والنية، النبي عليه السلام قال للمريض: صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنبٍ، فإن لم تستطع فمُستلقيًا، ما له عذرٌ إذا كان عقله معه، أما إذا كانت عنده غيبوبة وضاع عقله فما عليه شيءٌ، لكن إن كان عقله معه -يعقل الصلاة ويفهم- يُصلي على حسب حاله: القاعد يركع في الهواء، ثم يسجد في الأرض إن كان يستطيع، وإن كان ما يستطيع صلَّى على جنبه بالنية والكلام، يُكبر ويقرأ الفاتحة معها، ثم يُكبر ناويًا الركوع ويقول: سبحان ربي العظيم، ثم يقول: سمع الله، ناويًا الرفع من الركوع، ويقول: ربنا ولك الحمد، إلى آخره، ثم يُكبر ناويًا السّجود ويقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم يُكبر ناويًا الرفع من السجود ويقول: رب اغفر لي، رب اغفر لي، ثم يُكبر الثانية ناويًا السجود، وهكذا حتى يُكمل، وعلى جنبه، أو مُستلقيًا، لا يسقط عنه أداء الصلاة، على جميع الأحوال، ما دام عقله معه.\nأما إذا كانت عنده غيبوبة وضاع العقلُ، ما يضبط، فالله جلَّ وعلا لا يُكلِّف نفسًا إلا وسعها، ولا يُكلِّف غير العاقل، غير العاقل ما عليه شيءٌ، ما عليه تكاليف من حين تغيَّر العقلُ: لكبر سنٍّ، أو مرضٍ سقطت التَّكاليف.","link":"https://binbaz.org.sa/fatwas/21346/هل-يجوز-الصلاة-عن-فاقد-الوعي-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1089هل يجوز للمريض أن يوصي أحد أن يصلي عنه إذا لم يستطع ؟ ابن باز فتاوى.mp3","categories":["قضاء الصيام","قضاء الفوائت"]},{"id":1300,"question":"رجلٌ صلَّى العصر، ثم نام، فما قام إلا مع إقامة صلاة العشاء، فبأيّهما يبدأ؟ وكيف يُرتّبها؟ وإن دخل مع الإمام بنية المغرب فماذا يفعل؟ وكيف يُصليها؟","title":"ما كيفية القضاء لمن نام عن عدة صلوات؟","answer":"الجواب:\nيبدأ بالمغرب كما رتَّب الله، يُصلي معهم العشاء وينوي المغرب، فإذا قاموا للرابعة جلس، وسلَّم معهم إذا سلَّموا، ثم صلَّى العشاء بعد ذلك، إلا إذا أمكن أن يُصلي المغرب قبل أن تُقام العشاء، صلَّى المغرب قبل، ثم صلَّى معهم العشاء، فإن أدركهم في الصلاة قد أُقيمت الصلاةُ يُصلي معهم، وإذا قاموا للرابعة جلس في الثالثة وتشهَّد وانتظرهم، وسلَّم معهم، وصارت له مغربًا على الصحيح، ثم يُصلي العشاء بعد ذلك.","link":"https://binbaz.org.sa/fatwas/21369/ما-كيفية-القضاء-لمن-نام-عن-عدة-صلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1112رجل صلى العصر فنام ولم يستيقط ألاَّعلى إقامة صلاة العشاء فأيهما يبدأ؟ ابن باز.mp3","categories":["قضاء الفوائت"]},{"id":1468,"question":"يقول السائل: ما حكم الوصية للأقارب غير الوارثين؟ هل هو واجب أم سُنة؟","title":"حكم الوصية للأقارب غير الوارثين","answer":"الجواب:\nمستحبة، مساعدة الأقارب غير الورثة مستحبة، يعني الوصية لهم. أما الورثة فلا؛ يقول النبي ﷺ: لا وصية لوارث.\nس: يكون من الثُّلُث؟\nج: من الثلث فما دونه.","link":"https://binbaz.org.sa/fatwas/21565/حكم-الوصية-للاقارب-غير-الوارثين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الوصية للأقارب غير الوارثين.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1498,"question":"مَن نام عن العصر والمغرب فلم يستيقظ إلا قبل العشاء بشيءٍ يسيرٍ لا يكفي إلا لأداء فريضةٍ واحدةٍ ماذا يُقَدِّم؟","title":"ما ترتيب القضاء لمن نام عن عدة صلوات؟","answer":"الجواب:\nيُصلي الظهر والعصر، ثم يُصلي المغرب والعشاء.\nس: ألا يُقدِّم المغرب لكي لا تكثر عليه الفوائت؟\nج: بعضهم يقول: إذا ضاق الوقت يبدأ بالحاضرة، ولكن ظاهر النصوص خلاف ذلك، يقول النبيُّ ﷺ: مَن نام عن الصلاة أو نسيها فليُصلِّها إذا ذكرها، لا كفَّارةَ لها إلا ذلك، هذا نصُّ حديث النبي ﷺ، يبدأ بالمنسيَّة ثم يأتي بالحاضرة.","link":"https://binbaz.org.sa/fatwas/21597/ما-ترتيب-القضاء-لمن-نام-عن-عدة-صلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في قضاء الفوائت.mp3","categories":["قضاء الفوائت"]},{"id":1605,"question":"والد أوصى في وصيته لأبنائه بأن يُضحُّوا له كل سنةٍ، فمضت أيام التَّشريق في إحدى السنوات ولم يُضحّوا، فما الواجب عليهم؟","title":"حكم من أخلّ بوصية والده أن يُضَحَّى عنه","answer":"الجواب:\nيعني: هو الذي أوصى به؟\nس: نعم.\nج: يذبحونها ولو بعد العيد.\nس: هل عليهم التوبة؟\nج: نعم، عليهم التوبة إذا كانوا تعمَّدوا، حتى ولو من مالهم..... لو تصدَّق عنه بذبيحةٍ في أي وقتٍ، تصدَّق بها على الفقراء فله أجر.\nس: إذا لم يكن له مالٌ وإنما أوصى الأولاد أن يذبحوا؟\nج: إذا تيسر لهم.\nس: يعني ما هو واجب؟\nج: لا، ما هو واجب: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ ۝ وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:14- 15]، فمع كونهما جاهداه في الشرك قال الله له: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا بالإحسان إليهما وبرّهما، وإن كانا مشركين، فلعل الله يهديهما بسبب برّه لهما، والإحسان إليهما، والرفق بهما، لعلهما ولعلهما.","link":"https://binbaz.org.sa/fatwas/21709/حكم-من-اخل-بوصية-والده-ان-يضحى-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أوصى أولاده بأن يضحوا له كل عام ولم يستطيعوا.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":1614,"question":"سؤال من امرأةٍ تقول: ركبتُ لولبًا، وكانت أيام الدورة ستة أيام، ولا يزال الدم مستمرًّا، وتركت الصلاة مدة خمسة أيام بعد الأيام الأولى، فهي في خلال خمسة أيام لم تُصلِّ، هل تُعيد الصلاة خمسة أيام؟ وهل عليها إثم؟","title":"حكم صلاة المرأة التي زاد الدم عن عادتها","answer":"الجواب:\nهو الأحوط، لها أن تُعيد ما زاد على الدورة، الرسول لما اشتكت إليه النساء أمر مَن اشتكت إليه الدّماء أن تغتسل عند تمام الدورة.","link":"https://binbaz.org.sa/fatwas/21718/حكم-صلاة-المراة-التي-زاد-الدم-عن-عادتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة المرأة التي ينزل منها دم.mp3","categories":["الحيض والنفاس","قضاء الفوائت"]},{"id":2095,"question":"أوصى المُوصِي بوصيَّةٍ ولم يقبلها المُوصَى له؟","title":"حكم الوصية إذا لم يقبلها المُوصَى له","answer":"الجواب:\nإذا ما قبلها تصير للورثة.\nس: للورثة أم لبيت المال؟\nج: لا، للورثة، ورثة الموصِي.","link":"https://binbaz.org.sa/fatwas/22213/حكم-الوصية-اذا-لم-يقبلها-الموصى-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أوصى المُوصِي ولم يقبلها المُوصَى له.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2184,"question":"كتابة الوصية هل هي واجبة؟","title":"ما حكم كتابة الوصية؟","answer":"الجواب:\nلا، مستحبة، لكن إذا كان له شيء يخشى عليه، مثل: ديون ما عليها وثائق، فعليه أن يُثبتها للناس حتى لا تضيع حقوقهم، أمَّا إذا لم يكن عليه شيء وإنما هي مجرد صدقة فمستحبٌّ له إذا كان عنده شيء يُوصي فيه، إذا كانت عنده سعة.","link":"https://binbaz.org.sa/fatwas/22306/ما-حكم-كتابة-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كتابة الوصية.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2255,"question":"إذا نام عن صلاة العيد هل يقضيها؟","title":"حكم قضاء صلاة العيد والاستسقاء","answer":"الجواب:\nأفضل.\nس: وصلاة الاستسقاء؟\nج: إذا استسقى جزاه الله خيرًا، وهو أفضل، ويُرجى أن يُجيب اللهُ دعوتَه.\nس: كيف يستسقي منفردًا؟\nج: يُصلي ركعتين ويسأل ربَّه ويقول: اللهم أَغِثِ العباد، اللهم أغث عبادك.\nس: بنفس الصِّفة؟\nج: نعم، مثل صلاة العيد.","link":"https://binbaz.org.sa/fatwas/22378/حكم-قضاء-صلاة-العيد-والاستسقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نام عن صلاة العيد والاستسقاء.mp3","categories":["صلاة العيدين","قضاء الفوائت"]},{"id":2276,"question":"امرأة لها ابنان، ولها مِلكٌ عبارة عن منزلٍ، واشترطت أنه إذا تُوفي الابنُ الصَّغير أن يحلّ محله ابنه كالسّبالة؟","title":"ما حكم الوصية لابن الابن والأجنبي؟","answer":"الجواب:\nإذا أوصت لهم؛ لا بأس، بقدر الثلث، ما لهم إلا قدر الثلث، إلا أن يرضى بقيةُ الورثة.\nس: الابنان شريكان في المنزل بعد ورثهما أمّهما؟\nج: المقصود أنها إذا أوصت لأولاد ولدها تكون الوصيةُ ناجزةً لا بأس بها، لكن بالثلث فأقل.\nس: هي أوصت لأحد ..؟\nج: أو لأجنبي لا بد أن يكون بالثلث فأقل.\nس: أوصت لأبناء أحد الابنين، هل يجوز ذلك؟\nج: بالثلث فأقل؛ لأنَّه ما يرث، فالابن مع الابن عمُّهم يمنعهم، ما هم بورثةٍ، فإذا أوصت لهم بالثلث أو بأقل كالربع والخمس لا بأس.\nس: الموصي ولو كان ماله قليلًا؟\nج: ولو كان ماله قليلًا إذا أوصى.","link":"https://binbaz.org.sa/fatwas/22399/ما-حكم-الوصية-لابن-الابن-والاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اشتراك الأبناء في الميراث.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":2332,"question":"مَن أخَّر الصلاةَ بدون عذرٍ حتى خرج وقتُها، هل تصح صلاتُه؟","title":"حكم الصلاة بعد الوقت لمَن أخَّرها دون عذرٍ","answer":"الجواب:\nعلى خلافٍ: الجمهور تصحّ عندهم الصلاة، ومَن قال أنه كفر فعليه التوبة فقط، وإذا قضى احتياطًا فحسنٌ.","link":"https://binbaz.org.sa/fatwas/22456/حكم-الصلاة-بعد-الوقت-لمن-اخرها-دون-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخَّر الصلاةَ بدون عذرٍ حتى خرج وقتُها.mp3","categories":["قضاء الفوائت"]},{"id":3286,"question":"سئل شيخ الإسلام ابن تيمية كما في مجموع الفتاوى عن رجل فاتته صلاة العصر فجاء إلى المسجد فوجد المغرب قد أقيمت فهل يصلي الفائتة قبل المغرب أم لا؟فقال رحمه الله: بل يصلي المغرب مع الإمام ثم يصلي العصر باتفاق العلماء، ثم ذكر رحمه الله خلاف العلماء في إعادة المغرب بعد صلاة العصر، فهل جواب شيخ الإسلام صحيح أم لا؟فإذا كان صحيحًا فكيف يُخَرَّج؟ فمعلوم أن ترتيب الصلوات واجب؟","title":"حكم من فاتته صلاة العصر وأُقيمت المغرب","answer":"الجواب: مراده رحمه الله أنه يصلي مع الإمام نافلة المغرب؛ لقول النبي ﷺ: فإن أقيمت وأنت في المسجد فصل معهم، فلا تقل صليت فلا أصلي، صَلِّ معهم. فبعض أهل العلم قال: تجزئ ولو قدمتها على العصر، وقال بعضهم: لا، يصليها تكون نافلة، لا يجلس والناس يصلون، ثم يصلي بعد ذلك المغرب إذا صلى العصر؛ حتى يحصل الترتيب وهذا هو الصواب: يصلي العصر ثم يصلي المغرب، فإذا جاء وهم في المغرب صلى معهم نافلة حتى لا يجلس والناس يصلون، وإن صلاها بنية العصر وزاد واحدة فالظاهر أنها تجزئه؛ لأن النية لا تؤثر ما دام تم من الفعل فالحمد لله.  لكن كونه يصلي معهم نافلة ثم يصلي العصر ثم يصلي بعدها المغرب؛ فهذا هو الواجب؛ لأن الله رتبها هكذا، وإن صلى العصر وحده ثم دخل معهم في المغرب وأمْداه فلا بأس.","link":"https://binbaz.org.sa/fatwas/23450/حكم-من-فاتته-صلاة-العصر-واقيمت-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رجل فاتته صلاة العصر فجاء إلى المسجد فوجد المغرب قد أقيمت.mp3","categories":["قضاء الفوائت"]},{"id":3328,"question":"صلاة العيد تقضى جماعة أم فرادى؟","title":"هل تُقضى صلاة العيد جماعة أم فرادى؟","answer":"الجواب: إذا قضاها مع أهل بيته في جماعة لا بأس، كما كان يفعل أنس، أو قضاها وحده الأمر واسع إن شاء الله.","link":"https://binbaz.org.sa/fatwas/23494/هل-تقضى-صلاة-العيد-جماعة-ام-فرادى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من فاتته صلاة العيد فهل يقضيها جماعة.mp3","categories":["صلاة العيدين","قضاء الفوائت"]},{"id":3506,"question":"من نام عن صلاة، هل يؤذن لها؟","title":"هل يُؤذَّن للصلاة الفائتة؟","answer":"الجواب: القاعدة الأذان، إذا كان قد خرج الوقت. أما إذا كان في الوقت فقد أذن الناس ويكفي، ويقيم، والحمد لله. أما إذا استيقظ بعد الشمس فالسُّنة أن يؤذن ويقيم.","link":"https://binbaz.org.sa/fatwas/23686/هل-يوذن-للصلاة-الفاىتة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من نام عن صلاة، هل يؤذن لها.mp3","categories":["قضاء الفوائت"]},{"id":3507,"question":"نام عن صلاة الفجر ولم يتذكر حتى صلاة العشاء؟","title":"حكم مَنْ نام عن الفجر ولم يتذكر حتى العشاء","answer":"الجواب: إذا ذكرها صلاها فقط.\nس: ويعيد الظهر والعصر ؟\nالشيخ: لا يعيد شيئًا، بس إذا ذكرها يعيدها هي، يصليها هي.","link":"https://binbaz.org.sa/fatwas/23687/حكم-من-نام-عن-الفجر-ولم-يتذكر-حتى-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من نام عن صلاة الفجر ولم يتذكر حتى صلاة العشاء.mp3","categories":["قضاء الفوائت"]},{"id":3508,"question":"شخص إذا خرج الجماعة من المسجد يقوم فيتوضأ ثم يذهب يصلي وحده في المسجد، وقال: إن قضاء الفرض في المسجد أولى من البيت وأفضل، فهل له دليل؟","title":"هل قضاء الفرض بالمسجد أفضل من البيت؟","answer":"الجواب: فاتته الجماعة؟\nالطالب: فاتته الجماعة الأصلية.\nالشيخ: الظاهر يقضيها في البيت، ولا حاجة إلى المسجد، قضاؤها في البيت يكفي.","link":"https://binbaz.org.sa/fatwas/23688/هل-قضاء-الفرض-بالمسجد-افضل-من-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قضاء الفرض في المسجد أولى من البيت.mp3","categories":["قضاء الفوائت"]},{"id":3509,"question":"(الفائتة) يصليها برواتبها؟","title":"هل تُقضى الرواتب مع الصلاة الفائتة؟","answer":"الجواب: ما جاء ذِكْرُ الرواتب، ما بلغني في هذا شيء، لكن في سنة الفجر يصلي سنة الفجر، النبي ﷺ لما قضاها صلى سُنّتها معها.","link":"https://binbaz.org.sa/fatwas/23689/هل-تقضى-الرواتب-مع-الصلاة-الفاىتة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصلي الصلاة الفائتة برواتبها.mp3","categories":["قضاء الفوائت"]},{"id":3510,"question":"إذا ذكر الفائتة في أثناء الصلاة؟","title":"حكم مَنْ ذكر فريضة فائتة أثناء أخرى؟","answer":"الجواب: الأقرب -والله أعلم- أنه يتمها نافلة، ثم يصليها الفائتة، ثم يصلي الحاضرة.","link":"https://binbaz.org.sa/fatwas/23690/حكم-من-ذكر-فريضة-فاىتة-اثناء-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ذكر الفائتة في أثناء الصلاة.mp3","categories":["قضاء الفوائت"]},{"id":3915,"question":"المريض إذا تركها جهلًا هل يقضيها أو يكفيه التوبة؟","title":"حكم المريض الذي ترك الصلاة جهلًا","answer":"الجواب: إذا كان مثله يجهل لا يقضي.  أما إذا كان مثله لا يجهل فيَكْفُر، ولا يقضي أيضًا. هذا الذي يختلف: إنسان نشأ في أطراف غابات إفريقيا أو غابات بعيدة عن الإسلام، فهذا يُعلم ويبدي الإسلام من جديد.","link":"https://binbaz.org.sa/fatwas/24133/حكم-المريض-الذي-ترك-الصلاة-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المريض الذي ترك الصلاة جهلًا.mp3","categories":["قضاء الفوائت"]},{"id":4490,"question":"إذا فاتت صلاةُ العيد على القول بأنها فرض كفايةٍ يُعيدها الواحد؟","title":"حكم قضاء صلاةُ العيد لمن فاتته","answer":"الجواب: ... الأفضل يُعيدها، أما إذا قلنا بالوجوب العيني وجب القضاء.  أما بالقول بأنها كفاية أو أنها سنة استحبّ قضاؤها ركعتين.\nس: صلاة العيد فاتته ركعة؟\nج: يأتي بركعةٍ مثل الجمعة.","link":"https://binbaz.org.sa/fatwas/24770/حكم-قضاء-صلاة-العيد-لمن-فاتته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا فاتت صلاةُ العيد على القول بأنها فرض كفايةٍ هل يُعيدها الواحد.mp3","categories":["صلاة العيدين","قضاء الفوائت"]},{"id":4501,"question":"مَن قدم مُسافرًا، وكان قد أخَّر الصلاة، ثم صلَّى بنية العصر، وبقيت عليه الظهر، هل صلاته صحيحة أو يقال: يُعيد؟","title":"حكم من صلَّى العصر مع جماعة وعليه الظهر","answer":"الجواب: الصواب أنه يُعيد، يُصلي الظهر ثم يُعيد العصر، لكن إذا صلَّى مع الناس لتحصيل الفضل، وتكون له نافلة، ثم يُصلي الظهر، ثم يُصلي العصر، وإن صلَّى الظهر معهم بنية الظهر وهم يُصلون العصر أجزأ على الصحيح، اختاره جماعةٌ من أهل العلم: كالموفق، وشيخ الإسلام ابن تيمية، وجماعة، ينوي الظهر وهم يُصلون العصر، فإذا فرغ صلَّى العصر.\nس: هنا اختلفت النيةُ؟\nج: ما يضرّ اختلاف النية.","link":"https://binbaz.org.sa/fatwas/24781/حكم-من-صلى-العصر-مع-جماعة-وعليه-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قدم مُسافرًا قد أخَّر الصلاة وصلَّى بنية العصر وبقيت عليه الظهر، فما الحكم.mp3","categories":["صلاة المسافر","قضاء الفوائت"]},{"id":4503,"question":"إذا ضاق وقتُ الحاضرة وعليه فائتة؟","title":"إذا ضاق وقتُ الحاضرة وعليه فائتة أيهما يقدم؟","answer":"الجواب: يُصلي الحاضرة، وهذا المقدم عند الجمهور؛ حتى لا تكون كلها فائتة.","link":"https://binbaz.org.sa/fatwas/24783/اذا-ضاق-وقت-الحاضرة-وعليه-فاىتة-ايهما-يقدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا ضاق وقتُ الحاضرة وعليه فائتة.mp3","categories":["قضاء الفوائت"]},{"id":4825,"question":"مَن كان يُصلي العصر، فتذكَّر صلاةً فائتةً قد نسيها ماذا يعمل؟ سواء كانت مماثلةً لصلاة العصر في العدد، أو أقلّ في المغرب والعشاء؟","title":"ماذا يعمل من تذكَّر صلاةً فائتةً وهو يصلي فريضة؟","answer":"يقطعها، ويُحرم من جديدٍ بنية الفائتة، يقطع هذه، ويُكبر من جديدٍ بنية الفائتة، ويقضي ما فاته.","link":"https://binbaz.org.sa/fatwas/25234/ماذا-يعمل-من-تذكر-صلاة-فاىتة-وهو-يصلي-فريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دخل في الفريضة ثم تذكَّر صلاةً فائتةً قد نسيها فماذا يعمل؟.mp3","categories":["قضاء الفوائت"]},{"id":4882,"question":"هل تقدم الوصية على الدين؟","title":"هل يجوز تقديم الوصية على الدين؟","answer":"لا، الدين مقدَّم على كل شيء مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ [النساء:11] قضى النبي ﷺ بالدين قبل الوصية.","link":"https://binbaz.org.sa/fatwas/25387/هل-يجوز-تقديم-الوصية-على-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما يقدم الوصية أم الدين.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":5071,"question":"هل تُقْضَى سنة الفجر إذا فاتت، وكذلك الوتر؟","title":"ما حكم قضاء سنة الفجر والوتر؟","answer":"الجواب: نعم، إذا فاتت سنةُ الفجر تُقْضَى بعد الصلاة، أو بعد طلوع الشمس وارتفاعها، هذا هو السُّنة، هذا هو الأفضل.\nوهكذا الوتر: إذا فات في الليل السُّنة أن يُصلِّي المؤمنُ والمؤمنة في النهار مثلما كان يُصلي بالليل، لكن لا يُوتر، يشفع، إذا كان يُصلي خمسًا صلَّى ستًّا، بثلاث تسليمات، وإذا كان يُصلي ثلاثًا سلَّم تسليمتين، وإذا كان يُصلي سبعًا صلَّى ثمان ركعات، أربع تسليمات، وهكذا.\nتقول عائشةُ رضي الله عنها: \"كان النبيُّ ﷺ إذا شغله مرضٌ أو نومٌ عن وتره من الليل صلَّى من النهار ثنتي عشرة ركعة\"، وكان في الغالب ﷺ يُصلي إحدى عشرة ركعة في الليل، فإذا شُغل عن ذلك بنومٍ أو مرضٍ صلَّاها من النهار وشفعها، صلَّاها ثنتي عشرة ركعة، ست تسليمات، فهكذا غيره ﷺ إذا وقع له مثل ذلك: شُغِلَ عن الوتر بالليل لنومٍ أو مرضٍ يُصلي من النهار، ولكن يشفع، لا يُصلي وترًا، يشفع.","link":"https://binbaz.org.sa/fatwas/29382/ما-حكم-قضاء-سنة-الفجر-والوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم قضاء سنة الفجر والوتر؟.mp3","categories":["قضاء الفوائت"]},{"id":5322,"question":"ما هو القول الصحيح في الوصية الواجبة، ومن قال بالوصية الواجبة من العلماء؟","title":"ما حكم الوصية؟ ومتى تكون واجبة؟","answer":"الجواب: الوصية الواجبة من الحقوق التي عليه، يجب عليه أن يوصي بالديون التي ما عليها بيّنات؛ كفارات، حقوق عليه للناس، يلزمه أن يُوصِي بها. الحق الذي عليه لله أو لعباده يوصي به، وأما الوصية بالثلث، بطاعة الله، أو بالربع، أو بالخمس، هذه مستحبة.[1]","link":"https://binbaz.org.sa/fatwas/30985/ما-حكم-الوصية-ومتى-تكون-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 042.mp3","categories":["الوصايا","قضاء الصيام","قضاء الفوائت"]},{"id":5367,"question":"امرأة أُصيبت بمرض الضغط فجأةً، وارتفع لديها السكر كذلك، وبقيت في المستشفى قرابة ثلاثة أيام، وهي فاقدة للوعي، ثم خرجت من المستشفى، ولا تزال لا تستطيع أداء الصلوات الفائتة حتى مضت عليها عشرة أيام، وتُريد الآن قضاء ما فاتها، ولكنها لا تُحسن أداء الصلاة، فيلزم من أبنائها إرشادها داخل الصلاة، فهم يُخبرونها إذا حان الركوع والسجود، وهي كذلك إذا كانت في الصلاة لا تدري كم صلَّت من ركعةٍ، فهل عليها قضاء ما فاتها من الصَّلوات والحال هذه أو لا؟","title":"ما حكم قضاء الصلاة لمن زال عقله عدة أيام؟","answer":"الجواب: ما دام عقلها مختلًّا ما عليها شيء، إذا كان عقلها لا يزال ثلاثة أيام مختلًّا لا، الصواب أنه في حدود ثلاثة أيام الإغماء، وبعض أهل العلم قال: في حدود يوم وليلة فقط، إذا زاد صار حكمه حكم المجنون، أما ثلاثة أيام فالأحوط القضاء، كما يُروى عن عمار أنه أُغمي عليه ثلاثة أيام وقضى ، أما هذه إن كان عقلها رجع إليها بعد الثلاثة تقضي الثلاثة، أما إذا استمرت عشرة أيام وهي لا تُحسن فلا قضاءَ عليها. س: لكن كونها إذا أنهت الصلاة لا تدري كم صلَّت، ولا تعرف شيئًا؟ ج: هذا معناه أنه ما رجع عقلها إليها، ما زالت في إغمائها.[1]","link":"https://binbaz.org.sa/fatwas/31078/ما-حكم-قضاء-الصلاة-لمن-زال-عقله-عدة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima010.mp3","categories":["قضاء الفوائت"]},{"id":5384,"question":"المجنون والمُغمى عليه إذا أفاق بعد خروج الوقت هل يقضون الصلاة؟","title":"حكم قضاء الصلاة للمجنون والمُغْمى عليه","answer":"الجواب: المجنون لا، ما هو مُكلَّف، إن صار مجنونًا قبل دخول الوقت رُفع عنه التكليف، أما النائم يقضي، والمُغمَى عليه يشبه النائم، إذا أفاق يقضي في اليوم أو اليومين أو الثلاث، كما رُوي عن عمار بن ياسر  وجماعة، وقال بعض أهل العلم: إن أُغمي يومًا كاملًا فلا قضاء، وإن كان أقل من يوم يقضي، والأقرب -والله أعلم- أنه يشبه النائم، إذا كان يوم أو يومين أو ثلاث يقضي، وإن كان أكثر لا يقضي.[1]","link":"https://binbaz.org.sa/fatwas/31124/حكم-قضاء-الصلاة-للمجنون-والمغمى-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/majomo3_fatawa001.mp3","categories":["قضاء الفوائت"]},{"id":5581,"question":"قول بعض أهل العلم أنَّ مَن ترك الصلاة تعمدًا لا يقضيها؛ لقول الرسول ﷺ: مَن عمل عملًا ليس عليه أمرنا فهو ردٌّ، فتعمد تركها ترد عليه، لا يُصلي؟","title":"هل يقضي الصلاة مَن تركها تعمدًا؟","answer":"الجواب: هذا إن قلنا: كفر، فلا قضاء عليه، وإن قلنا: لم يكفر، يقضي؛ لأنَّه من باب إن كان يقضي مَن نام فالذي يتركها عمدًا من باب أولى أن يقضي، عند الجمهور يقضي. س: لو ترك حتى فرضًا واحدًا؟ ج: ظاهر الحديث عام، إذا تعمَّده حتى خرج الوقت.[1]","link":"https://binbaz.org.sa/fatwas/31538/هل-يقضي-الصلاة-من-تركها-تعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 021.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":5582,"question":"التحديد بثلاثة أيام ثابت عن الرسول ﷺ؟","title":"هل صح تحديد قضاء الفوائت بثلاثة أيام؟","answer":"الجواب: لا، هذا يُروى عن عمار  لما أُغمي عليه، وعن سمرة بن جندب ، وعن عمران ، ولم أقف على أسانيدها، لكن ذكروها عن الثلاثة، حتى الآن لم أقف على أسانيدها عنهم، لكنه قريب، قول قريب؛ لأنَّ ثلاثة أيام علّق بها أحكام، مثل: الخيار ثلاثة أيام، ومثل أشياء كثيرة علّق بها ثلاثة أيام؛ فالقول بها قريب؛ لأنَّ النوم قد يغلب على الإنسان، قد ينام يومًا أو يومين، قد ينام ثلاثة أيام. س: يُلحق بها الصيام إذا أُغمي عليه أكثر من ثلاثة أيام؟ ج: نعم، لا قضاءَ عليه. س: مَن فرَّق بين المُغمى عليه وبين النَّائم؛ هذا باختياره، وهذا بغير اختياره؟ ج: ما في شكّ، لكن يُشبهه بثلاثة أيام فأقلّ، يُشبه به. س: إذا لم يقضِ الصلاة للإغماء فكذلك الصيام؟ ج: لا يقضي صيامًا ولا صلاةً.[1]","link":"https://binbaz.org.sa/fatwas/31540/هل-صح-تحديد-قضاء-الفواىت-بثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 022.mp3","categories":["قضاء الفوائت"]},{"id":5587,"question":"مَن ذكر صلاة السفر حضرًا؟","title":"كيف يقضي صلاة السفر مَن ذكرها بالحضر؟","answer":"الجواب: يُصليها أربعًا، زال العذر.[1]","link":"https://binbaz.org.sa/fatwas/31546/كيف-يقضي-صلاة-السفر-من-ذكرها-بالحضر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 027.mp3","categories":["قضاء الفوائت"]},{"id":5605,"question":"الرجل الذي نام عن الصلاة أو نسيها تكون في حقِّه قضاءً أو أداءً؟","title":"هل تكون الصلاة قضاءً أم أداءً لمن نام عنها؟","answer":"الجواب: نعم، إن كان في الوقت فهو أداء، وإن كان في خارج الوقت يُسمَّى: قضاء، هذا أمر اصطلاحي، أمر سهل، المقصود البدار، الواجب عليه البدار، سواء سُمي: قضاء أو أداء، الأمر في هذا واسع.[1]","link":"https://binbaz.org.sa/fatwas/31572/هل-تكون-الصلاة-قضاء-ام-اداء-لمن-نام-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 045.mp3","categories":["قضاء الفوائت"]},{"id":5606,"question":"القول بأنَّ مَن ترك الصلاة متعمدًا لا يقضيها؟","title":"ما حكم قضاء الصلاة لمن تركها متعمدًا؟","answer":"الجواب: هذا شيء آخر، هذا ينبني على القول بالكفر: إذا تركها عمدًا؛ كَفَر ولا قضاء، إذا قلنا بكفره لم يقضِ، عليه التوبة فقط، أما إذا قلنا: لا يكفر، فعليه القضاء. أما النوم عن الصلاة فليس بكفرٍ، مَن نام عن الصلاة أو نسيها معذور، لكن لا يجوز التَّعمُّد، النبي ﷺ يقول: بين الرجل وبين الكفر والشرك ترك الصلاة، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر نسأل الله العافية. س: مَن ترك الصلاة عمدًا؟ ج: يكفر، يكفر. س: ولا يقضي؟ ج: إن قضى خروجًا من الخلاف لا بأس، وإن لم يقضِ فلا قضاءَ عليه، وإن قضى خروجًا من خلاف العلماء احتياطًا لدينه فلا بأس. س: المختار أنه يقضي؟ ج: إن قضى احتياطًا فلا مانع.[1]","link":"https://binbaz.org.sa/fatwas/31573/ما-حكم-قضاء-الصلاة-لمن-تركها-متعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 046.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":5607,"question":"بعض الناس يقول: إذا فاته الظهر وتذكر بالليل لا يقضي إلا في موعدها؟","title":"ما صحة القول بقضاء الصلاة في نفس وقتها؟","answer":"الجواب: لا، غلط، النبي عليه السلام قال: مَن نام عن الصلاة أو نسيها فليُصلها إذا ذكرها، ما بعد كلام النبي ﷺ شيء. س: استدل بقوله عليه الصلاة والسلام: إنَّ لله عملًا بالنهار لا يقبله..؟ ج: لا، هذا كلام باطل، هذا تشبيه، النبي عليه الصلاة والسلام كلامه صريح: مَن نام عن صلاة أو نسيها فليُصلها إذا ذكرها.[1]","link":"https://binbaz.org.sa/fatwas/31574/ما-صحة-القول-بقضاء-الصلاة-في-نفس-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 047.mp3","categories":["قضاء الفوائت"]},{"id":5608,"question":"لو ذكر في أثناء صلاة العصر أنه ما صلَّى الظهر؟","title":"حكم مَن ذكر في الفريضة أنه ما صلى التي قبلها","answer":"الجواب: يقطعها ويُصلي الظهر، ينويها الظهر، يُغير النية. س: يستأنف؟ ج: يستأنف نعم. س: بعد القطع تغيير النية؟ ج: يستأنف وينوي بالصلاة الحاضرة الظهر، ثم يُصلي العصر. س: يقطعها؟ ج: بالنية، بالنية وهو في مكانه، في وقفته يقطعها ويُكبر ناويًا الظهر، ويُكمل مع الإمام، ويقضي ما فاته، ثم يُصلي العصر بعد ذلك. س: يقطعها ثم يُكبر؟ ج: يُكبر تكبيرًا جديدًا بنية الفائتة ويُكمل، ثم يأتي بالجديدة. س: نية وتكبيرة جديدة؟ ج: نعم، نية وتكبيرة جديدة؛ لأنه قطع الأولى.[1]","link":"https://binbaz.org.sa/fatwas/31575/حكم-من-ذكر-في-الفريضة-انه-ما-صلى-التي-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 048.mp3","categories":["قضاء الفوائت"]},{"id":6013,"question":"أنا شاب تبت إلى الله، ولكن ضيعت كثيرًا من الصلوات قبل التوبة، فما حكم الصلاة الفائتة؟","title":"حكم قضاء الصلوات التي تركت عمداً قبل التوبة","answer":"الجواب:  إذا كان الإنسان لا يصلي، ثم هداه الله، ومنَّ عليه بالتوبة، وأقبل على الله، وصلى؛ فإن التوبة تجب ما قبلها، والحمد لله، وتهدم ما قبلها، ولا إعادة عليه، ولا قضاء عليه، هذا هو الأرجح، والصواب من قولي العلماء. التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله، كما قال الله : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] والنبي -عليه الصلاة والسلام- قال: الإسلام يهدم ما كان قبله، والهجرة تهدم ما كان قبلها، والحج يهدم ما كان قبله، والتوبة تهدم ما كان قبلها. هذا هو الصواب: أنه لا قضاء عليه؛ لأن ترك الصلاة كفر، فإذا تاب إلى الله، ورجع إلى الحق، والصواب؛ فتوبته تجب ما قبل ذلك.","link":"https://binbaz.org.sa/fatwas/1401/حكم-قضاء-الصلوات-التي-تركت-عمدا-قبل-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_356.mp3","categories":["قضاء الفوائت","الرقائق"]},{"id":6206,"question":"إذا لم أذكر الوتر إلا بعد يومين، أو ثلاثة، فماذا أفعل فيه؟","title":"كيفية قضاء من نام عن الوتر أو نسيه","answer":"الجواب: إذا نام عن الوتر، أو نسيه؛ شرع له أن يصلي من الضحى ما تيسر، فإذا ذهب الضحى؛ زالت السنة، ولم يبقَ عليه شيء، ولكن يشرع له أن يتعوض عنه بالضحى إذا نسيه بالليل؛ صلى من الضحى ركعات؛ هذه السنة. وإذا فاته  الوتر؛ يسن له أن يصلي في الضحى ما يقابل ذلك، لكن يشفع صلاته، ولا يوتر، قالت عائشة -رضي الله عنها-: كان النبي ﷺ إذا شغله عن وتره نوم، أو مرض؛ صلى من النهار ثنتي عشرة ركعة وكان وتره في الغالب إحدى عشرة ركعة -عليه الصلاة والسلام- فإذا نام عنه، أو شغله عنه مرض؛ صلى من النهار ثنتي عشرة ركعة، يعني ست تسليمات، هذا هو الأفضل. إذا كنت تصلي من الليل خمس ركعات، وفاتك الوتر لنوم، أو مرض، تصل من النهار ست ركعات؛ زيد واحدة، ثلاث تسليمات، وإذا كانت عادتك سبع  ركعات؛ توتر بها، تصلي من النهار ثمان ركعات، أربع تسليمات، وإذا كانت عادتك ثلاث ركعات؛ توتر بها في الليل، ألهيت عنها، أو شغلت عنها بمرض، تصلي من النهار أربع ركعات تسليمتين، ومن زاد؛ فلا بأس، من زاد على هذا؛ فهو خير، وهذا يكون قبل الظهر، فإذا فاته هذا الوقت؛ فالظاهر أنه سنة فات محلها.","link":"https://binbaz.org.sa/fatwas/1643/كيفية-قضاء-من-نام-عن-الوتر-او-نسيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_556.mp3","categories":["الوتر وقيام الليل","قضاء الفوائت"]},{"id":6782,"question":"إذا كان الميت في مرض موته لم يتمكن من أداء فروض صلاته لعدم استطاعته، هل تقضى عنه بعد وفاته؟","title":"حكم قضاء الصلاة عن الميت","answer":"الجواب: يغلط بعض الناس في هذا مثل ما سمعتم في الندوة، بعض الناس إذا مرض يتساهل في الصلاة، ولا يصلي، يقول: إذا شفيت؛ أقضي، وهذا غلط، قد يموت في المستشفى، هذا غلط، الواجب عليه أن يصلي على حسب حاله قائمًا، أو قاعدًا، أو على جنبه، أو مستلقيًا كما سمعتم في المحاضرة، هكذا أمر النبي ﷺ وإن عجز عن الماء؛ يصلي بالتيمم، وإذا كان ما تيسر له التيمم، ولا الماء؛ صلى على حسب حاله، ولو أن ثيابه نجسة.. يصلي على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إن استطاع الوضوء؛ توضأ، التيمم تيمم، إن استطاع يغير ثيابه؛ غير ثيابه، إن استطاع يغير مصلاه؛ غير مصلاه.  أما أن يتساهل، ويقول: بعدين إذا عافاني الله أصلي؛ هذا غلط، لا يجوز، النبي ﷺ قال للمريض: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا والذي لا يجد الماء؛ يتيمم، والعاجز يتيمم، ليس له عذر، هذا غلط.  فالواجب على المسلم أن ينبه إخوانه في مثل هذا، إذا زار أخاه المريض ينبهه على هذه المسائل، يقول له، إذا كان يخشى أنه يغلط في هذا؛ ينبهه، ويبين له حتى يكون هذا من باب التعاون على البر، والتقوى، وإذا مات، ولم يصل؛ ما عليه قضاء، يدعى له بالمغفرة، والعفو؛ لأنه تركها لشبهة، يصير جاهلًا، يظن أن هذا هو الأفضل، فليس في حكم من تعمد تركها مكابرة، أو تساهلًا، بعض الناس يتركها، يظن أن هذا هو المشروع، وأنه إذا صلاها بعد المرض يكون أحسن.. أكمل، وهذا من الجهل العظيم، والله المستعان. السؤال: إذا تركها ...  الجواب: كل هذا غلط. الطالب: لكن تركها، ومات وهو..؟ الجواب: لا ما تقضى عنه، لكن -إن شاء الله- يرجى له العفو من الله. الطالب: إذا كان ترك الصلاة عامدًا متعمدًا..؟ الجواب: إذا كان تساهلًا؛ يكون كافرًا -نعوذ بالله- لا يغسل، ولا يصلى عليه، أما إذا كان قصده أنه نجس، ويرى أن تأخيرها أفضل لجهله هذا ...","link":"https://binbaz.org.sa/fatwas/2631/حكم-قضاء-الصلاة-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1127.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":7462,"question":"هنا رسالة من السودان وردت من الأخ المخلص محمد علي عبد الله، يقول فيها: إنه تعود أن يصلي نفل بعد المغرب ست ركعات، يقول: ولكني أصليهم بسورة الفاتحة فقط، هل هذا يجوز أم لا؟","title":"حكم صلاة ست ركعات بعد المغرب؟","answer":"الجواب: المشروع بعد المغرب ركعتان فقط الراتبة، فمن صلى بعدها زيادة ستاً أو ثماناً أو عشراً أو أكثر فلا حرج عليه، لكن بعض الناس قد يظن أن للست خصوصية، وهذا لا أصل له، ولم يثبت في حديث عن النبي ﷺ يدل على ذلك وإن اعتاده بعض الناس، فالست ليس لها خصوصية، و ليس لها أصل يعتمد عليه في الأحاديث الصحيحة، ولكن من فعلها لمزيد الخير ولمزيد العبادة، صلى ستاً أو ثماناً بعد المغرب أو عشراً فلا حرج عليه، ليس في حد محدود، بين العشاءين محل صلاة ومحل عبادة، ولكن الراتبة فقط ركعتان، التي كان يحافظ عليها النبي ﷺ ركعتان فقط، هذه الراتبة، فمن زاد وصلى أكثر من ذلك فلا حرج عليه ولا بأس عليه. المقدم: لكن تجزئ بسورة الفاتحة فقط؟\nالشيخ: يجزئ بسورة الفاتحة نعم، لو صلى بالفاتحة فقط أجزأت؛ لكن الأفضل أن يقرأ مع الفاتحة ما تيسر: آية أو آيتين أو سورة قصيرة، هذا هو الأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/4180/حكم-صلاة-ست-ركعات-بعد-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_001/00104.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":7498,"question":"سؤاله الأخير يقول: ما حكم من ترك خمس صلوات لعذر؛ كعدم الطهارة مثلاً، وكيف يقضي هذه الصلوات، وكيف تقضى إذا كانت أكثر من خمس صلوات، وكذلك كيف تقضى إذا كانت أقل؟ أفيدونا جزاكم الله خير الجزاء.","title":"حكم ترك الصلاة لعذر وكيف تقضى","answer":"الجواب: كثير من المرضى قد يجهل الحكم الشرعي في الصلاة فيتساهل ويؤخر الصلوات، يرجو بزعمه أنه يعني: يشفى حتى يقضيها على حال أحسن، وهذا غلط، لا يجوز للمريض أن يؤخر الصلوات بل يصليها على حسب حاله، فإن الرسول ﷺ قال لـعمران لما اشتكى مرض البواسير، قال: صل قائماً،، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً» فأمره ﷺ بأن يصلي على حسب حاله ولم يسمح له بالتأخير؛ ولأن الصلاة واجبة في وقتها فلا يجوز تأخيرها عن وقتها، لكن يجوز له الجمع بين الظهر والعصر، بين المغرب والعشاء لمرض، كما يجمع المسافر، أما تأخيرها عن وقتها بالكلية، تأخير مجموعتين عن وقتهما وتأخير الفجر عن وقتها، هذا لا يجوز، بل يجب عليه أن يصلي في الوقت ولو على جنبه ولو مستلقياً؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. والنبي عليه السلام يقول: إذا أمرتكم بأمر فأتوا منه ما استطعتم فينبغي التنبه لهذا وتنبيه الناس على هذا الشيء، ينبغي لكل مؤمن ولكل مؤمنة التنبه لهذا الأمر وتنبيه الناس على هذا الأمر، وأن المريض لا يجوز له التأخير بل يجب عليه أن يصلي الصلاة في وقتها، سواء كان قائماً، أو قاعداً، أو على جنبه، أو مستلقياً، على حسب قدرته: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nوإذا عجز عن الصلاة بالماء صلى بالتيمم، كأن يشق عليه استعمال الماء لأجل المرض استعمل التيمم، يعني: تيمم بالتراب تعفر بالتراب، يضرب التراب بيديه فيمسح بهما وجهه وكفيه، ويقوم مقام الماء عند العجز عن الماء، أو عند العجز عن استعماله لمرض والحمد لله، وهكذا لو كانت ملابسه، أو كان فراشه فيه نجاسة، ولم يتيسر له غسل الملابس ولا إبدالها، ولم يتيسر له غسل الفراش ولا إبداله، يصلي على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وصلاته صحيحة، لكن لو أخر جهلاً منه فإنه يقضيها بالترتيب ولو في لحظة واحدة، يقضيها بالترتيب؛ يصلي الفجر الظهر العصر المغرب العشاء مرتبة، ولو صلاها في وقت واحد في الحال فهذا طيب، فالمقصود الواجب عليه البدار والمسارعة إلى القضاء ولا يؤخر ولا يؤجل بعدما يقوى على ذلك.","link":"https://binbaz.org.sa/fatwas/4459/حكم-ترك-الصلاة-لعذر-وكيف-تقضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_007/00703.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":7566,"question":"هذه الرسالة وردت للبرنامج من الأخ أحمد محمد الصادق من جدة العمارية، يقول: ما حكم صلاة السجود في الليل، نرجو الإفادة عن ذلك؟","title":"فضل السجود","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: هذا السؤال فيه إجمال، وهو ما حكم صلاة السجود في الليل؟\nيحتمل أن مراده بذلك يعني ما حكم الصلاة التي يكثر فيها السجود ولا تطول فيها القراءة، ويحتمل أنه أراد معنى آخر لم أفهمه، فإن كان يسأل عن الأول فقد جاء عن النبي ﷺ ما يدل على شرعية الإكثار من الصلوات وأنها من أسباب دخول الجنة، وأن العبد ما سجد سجدة إلا رفعه الله بها درجة، وفي حديث ربيعة بن كعب الأسلمي قال: قلت يا رسول الله! لما قال له الرسول ﷺ: سل -كان يخدم النبي صلى الله عليه وسلم- قال: أسألك مرافقتك في الجنة، فقال: أعني على نفسك بكثرة السجود يعني: بكثرة الصلاة. \nفكثرة الصلاة يلزم منها كثرة السجود، والسجود فيه خشوع لله وتعظيم لله عز وجل، فهو من أسباب رفع الدرجات وحط الخطيئات، ومن أسباب دخول الجنة والنجاة من النار، ومن أسباب حصول الشفاعة من النبي ﷺ لصاحبه إذا كان موحداً مسلماً، وصح عنه عليه الصلاة والسلام أنه قال: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، رواه مسلم في الصحيح، وقال أيضاً عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، فهذا يدل على أن السجود له شأن، وأن العبد أقرب ما يكون من ربه في حال سجوده؛ لأن السجود حالة خضوع، حالة ذل لله وانكسار بين يديه سبحانه وتعالى، يضع وجهه الذي هو أشرف أعضائه الظاهرة يضعه في الأرض خاضعاً لربه، مطمئناً خاشعاً، يرجو ثوابه ويخشى عقابه، فهو في هذه الحالة في غاية الذل والانكسار، فهو أقرب ما يكون إلى الله جل وعلا، ولهذا قال عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، فدل ذلك على أن الدعاء في السجود دعاء مطلوب، وأن صاحبه حري بالإجابة، وصح عنه ﷺ في حديث ثوبان: أن العبد إذا ما سجد لله سجدة إلا رفعه الله بها درجة وحط بها عنه خطيئة، فينبغي الإكثار من الصلوات في الليل، وفي النهار، كالضحى، والظهر، وفي الليل بين العشاءين، وبعد العشاء، وفي جوف الليل، وفي آخر الليل، كل هذه أوقات عظيمة ينبغي فيها الإكثار من الصلاة ولاسيما في الليل، فإن الليل الصلاة فيه أفضل من الصلاة في النهار، وأقرب إلى الخشوع وهدوء القلب، كما يقول جل وعلا: إِنَّ نَاشِئَةَ اللَّيْلِ هِيَ أَشَدُّ وَطْئًا وَأَقْوَمُ قِيلًا [المزمل:6]، الصلاة في الليل لها شأن، والإنسان فيها أقرب ما يكون إلى الخشوع والذل بين يدي الله، ولاسيما في جوف الليل وفي آخر الليل، فينبغي الإكثار من الصلوات في الليل وفي النهار، ويختمها في الليل بالوتر، إذا صلى ما كتب الله له من الصلوات ختمها بالوتر، وأفضل ما يكون إحدى عشرة ركعة أو ثلاثة عشر ركعة كفعل النبي عليه الصلاة والسلام، وإن صلى أقل من ذلك كخمس أو سبع فلا بأس، النبي صلى الله عليه وسلم كان يتنوع في صلاته، ربما أوتر بخمس، وربما أوتر بسبع، ربما أوتر بتسع، ربما أوتر بإحدى عشرة وهو الأغلب، وربما أوتر بثلاث عشرة، فالأمر في هذا واسع، وإن صلى في الليل عشرين ركعة، أو ثلاثين ركعة، أو أربعين ركعة، أو مائة ركعة وختم بالوتر، فكل هذا لا بأس به. \nالنبي ﷺ سئل عن صلاة الليل فقال: مثنى مثنى، فلم يحد حداً عليه الصلاة والسلام، ما قال عشر ولا عشرين بل أطلق، فالإنسان يصلي في الليل ما بدا له ولو مائة ركعة، لكن من دون مشقة على نفسه مع الرفق بنفسه، ومع الطمأنينة وعدم العجلة، ثم يختم بالوتر، ولهذا قال عليه الصلاة والسلام: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة وتر وله ما قد صلى، فيصلي ما كتب الله له في الليل، ولا يسهر بل ينام ويصلي، هذه السنة حتى لا يتعب في النهار، وحتى يتفرغ لأعماله النهارية وعباداته النهارية، فيصلي ما كتب الله له في الليل، في أول الليل، أو في جوفه، أو في آخره، والآخر أفضل إذا تيسر، ثم يوتر بواحدة ركعة واحدة، هذا هو الأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/4571/فضل-السجود ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01601.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":7567,"question":"سؤاله الثاني يقول: ما حكم صلاة الضحى، هل هي سُنة أم واجبة؟ أفيدونا جزاكم الله خير الجزاء، ونتمنى لكم التوفيق؟","title":"هل صلاة الضحى سُنة أم واجبة؟","answer":"الجواب: صلاة الضحى سنة وليست بواجبة الرسول ﷺ لما سئل عن الصلوات الخمس الظهر والعصر والمغرب والعشاء والفجر؟ قال السائل: هل علي غيرها؟ قال له النبي ﷺ: لا إلا أن تطوع ليس عليه غير الخمس في اليوم والليلة إلا أن يطوع، فصلاة الضحى والرواتب التي مع الصلوات الخمس، وصلاة الليل كلها مستحبة، حتى الوتر مستحب على الصحيح، الوتر سنة مؤكدة وليس بواجب عند جمهور أهل العلم. نعم.","link":"https://binbaz.org.sa/fatwas/4572/هل-صلاة-الضحى سنة-ام-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01602.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":7571,"question":"هذه الرسالة من المستمع من حوطة بني تميم من زيد عبد العزيز القرش، يقول: أرجو الإجابة على سؤالي هذا، وهو: إذا تأخر الواحد عن صلاة الفجر مع الجماعة بسبب نوم أو غيره، فمتى تكون ركعتي السنة قبل أو بعد صلاة الفجر، ولكم شكري وخالص تحياتي؟","title":"ما وقت قضاء سنة الفجر لمن فاتته؟","answer":"الجواب: إذا تأخر الإنسان عن الجماعة في صلاة الفجر ولم يدرك الجماعة فإنه يبدأ بالسنة الراتبة يصليها ثم يصلي الفريضة، النبي ﷺ لما نام ذات ليلة عن صلاة الفجر في السفر ولم يوقظه إلا حر الشمس، صلى النبي الراتبة ثم صلى الفجر عليه الصلاة والسلام، وأمر بالأذان والإقامة كالعادة، فالإنسان إذا فاتته صلاة الفجر فلم يستيقظ إلا بعدما صلى الناس، أو جاء إلى المسجد وقد صلى الناس فإنه يصلي الراتبة ثنتين ركعتين ثم يصلي الفريضة، هذا هو السنة، ولو أخرها وصلاها بعد الصلاة أو بعد طلوع الشمس فلا بأس، ولكن الأولى والأفضل أن يبدأ بها كما بدأ بها النبي ﷺ لما فاتته الصلاة في بعض أسفاره، وإذا صلى مع الجماعة جاء وهم يصلون صلى معهم وهو ما صلى الراتبة فإنه يصليها بعد الصلاة إن شاء، أو يصليها بعد ارتفاع الشمس وهو أفضل، لأنه جاء بهذا حديث وبهذا حديث، فهو مخير، إن شاء صلاها بعد صلاة الفجر في المسجد أو في بيته، وإن شاء صلاها بعد ارتفاع الشمس، كل ذلك بحمد الله موسع، وكل ما جاء به حديث جيد عن النبي عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/4577/ما-وقت-قضاء-سنة-الفجر-لمن-فاتته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01607.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":7746,"question":"ونبدأ برسالة المستمع سليمان محمد التميمي الرياض، يقول:إذا قمت لصلاة الصبح فشكيت هل أديت صلاة العشاء؟ فما الحكم إذا كان الراجح عندي أني صليت، وإذا كان الراجح أني لم أصل، وإذا تساوى الأمران؟","title":"حكم من شك في صلاة أنه أداها أو لم يؤدها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nالذي يظهر أن الشرع المطهر أن الإنسان إذا شك هل أدى واجب أو لم يؤده؛ أن عليه أن يؤدي الواجب، إذا كان من عادته أنه قد يتساهل فيها وقد يضيعها وقد يتساهل فيها؛ فالذي ينبغي له أن يبادر بقضائها أولاً ثم يصلي الفجر، أما إذا كان لا ليس من عادته ذلك بل يصلي الصلاة في وقتها مع المسلمين أو في وقتها في البيت لديه بعض الأعذار، وإن كان لا يجوز أن يصليها في البيت، فالواجب على المسلم أن يصليها في الجماعة في المساجد، ولا يجوز لأحد أن يصليها في البيت إلا من عذر شرعي كالمرض أو الخوف الذي يمنعه من الخروج كأن يخشى على نفسه، لكن إذا كان من عادته أنه يصليها مع الجماعة أو يصليها في البيت لعذر من الأعذار فلا ينبغي أن ينظر إلى هذا الشك، بل ينبغي أن يطرح هذا الشك ولا يلتفت إليه، أما إذا كان تارة وتارة، قد يؤخرها وقد يمسي وما فعلها، وقد يشغل عنها، فإذا كان ما تحقق ولا جزم أنه فعلها فليقضها ثم يصلي الفجر بعد ذلك، أما إذا كانت أوهام وظنون لا أساس لها بل من عادته ومن طريقته العناية بها وفعلها في وقتها والصلاة كما شرع الله؛ فهذه وساوس لا يلتفت إليها ولا يعمل بها بل يصلي الفجر ويحمل أمره على أنه فعلها والحمد لله كعادته المتبعة. نعم.","link":"https://binbaz.org.sa/fatwas/4943/حكم-من-شك-في-صلاة-انه-اداها-او-لم-يودها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_042/04201.mp3","categories":["قضاء الفوائت"]},{"id":7749,"question":"هذه رسالة وردت من المستمع محمد أحمد محمد الشمراني من بلاد شمران باشوت يقول: الحمد لله رب العالمين، والصلاة والسلام على أشرف الأنبياء وخاتم النبيين وبعد: فأبعث لكم برسالتي هذه أرجو من الله ثم منكم عرضها على فضيلة الشيخ عبد العزيز بن باز، نقول لك محمد: الآن يجيب على رسالتك الشيخ عبد العزيز بن باز.والسؤال الأول: لقد دار نقاش بين اثنين عما إذا كانت الصلاة تقضى، فهل تقضى مع العلم أنه لا يعرف كم عدد الفروض التي تركت؟","title":"حكم قضاء الصلاة المتروكة","answer":"الجواب: إذا كان الإنسان ترك الصلاة عمداً فإنه يكفر بذلك كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، وقال عليه الصلاة والسلام: رأس الأمر الإسلام، وعموده الصلاة، وذورة سنامه الجهاد في سبيل الله، وقال أيضاً عليه الصلاة والسلام: من حافظ على الصلاة كانت له نوراً وبرهاناً ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور ولا برهان ولا نجاة، وكان يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف نسأل الله العافية، هؤلاء من كبار الكفار ومن صناديدهم، فالذي يضيع الصلاة يحشر مع هؤلاء، وذلك يدل على كفره العظيم؛ لأنه إن ضيعها شغلاً بالرياسة فقد أشبه فرعون ، وإن ضيعها شغلاً بالوزارة والوظيفة فقد شابه هامان وزير فرعون ، وإن ضيعها شغلاً بالمال والشهوات فقد شابه قارون الذي خسف الله به وبداره الأرض بسبب استكباره عن الحق واشتغاله بالشهوات، وإن تركها تشاغلاً بالمعاملات والبيع والشراء فقد شابه أبي بن خلف تاجر أهل مكة، فيكون كافراً محشوراً مع هؤلاء الكفرة نسأل الله العافية.\nفالحاصل أن تركها كفر فلا تقضى، إذا أسلم وهداه الله وتاب ليس عليه قضاء هذا هو الصواب، ليس عليه قضاؤها ولا قضاء غيرها كالصوم وغيره، إذا تاب بعد ذلك فإن التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله كما قال الله سبحانه: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، فالتائب من تركه للصلاة ليس عليه قضاء؛ لأنه أسلم من جديد، هذا هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/4946/حكم-قضاء-الصلاة-المتروكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_042/04204.mp3","categories":["قضاء الفوائت"]},{"id":7773,"question":"هذا يقول: أنا رجل مريض بداء السكري، وآخذ عنه علاج، وأحياناً ينزل السكر تحت المعدل ثم أصاب بإغماء في النوم، وإذا قمت ما أدري هل أنا في اليوم الذي نمت فيه أو بعده بيوم، فأسأل عشيرتي ويخبروني بنفس اليوم الصحيح، فأصلي مجتهداً، ولكني لا أضبط صلاتي من حيث عدد الركعات، فهل هذه الصلوات صحيحة أو أعيدها إذا صحيت جداً، وشكراً (س. م. ت) الرياض؟","title":"حكم من فاتته الصلاة بسبب الإغماء","answer":"الجواب: الواجب على من يصاب بالإغماء أنه إذا انتبه واستيقظ وزال إغماؤه يقضي، إذا كان مدة الإغماء قليلة كاليوم واليومين والثلاثة، وقد جاء عن بعض الصحابة أنهم أغموا كـعمار وغيره فقضوا الصلوات، فهو إذا انتبه وزال إغماؤه يقضي ما مضى، لكن لا يعجل حتى يؤول إليه عقله، حتى يعني: يثبت عقله، لا يعجل وهو ما بعد ما ثبت عقله حتى لا يميز بين الركعات، لا، لا يعجل، حتى يعني يستقيم عقله، حتى يستطيع أن يؤدي الصلوات مضبوطة.\nأما إذا أداها وعقله حتى الآن ما يميز بين الركعتين والثلاث، فهو حتى الآن ما بعد استقام عقله، ولا تصح صلاته إنما عليه التأني والتثبت، فإذا أتم حضور عقله واستقام أمره قضى الأيام التي أخبره إخوانه الذين عرفوا حاله أنه ضيعها. نعم.\nالمقدم: لكن بالنسبة لصلواته التي صلاها وهو لم يصح من الإغماء هل يعيدها؟\nالشيخ: يعيدها، نعم الصلوات التي صلاها بدون شعور ما ضبطها يعيدها. نعم.\nالمقدم: وإن كان لا يعلم هل هي ظهر أو عصر؟\nالشيخ: يتحرى بالظن، ويعيد. نعم.\nالمقدم: أحسنتم، أثابكم الله!","link":"https://binbaz.org.sa/fatwas/4980/حكم-من-فاتته-الصلاة-بسبب-الاغماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_046/04603.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":8033,"question":"أيضاً تقول في رسالتها: ما حكم أو ما الحكم في الفروض التي فاتت من المدة التي ذكرت لكم، أفيدوني وفقكم الله؟","title":"حكم من ترك عدة صلوات اعتقادًا بسقوطها لمرضه","answer":"الجواب: الواجب أن تصلي، الواجب على السائلة أنها تصلي دائماً؛ لأن منع الماء ما يمنع الصلاة، فإذا كانت ضيعت بعض الفروض فعليها قضاؤها؛ لأن الماء إذا لم يتيسر يصلي المسلم بالتيمم، يضرب التراب ويمسح وجهه وكفيه بنية الطهارة من الأحداث الصغرى والكبرى ويصلي، وليس له عذر في ترك الصلاة بسبب عدم الماء، الحمد لله الماء له بدل والبدل هو التيمم كما قال جل وعلا: وَإِنْ كُنتُمْ مَرْضَى أَوْ عَلَى سَفَرٍ أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ أَوْ لامَسْتُمُ النِّسَاءَ فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43].\nفالمسلم إذا عجز عن الماء يتيمم الصعيد الطيب ويصلي هذا هو الواجب على المريض وفاقد الماء التيمم، فيتيمم ويصلي ما وجب الله عليه، فإذا كنت -أيها السائلة- قد فرطت في شيء من الصلوات فعليك أن تصلي ما فرطت فيه.. جميع الأوقات التي تركتي عليك أن تصليها جميعاً أن تقضيها. نعم.","link":"https://binbaz.org.sa/fatwas/5654/حكم-من-ترك-عدة-صلوات-اعتقادا-بسقوطها-لمرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08003.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":8064,"question":"هذه الرسالة وردت من عدة أشخاص يقولون: إلى فضيلة الشيخ المجيب على أسئلة السادة المستمعين وفقكم الله، الأسئلة المرجو أن تفيدونا عنها، السؤال الأول: إذا فاتت شخص فرض فهل يجوز قضاء هذا الفرض مع الفرض الثاني؟ وهل يجوز صلاة الفجر بعد طلوع الشمس؟ وهل يجوز قراءتها سراً أو جهراً أفيدونا هذا السؤال جزاكم الله خير، ومرسله المستمع محمد عبد الله حسن كريري؟","title":"هل يجوز صلاة الفجر بعد طلوع الشمس؟","answer":"الجواب: إذا فات المؤمن بعض الصلوات؛ لنوم أو نسيان؛ فإن الواجب عليه البدار بقضائها، ولا يؤخر ذلك إلى صلاة أخرى، بل الواجب البدار بالقضاء حالاً؛ لقول النبي ﷺ: من نام عن الصلاة أو نسيها؛ فليصلها إذا ذكرها لا كفارة له إلا ذلك هكذا قال النبي ﷺ، فالواجب البدار إلى أن يؤدي الصلاة التي نام عنها أو نسيها، وليس لها وقت نهي، فلو نسي الظهر فلم ينتبه لها إلا العصر، بادر وصلاها وصلى العصر، ولو نسي العصر فلم ينتبه لها إلا عند الغروب بادر، وهكذا لو نسى المغرب أو العشاء ثم ذكرها في أثناء الليل بادر وسارع إلى ذلك، ولا يؤخر إلى صلاة أخرى، بل هذا واجب عليه، وليس له تأخير الصلاة إذا ذكرها، وليس له تأخير الصبح إلى بعد طلوع الشمس لا يجوز؛ لا للرجال ولا للنساء، بل الواجب أن تصلى في الوقت، الرجل يصليها في الجماعة، ويخرج إلى المساجد في بيوت الله جل وعلا مع المسلمين، والمرأة تصليها في البيت في وقتها قبل الشمس، ولا يجوز لمسلم ولا لمسلمة تأخير صلاة الفجر إلى بعد طلوع الشمس؛ لأن حد الوقت طلوع الشمس، فإذا طلعت الشمس خرج الوقت، فلا يجوز للمسلم أبداً أن يؤخرها إلى طلوع الشمس، ولا للمسلمة أيضاً، بل هذا من عمل المنافقين نعوذ بالله، والله يقول جل وعلا: فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا [مريم:59] يعني: خساراً ودماراً، وقيل إن الغي وادٍ في جهنم، بعيد قعره خبيث طعمه نسأل الله العافية، قال ابن عباس في هذا: «ليس المراد أنهم تركوها لو تركوها لكفروا ولكن أخروها عن وقتها »، فهذا الوعيد لمن أخرها عن الوقت نسأل الله السلامة، أما من تركها فإنه يكفر، من تركها بالكلية يكون كافراً بذلك نعوذ بالله كما تقدم.\nفالحاصل أنه لا يجوز لأي مسلم، ولا لأي مسلمة تأخير الصلاة عن وقتها، لا الفجر إلى طلوع الشمس، ولا الظهر إلى وقت العصر، ولا العصر إلى وقت المغرب، ولا إلى أن تصفر الشمس، ولا المغرب إلى أن يغيب الشفق، ولا العشاء إلى نصف الليل، بل يجب أن تصلى كل صلاة في وقتها، هذا الواجب على المسلمين الرجال والنساء، الرجل يصليها في الجماعة مع المسلمين، وليس له تأخيرها عن الجماعة، وليس له تأخيرها عن الوقت، والمرأة عليها أن تصليها في الوقت في بيتها، وليس لها أن تؤخرها عن الوقت، وإذا كان النوم قد يغلب في الفجر، فينبغي أن توضع ساعة الساعة المنبهة، وتؤكد الوقت، حتى إذا جاء الوقت نبهتهم على وقت الصلاة؛ لأن هذا من الأسباب التي تعين على الخير، وإذا كان عنده من يوقظه فالحمد لله، فالحاصل أن الواجب على المسلم والمسلمة أن يهتما بهذا الأمر، فإن كان عندهما من يوقظهما لصلاة الفجر فالحمد لله، وإلا وجب أن يضعا ساعة عندهما للتنبيه على وقت الصلاة، حتى يقوم الرجل فيصلي مع المسلمين، وحتى تقوم المرأة فتصلي الصلاة في وقتها، هذا هو الواجب، وما أعان على الواجب وجب. نعم.","link":"https://binbaz.org.sa/fatwas/5861/هل-يجوز-صلاة-الفجر-بعد-طلوع-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_083/08306.mp3","categories":["قضاء الفوائت"]},{"id":8066,"question":"أشار محمد بن عبد الله حسن كريري إلى عادة اعتادها كثير من الناس، وهي: إذا فاتته الصلاة عن وقتها، تركها إلى أن يأتي وقت الثانية، مثلاً إذا فاتته الظهر يتركها للظهر اليوم التالي، هل لهم شيء يتعلقون به؟","title":"حكم تأخير الصلاة الفائتة إلى وقتها من اليوم التالي","answer":"الجواب: لا هذا جهل من قول بعض العامة، لا أصل له، لا يجوز تأخيرها إلى وقت آخر ولو قريب، إذا فاتته الظهر ليس له أن يؤخرها إلى وقت العصر، ولا إلى الظهر الآتي، بل يجب أن يبادر بها إذا تنبه وذكر، متى تنبه وجب أن يفعلها كما تقدم، وليس له تأخيرها متى ذكر. نعم.","link":"https://binbaz.org.sa/fatwas/5863/حكم-تاخير-الصلاة-الفاىتة-الى-وقتها-من-اليوم-التالي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_083/08308.mp3","categories":["قضاء الفوائت"]},{"id":8080,"question":"هذه الرسالة وردتنا من المستمع (ش. ع. ش) من الطائف يقول: والدي عمل عملية بالمستشفى وجلس في المستشفى أكثر من خمسة عشر يوم، ولم يصل أربع وأربعين فرض كانت قبل العملية، وقد اشتد عليه الوجع ولم يصل تلك الأربعة، وأما أربعين الفرض فهو كان في حالة بنج ولا يتمكن من الطهارة الكاملة التي تمكنه من أداء الصلاة. لذا أرجو إرشاده عن القضاء والكفارة، ماذا تقولون في ذلك وفقكم الله؟","title":"حكم المريض إذا ترك الصلاة أثناء مرضه","answer":"الجواب: إذا مات الميت وعليه صلوات لا تقضى عنه، ما شرع الله القضاء ولكن ينبغي لأهل المريض أن يلاحظوا تنبيهه على الصلاة، ويصلي على حسب حاله قاعداً أو قائماً أو على جنبه أو مستلقياًَ مثل ما أمر النبي ﷺ عمران بن حصين قال: صل قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً.\nفينبغي لأهل المريض أن يلاحظوا هذا ويشجعوا المريض ويوجهوه ويعلموه حتى يصلي على حسب حاله في المرض ولو كانت ملابسه نجسة إن تيسر غسلها أو إبدالها بغيرها فالحمد لله وإلا صلى على حسب حاله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16] وهكذا الفراش يصلي عليه ولو كان نجساً فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16] لكن إذا تيسر تغيير الفراش تغيير الملابس بشيء طاهر فهذا واجب، وإذا ما تيسر صلى على حسب حاله ولو ما توضأ ولو كانت الثياب فيها نجاسة وهكذا الفراش، وإن قدر على الوضوء أو التيمم وجب عليه ذلك، بدل الوضوء يحضر عنده الماء وتوضأ، وإن لم يقدر على استعمال الماء يحضر عنده بعض التراب حتى يتيمم، يتعفر يعني بوجهه وكفيه كما هو معروف، وإذا عجز عن هذا وعن هذا ولم يتيسر صلى على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16].\nولكن كثيراً من الناس لا يبالون بهذه المسائل، يتركون المريض، والمريض ربما يتأول أنه قد اشتد به المرض وأنه سوف يفعل إذا خف عليه المرض، وقد يأتيه الموت ولا يفعل، فلا ينبغي هذا بل يجب أن المريض يصلي على حسب حاله بالماء أو بالتيمم قائماً أو قاعداً أو على جنبه أو مستلقياً حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16] هذا هو الواجب، أما إذا كان شعوره قد تغير كأن أصابه ما يغير عقله فلا صلاة عليه، إذا تغير العقل فلا صلاة عليه، لكن مادام عقله معه فعليه الصلاة، وإذا أخذ البنج وتأخر صحوه من البنج يوماً أو يومين فهذا مثل النائم إذا استيقظ يصلي ما ترك.\nأما إذا كان أصابه خلل في عقله بأن اختل عقله بسبب المرض ومضى عليه مدة طويلة فهذا لا شيء عليه، لا قضاء عليه لو صح بعد ذلك، وإن قضى احتياطاً حسن، لكن لا قضاء عليه على الصحيح إذا طالت المدة، أما إن كانت المدة يوم يومين ثلاث فيقضي بعد أن يصحو من غشيته وذهاب عقله.\nوعلى كل تقدير لا تقضى عنه الصلاة سواء تعمد ذلك لجهله أو لعلة من العلل، فلا تقضى الصلاة إنما يقضى الصوم، إذا مات وعليه صيام قد فرط في قضائه يقضى عنه، أما إذا مات وعليه صيام ما تمكن من قضائه، مات في مرضه وما تمكن من قضاء الصوم فلا صوم عليه، لكن بعض الناس قد يصحو من مرضه قد يشفى ثم يتأخر ولا يقضي ما عليه من صيام رمضان، فهذا يقضى عنه، يقضي عنه أولياؤه؛ ورثته. نعم. كما قال النبي عليه الصلاة والسلام: من مات وعليه صيام صام عنه وليه، وقد سئل عدة أسئلة عليه الصلاة والسلام، قال بعض السائلين: يا رسول الله! إن أمي ماتت وعليها صيام شهر؟ وآخر يقول: إن أبي مات وعليه كذا؟ فيقول: صم. فيأمرهم بالصوم، ويقول لهم: أرأيتم لو كان على أبيك أو كان على أمك.. لو كان على أختك دين أكنت قاضيه؟ فاقضوا الله، فالله أحق بالوفاء فيشبه ما عليه من الصوم بالدين، فهو يأمر أولياءهم بالقضاء، أما الصلاة فلم يأمر أحداً بقضائها عليه الصلاة والسلام. نعم.\nالمقدم: لكن بالنسبة للصيام أليس مثلاً خاص برمضان أو في كل صيام؟\nالشيخ: الصواب أنه عام، بعض أهل العلم يخصه بالنذر ويقول: هذا في النذر خاصة، ولكنه قول ضعيف، والأحاديث عامة في رمضان وفي غيره؛ صوم رمضان وصوم الكفارة فهذا يقضي عنه أولياؤه. نعم.","link":"https://binbaz.org.sa/fatwas/5881/حكم-المريض-اذا-ترك-الصلاة-اثناء-مرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_085/08505.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":8173,"question":"الرسالة التالية باعثها أخونا ناصر البريدي من المنطقة الشرقية يقول: أنا كنت مريض في المستشفى راقد سرير كما يقول حوالي أسبوع، واشتد علي المرض لم أستطع أصلي، لكن بعدما طلعت من المستشفى صليت كل الأوقات التي فاتتني في عصر، وصليتها قصراً من كل وقت ركعتين ركعتين هل صلاتي هذه صحيحة أم لا؟","title":"حكم من ترك عدداً من الصلوات بسبب مرضه","answer":"الجواب: أولاً الواجب عليك أن تصلي في حال المرض ولو أنك جالس أو مضطجع، تصلي على حسب حالك لأن الله سبحانه يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والنبي ﷺ قال للمريض صل قائما، فإن لم تستطع فقاعدا، فإن لم تستطع فعلى جنب، فإن لمم تستطع فمستلقيا  هكذا أمره النبي عليه الصلاة والسلام، فالمريض يفعل ما يستطيع إن استطاع قائماً صلى قائماً، وإن عجز صلى قاعداً، وإن عجز صلى على جنبه الأيمن أو الأيسر والأيمن أفضل، فإن عجز صلى مستلقياً ورجلاه إلى القبلة هذا هو المشروع، فإذا لم يفعل وجب عليه القضاء، لم يفعل بزعمه أنه يصلي بعد حين أكمل أو كونه يشق عليه حال وجود المرض فكل هذا غلط ولكن عليه القضاء، لأنه تركها بشبهة فعليه القضاء والمبادرة بالقضاء إذا استطاع ذلك ويصلي أربعاً ما يصلي ثنتين، ثنتين هذه للمسافر، أما المريض يصلي أربع ولا يصلي ثنتين، إنما قصر الصلاة للمسافرين خاصة؛ أما المرضى فإنهم يجمعون فقط لأن لهم الجمع بين الصلاتين الظهر والعصر والمغرب والعشاء لا بأس يجمعون، أما القصر يعني: كونه يصلي ثنتين فلا، لكن يغتر بعض الناس بما يسمع من بعض العامة يقولون: المريض له يقصر، وقصدهم بالقصر الجمع، يسمون الجمع: قصر وهذا غلط في اللغة، الجمع بين الظهر والعصر والجمع بين المغرب والعشاء ما يسمى قصر يسمى جمعاً، لأنه جمع بين الصلاتين في وقت إحداهما فيسمى جمعاً لا قصرا، أما القصر فهو كونه يصلي الظهر ثنتين والعصر ثنتين والعشاء ثنتين هذا القصر، لكن بعض العامة يسمي الجمع قصر فنتج عن هذا أن بعض الناس قصر في المرض لما يسمع من بعض العامة أن المريض يقصر، ومرادهم أنه يقصر يعني: يجمع هذا لغة العامة، يسمون الجمع قصراً وهو غلط في اللغة العربية، الجمع ما يسمى: قصراً، يسمى: جمعاً، فإذا صلى الظهر والعصر جميعاً في وقت الظهر أو في وقت العصر هذا يسمى جمع ما يسمى قصر، وهكذا إذا صلى المغرب والعشاء جمعاً في وقت المغرب أو في وقت العشاء هذا يسمى جمعاً لا قصرا، أما القصر فكونه يصلي العشاء ثنتين، الظهر ثنتين، العصر ثنتين هذا القصر وهذا خاص بالمسافرين، المسافر هو الذي يصلي ركعتين، أما المريض فعليه أن يصلي أربعاً لكن له أن يجمع بين الظهر والعصر وله أن يجمع بين المغرب والعشاء من أجل المرض والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/5978/حكم-من-ترك-عددا-من-الصلوات-بسبب-مرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10410.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":8438,"question":"سؤاله الأخير: كيف يقضي المسلم ما فاته من الصلاة أي: صلاة بكاملها، كصلاة الفجر مثلاً؟ وهل إذا كانت الصلاة جهرية، يجب عليه أن يجهر بها، أفيدونا بارك الله فيكم؟","title":"ما كيفية قضاء الصلوات الجهرية والسرية؟","answer":"الجواب: من كان عليه صلوات يقضيها كما لو أداها، إن كانت جهرية قضاها جهراً كالفجر والعشاء والمغرب، وإن كانت سرية قضاها سراً كالظهر والعصر، يقضيها كما يؤديها في وقتها، هذا إذا كان تركها عن نسيان، أو عن نوم، أو عن شبهة مرض يزعم أنه لا يستطيع فعلها وهو في وقت المرض، فأخرها جهلاً منه، هذا يقضيها كما كانت.\nأما إذا كان تركها تعمداً ثم هداه الله وتاب فليس عليه قضاء؛ لأن تركها كفر إذا كان تعمد، فإذا تاب إلى الله من ذلك فليس عليه قضاء وإنما التوبة تمحو ما قبلها، إذا تاب توبة صادقة من تركه الصلاة؛ محا الله عنه بذلك ما ترك، وليس عليه قضاء في أصح قولي العلماء؛ إنما القضاء في حق من تركها نسياناً، أو جهلاً منه بوجوب أدائها بسبب مرض أصابه، فأراد أن يؤخرها حتى يصليها وهو صحيح؛ أو بسبب نوم هذا هو الذي يقضي.\nأما الذي يتركها تعمداً نعوذ بالله من ذلك، فهذا كفر، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، عن بريدة ، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه، في أحاديث أخرى تدل على ذلك.\nفالخلاصة أنه إذا تركها عمداً تهاوناً بها أو جحداً لوجوبها كفر، فإن كان جاحداً لوجوبها كفر إجماعاً، أجمع العلماء على أن من جحد وجوب الصلاة كفر إجماعاً نسأل الله العافية.\nأما إن تركها تهاوناً وتكاسلاً فهذا قد شابه المنافقين وذلك كفر أكبر في أصح قولي العلماء، فعليه التوبة إلى الله التوبة الصادقة النصوح، المتضمنة الندم على ما مضى، والإقلاع من ذلك، والعزم أن لا يعود لمثل ذلك، فهذا تكفيه التوبة والحمد لله، ولا قضاء عليه. نعم.","link":"https://binbaz.org.sa/fatwas/6322/ما-كيفية-قضاء-الصلوات-الجهرية-والسرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12003.mp3","categories":["قضاء الفوائت"]},{"id":8553,"question":"هذه رسالة وردت من الأخ خالد ناصر أبو بكر ، من جمهورية اليمن الديمقراطية يقول أولاً: هل على المرتد قضاء الصلاة أو الصيام إذا عاد إلى الإسلام وتاب إلى الله؟","title":"حكم قضاء المرتد ما فاته من صلاة وصيام بعد عودته","answer":"الجواب: ليس عليه قضاء، من تاب تاب الله عليه، إذا ترك الإنسان الصلاة أو أتى بناقض من نواقض الإسلام ثم هداه الله وتاب فإنه لا قضاء عليه، هذا هو الصواب من أقوال أهل العلم، الإسلام يجب ما قبله، والتوبة تهدم ما كان قبلها، قال الله سبحانه: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] فبين سبحانه أن الكافر إذا أسلم غفر الله له ما قد سلف، والنبي ﷺقال: التوبة تجب ما قبلها والإسلام يهدم ما كان قبله، فالحمد لله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6636/حكم-قضاء-المرتد-ما-فاته-من-صلاة-وصيام-بعد-عودته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20609.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":8556,"question":"هذه رسالة وردت من الأخ خالد ناصر أبو بكر ، من جمهورية اليمن الديمقراطية يقول أولاً: هل على المرتد قضاء الصلاة أو الصيام إذا عاد إلى الإسلام وتاب إلى الله؟","title":"حكم قضاء المرتد ما فاته من صلاة وصيام بعد عودته","answer":"الجواب: ليس عليه قضاء، من تاب تاب الله عليه، إذا ترك الإنسان الصلاة أو أتى بناقض من نواقض الإسلام ثم هداه الله وتاب فإنه لا قضاء عليه، هذا هو الصواب من أقوال أهل العلم، الإسلام يجب ما قبله، والتوبة تهدم ما كان قبلها، قال الله سبحانه: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] فبين سبحانه أن الكافر إذا أسلم غفر الله له ما قد سلف، والنبي ﷺقال: التوبة تجب ما قبلها والإسلام يهدم ما كان قبله، فالحمد لله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6636/حكم-قضاء-المرتد-ما-فاته-من-صلاة-وصيام-بعد-عودته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20609.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":8751,"question":"هذه رسالة من المرسل (م. ق. ل) من جيزان، كنا قد عرضنا سؤالاً له في الحلقة الماضية والآن نعرض بقية أسئلته، والتي طلب توجيهها لسماحتكم يقول في سؤاله الثاني: رجل أصابه حادث سيارة وغاب عنه ذهنه، وجلس يومين لا يدري ولا يحكم الفرض ولا يدري كم فرضاً فاتته؟ فهل يقضيها أفتونا مأجورين؟","title":"حكم الصلاة لمن أصيب بحادث فغاب وعيه","answer":"الجواب: نعم الذي يصاب بحادث يبقى يوماً أو يومين أو ثلاث لا يشعر، إذا صحا وانتبه يقضي الأيام التي ترك الصلاة فيها؛ لأن هذا يشبه بالنوم ويشبه بالإغماء الذي يحصل لبعض الناس، فيصلي تلك الفروض التي فاتته ولم يشعر بها، أما إذا طال الأمر بأن كانت المدة طويلة أكثر من ثلاثة أيام فهذا فيه خلاف من أهل العلم من قال: يقضي كالنائم ومنهم من قال: لا يقضي لطول المدة وهو فاقد العقل فهو أشبه بالمجنون والمعتوه، والأقرب والله أعلم أن ما زاد على الثلاث لا قضاء فيه؛ لأنه أشبه بالمجنون وأشبه بالمعتوه، أما الثلاث فما كان أقل فهذا أشبه بالنائم فيقضي، والنبي عليه السلام قال: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك.\nفإغماء اليوم واليومين والثلاث هذا يقارب النوم ويشبه النوم فيقضي، أما ما زاد على ذلك كالذي يغيب شهراً أو شهرين أو أكثر من ذلك، فهذا لا قضاء عليه إن شاء الله وهو أشبه بالمعتوه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6910/حكم-الصلاة-لمن-اصيب-بحادث-فغاب-وعيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21707.mp3","categories":["قضاء الفوائت"]},{"id":8864,"question":"هنا رسالة وصلت إلى البرنامج من أحد الإخوة من البحرين يقول: (ط.ح.م.)، أخونا يقول: إذا فاتتني سنة الفجر فمتى أقضيها؟","title":"وقت قضاء سنة الفجر لمن فاتته","answer":"الجواب: إذا فاتت سنة الفجر فالمسلم مخير وهكذا المسلمة إن شاء صلاها بعد الصلاة، وإن شاء صلاها بعد ارتفاع الشمس وهو أفضل، وكل هذا ورد عن النبي ﷺ، ورد عنه أنه رأى من يصلي بعد الصلاة فأنكر عليه فقال: يا رسول الله! إنها سنة الفجر، فسكت عنه عليه الصلاة والسلام.\nوجاء عنه الأمر بقضائها بعد ارتفاع الشمس، وكل هذا بحمد لله سائغ، فمن صلاها بعد الصلاة فلا بأس، ومن أخرها حتى ترتفع الشمس فهو أفضل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7019/وقت-قضاء-سنة-الفجر-لمن-فاتته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13802.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":9363,"question":"في يوم ما لم أصل العشاء ولم أتذكر ذلك إلا في صباح اليوم التالي، كيف أفعل؟","title":"حكم من نسي صلاة ثم ذكرها بعد أن خرج وقتها","answer":"الجواب: يقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك متى ذكرتها بعد الصبح صلها.. في الضحى صلها.. في الظهر صلها.. متى ذكرتها، فإن ذكرتها قبل الفجر فصلها قبل الفجر، فإن لم تذكرها إلا بعد الفجر فصلها بعد الفجر والحمد لله.","link":"https://binbaz.org.sa/fatwas/7527/حكم-من-نسي-صلاة-ثم-ذكرها-بعد-ان-خرج-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18604.mp3","categories":["قضاء الفوائت"]},{"id":9433,"question":"وهذه رسالة وردت إلى البرنامج من محمد هاشم سعيد مصري يعمل باليمن يقول في رسالته: لقد وجدت في كتاب المجموعة المباركة تأليف عبده محمد باباً في فائدة تقول: عن رسول الله ﷺ أنه قال: من فاتته صلاة في عمره ولم يحصها فليقم في آخر جمعة من رمضان ويصلي أربع ركعات بتشهد واحد، يقرأ في الركعة الواحدة الفاتحة وسورة القدر عدد خمسة عشر مرة، وكذلك سورة الكوثر مثلها، ويقول في النية: نويت أن أصلي أربع ركعات كفارة لما فاتني من الصلاة فهل هذا صحيح أفتونا أثابكم الله؟","title":"ما صحة قضاء الصلوات في آخر جمعة من رمضان؟","answer":"الجواب: هذا لا أصل له، بل هو موضوع مكذوب، هذا ليس له أصل، بل هو من الكذب والباطل، وإذا فات الإنسان صلاة ولم يذكرها يتحرى، يتحراها ظهراً أو عصراً أو عشاءً أو مغرباً أو فجر، يتحراها يعمل بظنه ويصلي ما غلب على ظنه والحمد لله في أي وقت. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7608/ما-صحة-قضاء-الصلوات-في-اخر-جمعة-من-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23909.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":9884,"question":"يسأل أيضاً ويقول: ما الحكم في الصلوات الفائتة علي، هل علي قضاؤها أم ماذا أفعل؛ لأنني سمعت حديثاً عن أنس ، يقول قال رسول لله ﷺ: من فاتته صلاة ولم يحصها فليقم في آخر جمعة من رمضان ويصلي أربع ركعات ويستغفر الله بعدها فهل هذا صحيح؟ أفيدوني أفادكم الله.","title":"حكم قضاء الصلاة على من تركها عمدًا","answer":"الجواب: ليس بصحيح ولا أصل له، ولكن عليه القضاء، إذا ترك صلوات نسياناً أو لأسباب مرض يحسب أنه يسوغ له التأخير أو لنوم فإنه يقضيها.\nأما إن كان عمداً ترك الصلاة عمداً ثم تاب الله عليه فإنه لا يقضي؛ لأن تركها عمداً كفر والكافر لا يقضي، هذا هو الصواب في ترك الصلاة إذا تركها ولو متهاوناً لا جاحداً فإنه يكفر بذلك، أما إن ترك الصلاة عامداً جاحداً لوجوبها هذا يكفر عند جميع أهل العلم، لكن إذا كان يقر بوجوبها، يعلم أنها واجبة عليه ولكنه تركها تهاوناً وتكاسلاً فهذا فيه نزاع بين أهل العلم. والصواب والراجح في هذه المسألة: كفره كفر أكبر فلا قضاء عليه لما ترك عمداً تهاوناً، أما ما تركه عن مرض يظن أنه يسوغ له التأخير، أو تركه عن نسيان أو عن نوم هذا يقضي، لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها لا كفارة لها إلا ذلك.\nوأما الذي يتركها عمداً تهاوناً فهذا هو الذي لا يقضي وعليه التوبة إلى الله جل وعلا؛ لأن تركها تهاوناً عمداً كفر أكبر، والكافر عليه التوبة، وإذا تاب لا يقضي لقوله : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] ولقوله ﷺ: التوبة تهدم ما كان قبلها، والإسلام يهدم ما كان قبله وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله وقال أيضاً عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة.\nخرجه مسلم في صحيحه رحمه الله.\nفهذه النصوص وما جاء في معناها كلها دالة على كفر من ترك الصلاة عمداً، تهاوناً وتكاسلاً لا عن علة من نوم أو مرض يظن أنه يسوغ له معه التأخير، أو عن نسيان فالناسي والنائم والمريض الذي يظن أنه يجوز له التأخير يقضي، وأما المتعمد المتساهل هذا لا يقضي وعليه التوبة إلى الله . نعم.\nالمقدم: أثابكم الله وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8055/حكم-قضاء-الصلاة-على-من-تركها-عمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26412.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":9936,"question":"أولى رسائل هذه الحلقة وردت من عبد الحميد أحمد محمد علي جمهورية مصر العربية - قنا، يقول: لم أصل إلا بعد ما بلغت الرابعة والعشرين من عمري، وصرت الآن أصلي مع كل فرض فرضاً آخر، فهل يجوز لي ذلك، وهل أداوم على هذا، أم أن علي حقوقاً أخرى؟ أفيدوني أفادكم الله!","title":"هل على التائب من ترك الصلاة قضاء؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالذي يترك الصلاة عمدًا ليس عليه قضاء على الصحيح وإنما عليه التوبة إلى الله ؛ لأن الصلاة عمود الإسلام، وتركها من أعظم الجرائم، بل تركها نوع من الكفر، إذا تركها عمداً كفر كفرًا أكبر في أصح قولي العلماء؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة رضي الله عنه، ولقوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه عن جابر بن عبد الله رضي الله عنهما في أحاديث أخرى تدل على ذلك، فالواجب عليك يا أخي التوبة إلى الله، التوبة الصادقة وذلك بالندم على ما مضى منك، والإقلاع من ترك الصلاة، والعزم الصادق أن لا تعود في ذلك، وليس عليك أن تقضي لا مع كل صلاة ولا في غير ذلك، بل عليك التوبة فقط، والحمد لله من تاب تاب الله عليه، يقول الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ويقول النبي ﷺ: التائب من الذنب كمن لا ذنب له فعليك أن تصدق في التوبة وأن تحاسب نفسك، وأن تجتهد في المحافظة على الصلاة في أوقاتها في الجماعة، وأن تستغفر الله مما جرى منك، وتكثر من العمل الصالح وأبشر بالخير، يقول الله سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] ولما ذكر الشرك والقتل والزنا قال جل وعلا بعد ذلك: وَمَنْْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا ۝ إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا[الفرقان:68-70] نسأل الله لنا ولك التوفيق وصحة التوبة والاستقامة على الخير. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8106/هل-على-التاىب-من-ترك-الصلاة-قضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27401.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":10001,"question":"تقول: عندما كنت في الثانية عشرة والثالثة عشرة والرابعة عشرة من عمري أفطرت أيامًا كثيرة في رمضان تلك السنين، ولا أعلم كم عدد هذه الأيام، والآن بعد مضي عدة سنوات صحوت من غفلتي ولله الحمد والمنة، وتذكرت تلك الأيام التي أفطرتها فأردت أن أصوم ثلاثة أشهر، فصمت ستة عشر يومًا منها، ولكني الآن توقفت عن صيامها، وذلك بعد أن سمعت في برنامج نور على الدرب: أن الذي لا يصلي بحكم الكافر الذي لا يقبل منه أي عمل حتى الصيام، وحيث أنني في تلك السنوات كنت لا أصلي بعض الصلوات كسلًا، وبالإضافة إلى ذلك كنت بعد العادة الشهرية أجلس يومًا كاملًا لا أصلي فيه بحجة أن أتبين هل تطهرت تطهرًا كاملًا أم لا، فماذا أفعل، أفيدوني جزاكم الله خيرًا؟","title":"حكم من أفطر أيامًا من رمضان مع تركه للصلاة","answer":"الجواب: يكفي التوبة في هذا، يكفيك يا أيها الأخت! في الله التوبة، عليك بالتوبة والحمد لله، التوبة الندم على الماضي، والعزيمة أن لا تعودين مع الاستغفار والحمد لله؛ لأن ترك الصلاة كفر كما قال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فالذي لا يصلي لا صوم له ولا زكاة له ولا غير ذلك، فلا يلزمك القضاء حينئذ وإنما عليك التوبة، والحمد لله الذي من عليك بالتوبة والالتزام.\nالمقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8166/حكم-من-افطر-اياما-من-رمضان-مع-تركه-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33106.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":10002,"question":"عند إجراء عملية جراحية لإنسان ما، فإن إجراء العملية يستمر عدة ساعات، وكذلك بعد الخروج من غرفة العمليات فإن هذا الإنسان يكون تحت تأثير البنج لعدة ساعات أخرى؛ مما يترتب على ذلك فوات عدة صلوات، فماذا يفعل؟ جزاكم الله خيرًا.","title":"فوات عدة صلوات بسبب الإغماء أو التخدير","answer":"الجواب: إذا وعى وانتبه يصلي الصلوات مثل النائم، حكمه حكم النائم والمغمى عليه بأسباب عارضة، فإذا انتبه صلى الصلوات كلها كالنائم. نعم.\nالمقدم: جزاكم الله خيرًا، الصلوات التي فاتته أثناء ... ؟\nالشيخ: أثناء العملية وتوابعها يصليها بعد الصحو والانتباه، يتوضأ ويصليها وإذا كان لا يستطيع الوضوء لأن مرضه يمنعه من استعمال الماء يتيمم ويصليها. نعم.\nأما ما يتعلق بالخارج من الدبر والقبل فهذا هو مخير إن شاء استنجى إن استطاع بالماء، وإن شاء أزال ذلك بالاستجمار بالمناديل الخشنة الطاهرة يتمسح ثلاث مرات أو أكثر، أو باللبِن أو بغير هذا من الأشياء الطاهرة النظيفة الخشنة حتى يزول الأذى، بشرط أن يكون ذلك ثلاث مرات فأكثر، ما ينقص عن ثلاث، وإذا لم تكف الثلاث زاد حتى يزول الأذى ولو إلى خمس ولو إلى سبع حتى يزول الأذى نعم، ثم يتوضأ وضوء الصلاة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8167/فوات-عدة-صلوات-بسبب-الاغماء-او-التخدير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33107.mp3","categories":["قضاء الفوائت"]},{"id":10104,"question":"مستمع من المملكة الأردنية الهاشمية في مكتبة الحرمين العلمية يقول: إذا كنت معاقًا إعاقة شديدة ولا أستطيع الحركة كيف لي أن أتوضأ وأصلي؟","title":"كيفية طهارة وصلاة المقعد","answer":"الجواب: عليك أن تصلي وتتوضأ بالعون، تكلف غيرك كزوجتك أو ولدك أو شخص آخر بأجرة ليوضئك يغسل وجهك ويديك و .. إلى آخره ويجمرك بالمناديل عن الأذى والحمد لله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، هذا تأمره أن يزيل الأذى من الدبر والقبل بالجمار بالحصى بالمدر بالمناديل ثلاث مرات فأكثر حتى يزيل الأذى ثم يمضمضك وينشقك ويغسل وجهك ويديك ويمسح رأسك وأذنيك ويغسل رجليك، فإن كان يشق عليك الماء ييممك يمسح وجهك بالتراب ويديك بالتراب بالنية عنك أنت تنوي وهو يعمل والنية منك والعمل منه، هذا هو الواجب عليك وتصلي على حسب حالك، تصلي تكبر بالنية أنه دخلت في الصلاة وتركع بالنية إذا كنت تستطيع الركوع تحني رأسك وأنت واقف وإن كنت لا تستطيع القيام ولا الحركة لا رأسك ولا غيره تنوي نية تكبر وتقرأ ثم تكبر وتنوي الركوع، تقول: سبحان ربي العظيم، ثم تقول: سمع الله لمن حمده إذا كنت وحدك ناويًا الرفع ثم تكبر ناويًا السجود تقول: سبحان ربي الأعلى ثم ترفع ناويًا الجلوس بين السجدتين تقول: رب اغفر لي، ثم تكبر ناويًا السجود تقول: سبحان ربي الأعلى وهكذا تكمل بالنية، بالنية والقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nالمقدم: جزاكم الله خيرًا، إذا لم يجد من يعينه -سماحة الشيخ- كيف يتصرف؟\nالشيخ: يصلي على حسب حاله يصلي بالتيمم إن قدر ...... ولا يخرج يدعه يخرج الوقت يصلي في الوقت ولا يعيد، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، وقد صلى الصحابة بغير وضوء ولا تيمم لما بعثهم النبي ﷺ يلتمسون عقد عائشة ، لم يجدوا ماءً ولم .... يجدوا.\nا لمقدم: ... وقبل مشروعية التيمم.\nالشيخ: قبل مشروعية التيمم وليس عندهم ... نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8273/كيفية-طهارة-وصلاة-المقعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33315.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":10306,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من الأحساء وباعثها مستمع رمز إلى اسمه بحرفين هما (س. ص)، أسئلته مطولة بعض الشيء يقول في الأول: أفيدكم أفادكم الله عن هذه القضية، عمري يتجاوز الثلاثين، كنت لا أعرف صلاةً ولا صياماً والعياذ بالله، وكنت من الذين ضائعين، ولكن الله من علي والحمد لله فالتزمت وشرعت في كتاب الله حفظا، هل في السنين التي انتهت من عمري علي صلاة وصيام، وأنا بديت الصوم قبل ثلاث سنوات فقط وأما بقية السنين فبدون صيام ولا صلاة، وجهوني حول حالتي السابقة جزاكم الله خيراً؟","title":"حكم من ترك الصلاة والصيام سنوات ثم تاب","answer":"الجواب: الحمد لله الذي هداك وردك إلى الصواب، ونوصيك بتقوى الله والصبر والثبات والاستقامة، وسؤال الله سبحانه دائماً أن يثبتك على الحق وأن يعينك على ذكره وشكره وحسن عبادته، وأن يمنحك التوفيق، تدعو ربك كثيراً في السجود، وفي آخر الصلاة، وفي آخر الليل، وبين الأذان والإقامة تجتهد بالدعاء، تسأله سبحانه أن يمنحك التوفيق، وأن يمنحك الاستقامة، وأن يمنحك الفقه في الدين، وأن يعفو عنك عما سلف، وليس عليك قضاء لا صلاة ولا صيام ليس عليك قضاء؛ لأن التوبة تجب ما قبلها؛ ولأن من ترك الصلاة كفر فلا يقضي ما مضى؛ لقوله سبحانه : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]؛ ولقوله ﷺ : التوبة تهدم ما كان قبلها، وقوله ﷺ: التائب من الذنب كمن لا ذنب له، فإذا كان الإنسان على حالة كفرية ثم تاب فإنه لا يقضي ما مضى من صلاة ولا صوم، وإذا أسلم وتاب فهو على ما أسلم من خير، ما كان قبل ذلك من الخير يبقى له وليس عليه القضاء لما ترك من صلاة وصوم في حال كفره بتركه الصلاة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8483/حكم-من-ترك-الصلاة-والصيام-سنوات-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31309.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":10315,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من الأحساء وباعثها مستمع رمز إلى اسمه بحرفين هما (س. ص)، أسئلته مطولة بعض الشيء يقول في الأول: أفيدكم أفادكم الله عن هذه القضية، عمري يتجاوز الثلاثين، كنت لا أعرف صلاةً ولا صياماً والعياذ بالله، وكنت من الذين ضائعين، ولكن الله من علي والحمد لله فالتزمت وشرعت في كتاب الله حفظا، هل في السنين التي انتهت من عمري علي صلاة وصيام، وأنا بديت الصوم قبل ثلاث سنوات فقط وأما بقية السنين فبدون صيام ولا صلاة، وجهوني حول حالتي السابقة جزاكم الله خيراً؟","title":"حكم من ترك الصلاة والصيام سنوات ثم تاب","answer":"الجواب: الحمد لله الذي هداك وردك إلى الصواب، ونوصيك بتقوى الله والصبر والثبات والاستقامة، وسؤال الله سبحانه دائماً أن يثبتك على الحق وأن يعينك على ذكره وشكره وحسن عبادته، وأن يمنحك التوفيق، تدعو ربك كثيراً في السجود، وفي آخر الصلاة، وفي آخر الليل، وبين الأذان والإقامة تجتهد بالدعاء، تسأله سبحانه أن يمنحك التوفيق، وأن يمنحك الاستقامة، وأن يمنحك الفقه في الدين، وأن يعفو عنك عما سلف، وليس عليك قضاء لا صلاة ولا صيام ليس عليك قضاء؛ لأن التوبة تجب ما قبلها؛ ولأن من ترك الصلاة كفر فلا يقضي ما مضى؛ لقوله سبحانه : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]؛ ولقوله ﷺ : التوبة تهدم ما كان قبلها، وقوله ﷺ: التائب من الذنب كمن لا ذنب له، فإذا كان الإنسان على حالة كفرية ثم تاب فإنه لا يقضي ما مضى من صلاة ولا صوم، وإذا أسلم وتاب فهو على ما أسلم من خير، ما كان قبل ذلك من الخير يبقى له وليس عليه القضاء لما ترك من صلاة وصوم في حال كفره بتركه الصلاة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8483/حكم-من-ترك-الصلاة-والصيام-سنوات-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31309.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":10317,"question":"يقول: إذا كان الشاب في بداية حياته قد ضيع بعض الصلوات وتركها وكذلك الصيام جهلاً وتكاسلاً، ثم تاب بعد ذلك وندم، فهل عليه إعادة لما ترك من الصلوات والصيام علماً بأنه لا يستطيع تحديدها، أفتونا مأجورين جزاكم الله خيراً؟","title":"حكم من تاب من ترك الصلاة والصيام كسلًا وجهلًا","answer":"الجواب: ليس عليه قضاء، والتوبة كافية، إذا كان لا يصلي ولا يصوم أو عنده أنواع من الكفر الأخرى فإن التوبة تكفي، يقول الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، ويقول جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ يعني: بالشرك والمعاصي لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]، أجمع العلماء على أن الآية المذكورة في التائبين، فإذا كان لا يصلي ولا يصوم، أو كان يسب الدين، أو كان يشرك بغير الله، يدعو الأموات، ويستغيث بأهل القبور، أو بالأصنام والأشجار، فإنه متى تاب توبةً صادقة تاب الله عليه، والتوبة الصادقة تشمل أموراً ثلاثة: الندم على الماضي الندم الصادق، والإقلاع من المعصية أو الشرك وترك ذلك، والعزم الصادق ألا يعود رغبةً فيما عند الله وإخلاصاً له ومحبةً له وتعظيماً له فإن هذه التوبة تمحو ما قبلها، من جميع أنواع الشرك والمعاصي.\nالأمر الأول: الندم على الماضي؛ خوفاً من الله وتعظيماً له.\nالأمر الثاني: الإقلاع من الذنوب من الكفر والمعاصي.\nالأمر الثالث: العزم الصادق ألا يعود في ذلك.\nفمتى فعل هذا خوفاً من الله وتعظيماً له ورغبةً فيما عنده وإخلاصاً له سبحانه تاب الله عليه ومحا عنه جميع الذنوب وليس عليه قضاؤها لا صلاة ولا صيام ولا غير ذلك، التوبة تجب ما قبلها، وإن كان عنده حق للمخلوقين فلابد من الأمر الرابع وهو رد حقوقهم إليهم كالسرقات والغصوب يعطيهم حقوقهم، وهكذا القصاص إذا قتل لهم أحداً يعطيهم حقهم بالقصاص أو الدية، لابد من أداء الحق للمخلوق أو استحلاله إذا أحله وسامحه لا بأس.\nأما إن كان فعله ليس بكفر أكبر كترك الصيام فقط وإلا هو يصلي لكن فرط في بعض الصيام فإنه يقضي، إذا كان يصلي ولكنه فرط في بعض الصيام أو في الزكاة ما زكى، ليس بكافر، ترك الصيام ليس بكفر إذا كان يؤمن بالوجوب وأن رمضان واجب عليه ولكن تساهل ففرط في بعض الصيام يقضي، عليه القضاء والتوبة إلى الله، وعليه أداء الزكاة عما مضى إذا كان لا يزكي، مع التوبة الصادقة والله يتوب على التائبين.\nأما ترك الصلاة فكفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالصلاة أمرها عظيم، وهي عمود الإسلام، من حفظها حفظ دينه ومن ضيعها ضيع دينه، نسأل الله العافية.\nفالواجب على كل مسلم أن يحذر تركها والتساهل بها، على الجميع رجالاً ونساء أن يتقوا الله، وأن يحافظوا على الصلوات الخمس في أوقاتها، وأن يؤديها الرجل في الجماعة، هذا هو الواجب على الجميع، فمن ضيعها وتهاون بها وتركها كفر نسأل الله العافية في أصح قولي العلماء.\nأما من جحد وجوبها وقال: ما هي بواجبة، هذا يكفر عند الجميع عند جميع الأمة عند جميع أهل العلم، من قال: إنها غير واجبة أو إن واحدة منها غير واجبة كالظهر أو العصر أو المغرب أو العشاء أو الفجر كفر إجماعاً، أما إذا كان يؤمن بأنها واجبة ولكن يتساهل ويتركها أو بعضها فإنه يكفر بذلك نسأل الله العافية، أما إن كان يصلي لكن في البيت فهذا يكون عاصي وعليه التوبة إلى الله وأن يصلي في الجماعة، وصلاته مجزئة لا يعيدها لكن عليه أن يصلي في الجماعة ويتوب مما سلف، إذا كان لا يصلي في الجماعة بل يصلي في البيت يجب أن يصلي مع الجماعة، وأن يتوب إلى الله مما سلف.\nأما النساء فعليهن الصلاة في البيت، السنة لهن الصلاة في البيوت، ومن صلت مع الجماعة صلاتها صحيحة، لكن الأفضل في حق النساء الصلاة في البيت. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8494/حكم-من-تاب-من-ترك-الصلاة-والصيام-كسلا-وجهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها","الرقائق"]},{"id":10329,"question":"يقول: إذا كان الشاب في بداية حياته قد ضيع بعض الصلوات وتركها وكذلك الصيام جهلاً وتكاسلاً، ثم تاب بعد ذلك وندم، فهل عليه إعادة لما ترك من الصلوات والصيام علماً بأنه لا يستطيع تحديدها، أفتونا مأجورين جزاكم الله خيراً؟","title":"حكم من تاب من ترك الصلاة والصيام كسلًا وجهلًا","answer":"الجواب: ليس عليه قضاء، والتوبة كافية، إذا كان لا يصلي ولا يصوم أو عنده أنواع من الكفر الأخرى فإن التوبة تكفي، يقول الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، ويقول جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ يعني: بالشرك والمعاصي لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53]، أجمع العلماء على أن الآية المذكورة في التائبين، فإذا كان لا يصلي ولا يصوم، أو كان يسب الدين، أو كان يشرك بغير الله، يدعو الأموات، ويستغيث بأهل القبور، أو بالأصنام والأشجار، فإنه متى تاب توبةً صادقة تاب الله عليه، والتوبة الصادقة تشمل أموراً ثلاثة: الندم على الماضي الندم الصادق، والإقلاع من المعصية أو الشرك وترك ذلك، والعزم الصادق ألا يعود رغبةً فيما عند الله وإخلاصاً له ومحبةً له وتعظيماً له فإن هذه التوبة تمحو ما قبلها، من جميع أنواع الشرك والمعاصي.\nالأمر الأول: الندم على الماضي؛ خوفاً من الله وتعظيماً له.\nالأمر الثاني: الإقلاع من الذنوب من الكفر والمعاصي.\nالأمر الثالث: العزم الصادق ألا يعود في ذلك.\nفمتى فعل هذا خوفاً من الله وتعظيماً له ورغبةً فيما عنده وإخلاصاً له سبحانه تاب الله عليه ومحا عنه جميع الذنوب وليس عليه قضاؤها لا صلاة ولا صيام ولا غير ذلك، التوبة تجب ما قبلها، وإن كان عنده حق للمخلوقين فلابد من الأمر الرابع وهو رد حقوقهم إليهم كالسرقات والغصوب يعطيهم حقوقهم، وهكذا القصاص إذا قتل لهم أحداً يعطيهم حقهم بالقصاص أو الدية، لابد من أداء الحق للمخلوق أو استحلاله إذا أحله وسامحه لا بأس.\nأما إن كان فعله ليس بكفر أكبر كترك الصيام فقط وإلا هو يصلي لكن فرط في بعض الصيام فإنه يقضي، إذا كان يصلي ولكنه فرط في بعض الصيام أو في الزكاة ما زكى، ليس بكافر، ترك الصيام ليس بكفر إذا كان يؤمن بالوجوب وأن رمضان واجب عليه ولكن تساهل ففرط في بعض الصيام يقضي، عليه القضاء والتوبة إلى الله، وعليه أداء الزكاة عما مضى إذا كان لا يزكي، مع التوبة الصادقة والله يتوب على التائبين.\nأما ترك الصلاة فكفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالصلاة أمرها عظيم، وهي عمود الإسلام، من حفظها حفظ دينه ومن ضيعها ضيع دينه، نسأل الله العافية.\nفالواجب على كل مسلم أن يحذر تركها والتساهل بها، على الجميع رجالاً ونساء أن يتقوا الله، وأن يحافظوا على الصلوات الخمس في أوقاتها، وأن يؤديها الرجل في الجماعة، هذا هو الواجب على الجميع، فمن ضيعها وتهاون بها وتركها كفر نسأل الله العافية في أصح قولي العلماء.\nأما من جحد وجوبها وقال: ما هي بواجبة، هذا يكفر عند الجميع عند جميع الأمة عند جميع أهل العلم، من قال: إنها غير واجبة أو إن واحدة منها غير واجبة كالظهر أو العصر أو المغرب أو العشاء أو الفجر كفر إجماعاً، أما إذا كان يؤمن بأنها واجبة ولكن يتساهل ويتركها أو بعضها فإنه يكفر بذلك نسأل الله العافية، أما إن كان يصلي لكن في البيت فهذا يكون عاصي وعليه التوبة إلى الله وأن يصلي في الجماعة، وصلاته مجزئة لا يعيدها لكن عليه أن يصلي في الجماعة ويتوب مما سلف، إذا كان لا يصلي في الجماعة بل يصلي في البيت يجب أن يصلي مع الجماعة، وأن يتوب إلى الله مما سلف.\nأما النساء فعليهن الصلاة في البيت، السنة لهن الصلاة في البيوت، ومن صلت مع الجماعة صلاتها صحيحة، لكن الأفضل في حق النساء الصلاة في البيت. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8494/حكم-من-تاب-من-ترك-الصلاة-والصيام-كسلا-وجهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها","الرقائق"]},{"id":10404,"question":"السؤال الأخير الذي نعرضه لأخينا في هذه الحلقة يقول: إذا ذهبت إلى المسجد وانتهى المؤذن من الأذان وصلوا السنة القبلية ولم أدركها معهم بل قاموا لأداء صلاة الفرض، فهل يجوز أن أصلي السنة القبلية بعد الفرض، أم أصلي السنة البعدية وسقطت عني القبلية؟","title":"حكم قضاء السنن الراتبة","answer":"الجواب: المشروع لك تصليهما جميعًا القبلية والبعدية بعد الصلاة، إذا جئت في الظهر وقد أقيمت الصلاة فإنك تصلي مع المسلمين ثم إذا فرغت من الصلاة والأذكار تصلي السنة القبلية أربع ركعات والبعدية ركعتين، هذا هو المشروع، وقد روى الترمذي بإسناد جيد عن النبي ﷺ أنه فعل ذلك، في بعض الأحيان لم يصل القبلية إلا بعد الصلاة عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8577/حكم-قضاء-السنن-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34011.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":10953,"question":"الأخت المستمعة (ع. ص. ز. أ) من الرياض بعثت برسالة تقول فيها: إذا شككت في تأدية فرض بعد أداء عدة فروض، هل أصلي ذلك الفرض، أم ماذا أفعل؟ أرجو التوجيه جزاكم الله خيرًا.","title":"حكم من شك في عدم تأدية فرض بعد مدة طويلة","answer":"الجواب:  الشك بعد الفرض لا أثر له، ما دام الشك إنما جد من جديد فلا أثر له، الأصل فعل الصلاة والحمد لله، فإذا شك الإنسان بعد ذلك فلا أثر لهذا الشك، وهذا من الشيطان، نعم. المقدم: جزاكم الله خيرًا، إذًا لا تصلي والحالة هذه؟ الشيخ: لا عليها، ليس عليها شيء، نعم. المقدم: ليس عليها شيء؟ الشيخ: نعم، الأصل أنها أدت الصلاة والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9122/حكم-من-شك-في-عدم-تادية-فرض-بعد-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36306.mp3","categories":["قضاء الفوائت"]},{"id":10955,"question":"الأخت المستمعة (ع. ص. ز. أ) من الرياض بعثت برسالة تقول فيها: إذا شككت في تأدية فرض بعد أداء عدة فروض، هل أصلي ذلك الفرض، أم ماذا أفعل؟ أرجو التوجيه جزاكم الله خيرًا.","title":"حكم من شك في عدم تأدية فرض بعد مدة طويلة","answer":"الجواب:  الشك بعد الفرض لا أثر له، ما دام الشك إنما جد من جديد فلا أثر له، الأصل فعل الصلاة والحمد لله، فإذا شك الإنسان بعد ذلك فلا أثر لهذا الشك، وهذا من الشيطان، نعم. المقدم: جزاكم الله خيرًا، إذًا لا تصلي والحالة هذه؟ الشيخ: لا عليها، ليس عليها شيء، نعم. المقدم: ليس عليها شيء؟ الشيخ: نعم، الأصل أنها أدت الصلاة والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9122/حكم-من-شك-في-عدم-تادية-فرض-بعد-مدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36306.mp3","categories":["قضاء الفوائت"]},{"id":11006,"question":"من المملكة الأردنية الهاشمية، هذه رسالة بعث بها مستمع من هناك هو (خ. ش) يقول في أحد أسئلته: أنا شاب عمري خمسة وعشرون عامًا، انقطعت عن الصلاة تهاونًا لمدة تسع سنوات، والآن قد تبت إلى الله، لكنني حائر في أمر الصلوات الماضية هل أقضيها، وإذا كنت سأقضيها هل أصلي مع كل فرض جديد فرضًا قديمًا حتى تنتهي المدة؟ أفيدوني أفادكم الله.","title":"حكم قضاء الصلوات لمن تاب من تركها","answer":"الجواب:  الحمد لله الذي من عليك بالتوبة، ونوصيك بلزوم التوبة والاستقامة عليها، وشكر الله على ذلك  والحذر من صحبة الأشرار الذين قد يجرونك إلى العودة إلى ترك الصلاة. وأما القضاء فليس عليك قضاء، التوبة كافية؛ لأن التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله، والذين ارتدوا في عهد الصحابة  لما تابوا لم يأمرهم الصحابة بالقضاء. فالمقصود: أن التوبة تكفي والحمد لله، يقول النبي ﷺ: الإسلام يهدم ما كان قبله، والتوبة تهدم ما كان قبلها، فليس عليك قضاء للصلوات الماضية، السنوات التسع، وعليك أن تلزم التوبة، وهي الندم على ما مضى، التوبة حقيقتها الندم على الماضي من الفعل السيئ، والإقلاع من ذلك والحذر منه، مع العزم الصادق أن لا تعود في ذلك. فنوصيك يا أخي! بلزوم التوبة، والاستقامة عليها، وسؤال الله الثبات على الحق، والاستقامة عليه، كما نوصيك بالمحافظة على الصلاة، وأداءها في الجماعة في المساجد، والحذر من صحبة الأشرار الذين قد يجرونك إلى ما حرم الله من ترك الصلاة، أو غير ذلك من الشرور، نسأل الله لنا ولك التوفيق والثبات على الحق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9169/حكم-قضاء-الصلوات-لمن-تاب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36503.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":11068,"question":"هذا السائل أبو علي يقول: إذا كان على الإنسان قضاء، ولا أعرف عدد هذا القضاء، والآن أنا أصلي مع كل فرض فرضًا، هل أصلي الفرض الحاضر الأول، أم أصلي القضاء الأول؟ مأجورين.","title":"كيفية قضاء الصلوات الفائتة","answer":"الجواب:  الواجب عليك أن تبادر بالقضاء؛ ولا تجعل فرض مع فرض، بل بادر به واسرده، اسرد ما عليك في الضحى في الظهر في الليل حتى تتخلص منه، ولا يجوز لك التأخير -النبي عليه السلام- يقول: من نسي صلاة أو نام عنها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك. فأنت الواجب عليك أن تبادر بقضاء الصلوات التي عليك بالتحري، الذي تظن، أفعله خمسًا، عشرًا، عشرين، الذي تظنه، بادر بقضائه، ولا تجعله مع كل صلاة، بل بادر به، اسرده جميعًا في الضحوة، أو في الظهر، أو في الليل حتى تنتهي منه، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9246/كيفية-قضاء-الصلوات-الفاىتة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28816.mp3","categories":["قضاء الفوائت"]},{"id":11177,"question":"هل يصلح أن أصلي عن شخص متوفٍ ترك صلاته بعض الوقت ولم يصل؟","title":"حكم قضاء الصلاة عن الميت التارك لها","answer":"الجواب:  الصلاة لا تقضى، الصلاة لا تقضى، إن كان تركها عمدًا فهذا كفر أكبر نعوذ بالله، وإن تركها من غير شعوره، اختل شعوره فلا شيء عليه. المقصود أن الصلاة لا تقضى، سواء تركها عن شعور أو عن غير شعور، فإن كان عن شعور وتعمد، هذا كفر أكبر نعوذ بالله، لا يصلى عليه ولا يغسل، ليس بمسلم على الصحيح، أما إن كان تركها لأجل اختلال الشعور، أي: بسبب شدة المرض اختل شعوره فلا شيء عليه، ولا تقضى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9376/حكم-قضاء-الصلاة-عن-الميت-التارك-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37220.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":11182,"question":"هل يصلح أن أصلي عن شخص متوفٍ ترك صلاته بعض الوقت ولم يصل؟","title":"حكم قضاء الصلاة عن الميت التارك لها","answer":"الجواب:  الصلاة لا تقضى، الصلاة لا تقضى، إن كان تركها عمدًا فهذا كفر أكبر نعوذ بالله، وإن تركها من غير شعوره، اختل شعوره فلا شيء عليه. المقصود أن الصلاة لا تقضى، سواء تركها عن شعور أو عن غير شعور، فإن كان عن شعور وتعمد، هذا كفر أكبر نعوذ بالله، لا يصلى عليه ولا يغسل، ليس بمسلم على الصحيح، أما إن كان تركها لأجل اختلال الشعور، أي: بسبب شدة المرض اختل شعوره فلا شيء عليه، ولا تقضى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9376/حكم-قضاء-الصلاة-عن-الميت-التارك-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37220.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":11291,"question":"من المستمعة (ج. هـ) من القصيم رسالة وضمنتها سؤالين، في سؤالها الأول تقول: قبل ثلاث سنوات كنت مسرفة على نفسي كثيرًا، وكنت مفرطة في الصلوات وفي الصوم، ولكن أنا الآن نادمة وتائبة، وسؤالي: كنت في أيام الغفلة ومضى علي سنتان وأنا لم أصم ولا أصلي، فهل يجب علي قضاء ما فات من صلاة وصيام؟أم كيف توجهونني؟ جزاكم الله خيرًا,","title":"حكم قضاء الصلاة والصيام على من تركها","answer":"الجواب: الصواب التوبة كافية إن شاء الله، ولا قضاء عليك، لا قضاء عليك والحمد لله، التوبة كافية، يقول النبي ﷺ: التوبة تجب ما قبلها.  والتائب من الذنب كمن لا ذنب له فلا قضاء عليك لا للصلاة ولا للصيام؛ لأن ترك الصلاة كفر، والكافر إذا أسلم لا يقضي ما مضى، قال الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [لأنفال: 38]، يغفر لهم ما قد سلف. فالمرتد لا يقضي ما سلف ولكن عليه التوبة والاستقامة والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9483/حكم-قضاء-الصلاة-والصيام-على-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37615.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":11454,"question":"رسالة بعث بها المستمع عبدالحميد برعي مصري الجنسية يقول: أنا بلغت من العمر السادسة والعشرين، وكنت تاركًا للصلاة، أقوم أحيانًا، وأترك أحيانًا، ولما سافرت إلى المملكة هنا وسمعت برنامج نور على الدرب، وسمعت فيه بأن تارك الصلاة كافر؛ عدت والحمد لله أقوم بالصلاة المفروضة في أوقاتها، لكني أسأل عما فات من عمري، كيف يكون حالي؟  -جزاكم الله خيرًا- هل يلزمني القضاء، أم تكفي التوبة؟ وجهوني جزاكم الله خيرًا.","title":"هل يلزم تارك الصلاة القضاء، أم تكفي التوبة؟","answer":"الجواب:  الحمد لله الذي هداك ووفقك للعودة إلى الخير، والمحافظة على الصلاة، نسأل الله لنا ولك الثبات على الحق، أما الماضي فتكفي التوبة، والحمد لله، الماضي تكفي التوبة؛ لأن الله سبحانه يقول: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، ويقول النبي ﷺ: التوبة تهدم ما كان قبلها ويقول -عليه الصلاة والسلام-: التائب من الذنب كمن لا ذنب له نسأل الله أن يمن على الجميع بالتوبة الصادقة النصوح، نعم.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9635/هل-يلزم-تارك-الصلاة-القضاء-ام-تكفي-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38109.mp3","categories":["قضاء الفوائت"]},{"id":11644,"question":"من مدينة الخبر رسالة بعث بها مستمع يقول: (ع. هـ. ح. ك) يسأل ويقول: إذا كان الإنسان نائمًا من مرض، أو تعب، أو أي سبب آخر، ففاته صلاة، أو صلاتان مثلًا، كان نائمًا بعد صلاة الظهر، فاستيقظ قبيل صلاة العشاء بقليل، ماذا يفعل؟ جزاكم الله خيرًا.","title":"حكم من نام ففاتته عدة صلوات","answer":"الجواب:  الواجب على كل مؤمن أن يحرص على أداء الصلاة في الجماعة في وقتها مع المسلمين، وأن يجتهد في إيجاد الأسباب من وجود ساعة ......... على الوقت، أو موقظين من أهله يوقظونه، مع التبكير في أوقات النوم، وعدم التأخر، فإذا غلبه أمر من غير اختيار، ولا قصد؛ فالله يعذره، مثلما قال ﷺ: ليس في النوم تفريط إذا كان من غير تساهل، ثم غلبه النوم لتعب ومرض؛ فلا يضره ذلك، لكن ليس له أن يتساهل بأن يتأخر في النوم، أو يأتي وقت الصلاة ينام، أو ما أشبه ذلك، ينام في الأوقات المناسبة، ويتحرى النوم في الأوقات المناسبة، ويتعاطى أسباب اليقظة بالساعة، أو بالموقظين، ولا يتساهل، والله -جل وعلا- هو الذي يعلم السرائر، ولا يخفى عليه خافية، فإذا علم سبحانه أن العبد مجتهد وحريص، ولكن غلبه الأمر؛ فلا شيء عليه لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لكن المصيبة أن يتساهل، وألا يبالي، ويحتج بالأعذار الباطلة، هذا هو الخطأ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9833/حكم-من-نام-ففاتته-عدة-صلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38920.mp3","categories":["قضاء الفوائت"]},{"id":11756,"question":"الأخوان محمد نور محمد علي مسعود سوداني، والأخ الصافي أحمد الزاكي بعثا برسالة وضمناها جمعًا من الأسئلة في أحدها يقولون: إذا كان أحدنا لم يصل العصر، ودخل وقت صلاة المغرب، وحضرت الجماعة في صلاة المغرب، هل يصلي العصر، أم يصلي مع الجماعة؟ جزاكم الله خيرًا.","title":"حكم من لم يصل العصر وقد أقيمت صلاة المغرب","answer":"الجواب:  إذا أمكنه أن يصلي العصر أولًا بدأ بها، ثم صلى معهم المغرب، فإن خشي أن تفوته معهم صلى معهم المغرب بنية العصر، فإذا سلموا من المغرب قام وأتى بالرابعة للعصر، ثم يصلي المغرب بعد ذلك، أما إذا أمكنه أن يصلي العصر وحده في المسجد قبل أن يصلوا المغرب؛ فإنه يصليها، ثم يدخل معهم المغرب، فإن لم يتيسر ذلك؛ صلى معهم على الصحيح بنية العصر، فإذا سلموا قام وأتى بالرابعة، ثم يصلي المغرب بعد ذلك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9940/حكم-من-لم-يصل-العصر-وقد-اقيمت-صلاة-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39402.mp3","categories":["قضاء الفوائت"]},{"id":11810,"question":"تقول: بعد انتهاء مدة الحيض أصبت بوعكة صحية أقعدتني في الفراش أي: ما يقارب خمسة أيام، خلال هذه الأيام -أي: الأيام الخمسة التي بعد فترة الحيض- لم أؤد فريضة الصلاة، فهل تعتبر هذه الأيام من فترة الحيض، أم ينبغي علي أن أصلي هذه الأيام التي تركتها، كأن أصلي كل وقت مرتين لمدة خمسة أيام، أم أصليها دفعة واحدة؟ جزاكم الله خيرًا.","title":"حكم من ترك الصلاة لمرض ألم به عدة أيام","answer":"الجواب:  الواجب عليك أن تقضيها، الفرائض التي تركت بعد الطهارة، الواجب أن تقضيها كلها، ولو في وقت واحد إذا استطعت، وإلا فحسب الطاقة، صلي ثلاث صلوات، أربعًا خمسًا، ثم تستريحين، ثم تصلين الباقي، وهكذا، عليك المبادرة والمسارعة، وقد أخطأت في هذا الأمر، فعليك التوبة إلى الله من ذلك؛ لأن المرض ما يمنع من الصلاة، فيصلي المرء ولو كان مريضًا، إن قدر قائمًا؛ صلى قائمًا، وإن عجز؛ صلى قاعدًا، وإن عجز؛ صلى على جنبه. ولهذا لما اشتكى عمران بن حصين -رضي الله عنهما- إلى النبي ﷺ مرضه قال: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيًا فالمريض يصلي على حسب حاله، ولا يجوز له ترك الصلاة، بل يصلي على حسب طاقته، قائمًا إن قدر، فإن عجز؛ صلى قاعدًا، فإن عجز؛ صلى على جنبه، فإن عجز؛ صلى مستلقيًا؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والذي على جنبه، أو مستلقي يصلي بالذكر، وما يستطيع من الفعل، يكبر، ويقرأ، ويكبر وينوي الركوع يقول: سبحان ربي العظيم، يقول سمع الله ناويًا الرفع، وهو على جنبه، أو مستلقيًا، ثم يكبر ناويًا السجود، يقول: سبحان ربي الأعلى، وهكذا بالنية والكلام، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9994/حكم-من-ترك-الصلاة-لمرض-الم-به-عدة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42312.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":11847,"question":"عندما يستيقظ الشخص بعد طلوع الشمس، هل يصلي الصبح حاضرًا، أم قضاء؟","title":"نام حتى طلوع الشمس فهل يصلي الصبح حاضراً أم قضاء؟","answer":"الجواب:  إذا استيقظ يبادر فيتوضأ ويصلي الراتبة، ثم يصلي الفريضة ولو بعد طلوع الشمس، يصلي الراتبة مثلما فعل النبي ﷺ لما نام في السفر حتى طلعت الشمس، أمرهم فاقتادوا رواحلهم عن المكان قال: إنه حضرنا فيه الشيطان فاقتادوا رواحلهم عنه بعض الشيء، ثم توضؤوا وصلوا الراتبة، وصلوا الفريضة بعد الأذان أذن وأقام ﷺ. فهكذا الرجل لو نام عن الصلاة غلبه النوم إذا استيقظ؛ يتوضأ، ويصلي الركعتين، ويقيم، ويصلي الفريضة، ولا يعجل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10025/نام-حتى-طلوع-الشمس-فهل-يصلي-الصبح-حاضرا-ام-قضاء ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39605.mp3","categories":["قضاء الفوائت"]},{"id":12054,"question":"المستمع محمود صالح بعث يسأل ويقول: من ترك الصلاة بخدعة الشيطان لمدد قد تصل لأشهر عديدة، هل يقضيها؟ وكيف يكون القضاء؟ وهل يصلي كل فرض مع فرضه، أم كيف يكون الحال؟ جزاكم الله خيرًا.","title":"حكم قضاء الصلوات المتروكة عمدًا","answer":"الجواب:  من تعمد ترك الصلاة؛ فقد كفر في أصح قولي العلماء، وإن لم يجحد الوجوب، إذا تعمد تركها؛ كفر بذلك؛ لقوله ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وهناك أحاديث أخرى تدل على هذا المعنى، فإذا تاب ورجع؛ فالتوبة تجب ما قبلها، والحمد لله، وليس عليه قضاء ما فات، الصحيح أنه لا قضاء عليه، الإسلام يجب ما قبله والنبي ﷺ لم يأمر الذين أسلموا أن يقضوا، ولم يأمر الذين ارتدوا، ثم أسلموا أن يقضوا، بل التوبة تكفي، والحمد لله، تجب ما قبلها، ولا قضاء عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10239/حكم-قضاء-الصلوات-المتروكة-عمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43403.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":12204,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية، باعثها المستمع: فتحي عاشور السيد، ومقيم في بغداد عندما بعث الرسالة، يقول في رسالته: إنني شاب هناك بعض فروض الصلاة لم أقوم بتأديتها من قبل، هل أقضيها الآن، وكيف يكون القضاء إذا كان واجبًا وكيف تكون النية؟","title":"حكم قضاء الصلوات لمن تركها عمدًا","answer":"الجواب:  الصلاة هي عمود الإسلام، وهي أعظم الفرائض، وأهم الفرائض بعد الشهادتين، ومن تركها جاحدًا لها؛ كفر بإجماع المسلمين، ومن تركها تكاسلًا، وليس بجاحد؛ فإنه كافر في أصح قولي العلماء؛ لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهمم الصلاة، فمن تركها؛ فقد كفر ولقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه في أحاديث أخرى تدل على ذلك، ومن ضيعها، أو ضيع بعضها، ثم تاب؛ فلا قضاء عليه، عليك أن تستقيم أيها السائل! وتسأل ربك التوفيق والإعانة، وتتوب إلى الله مما مضى من الترك، وليس عليك قضاء؛ لأن الكافر إذا أسلم ليس عليه قضاء، وتاركها تهاونًا كافر في الأصح، فليس عليه قضاء. ولكن عليه التوبة الصادقة، عليه أن يندم على ما مضى، ويحزن على ما مضى، ويعزم عزمًا صادقًا على أنه يستقيم في المستقبل، ويحافظ عليها، وبذلك يتوب الله عليه  كما قال : وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وقال النبي ﷺ: التائب من الذنب من الذنب كمن لا ذنب له فأنت يا أخي ليس عليك قضاء، هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10390/حكم-قضاء-الصلوات-لمن-تركها-عمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_444/44411.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":12458,"question":"مستمع يقول: سلمان أحمد سليمان يسأل ويقول: حصلت علي نومة في منتصف النهار حتى فاتتني صلاة الظهر، هل من الممكن أن أصلي الظهر مع العصر؟ وهل أبدأ بصلاة الظهر، أم أبدأ بصلاة العصر؟ جزاكم الله خيرًا، وحدثوني أيضًا عن الإقامة لكل من الفريضتين، جزاكم الله خيرًا.","title":"حكم من فاتته صلاة فريضة بسبب نوم أو غيره","answer":"الجواب:  من فاتته صلاة الظهر من أجل نوم، أو نسيان، أو غير ذلك، ثم انتبه؛ يبدأ بالظهر قبل العصر؛ لأن الله رتبهما، وفرض الظهر قبل العصر، فالواجب أن يبدأ بالظهر فيصليها، ثم يصلي العصر، ويسن الإقامة لكل واحدة، يقيم لكل واحدة، أما الأذان فقد كفى أذان أهل البلد، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10665/حكم-من-فاتته-صلاة-فريضة-بسبب-نوم-او-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40406.mp3","categories":["قضاء الفوائت"]},{"id":12644,"question":"مستمع أيضًا يسأل سؤالًا قريبًا من السؤال السابق يقول: إذا فاتني أداء صلاة العصر والمغرب؛ وذلك لسبب خارج عن إرادتي، ودخل العشاء، فهل يجوز قضاؤها مع العشاء؟","title":"كيفية أداء الصلوات الفائتة بسبب نوم أو نسيان","answer":"الجواب:  تبدأ بهما، تبدأ بصلاة العصر، ثم المغرب، ثم تصلي العشاء، وعليك أن تجتهد في البعد عن أسباب الترك والحذر، فإن المؤمن لا يتساهل في هذا الأمر، والله يقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهمم الصلاة، فمن تركها؛ فقد كفر ويقول ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة فالأمر عظيم، ولا يتخلف عنها إلا منافق، نسأل الله العافية. فالواجب عليك الحذر من مشابهة أهل النفاق، الواجب عليك المحافظة عليها في وقتها، فإذا نسيت منها شيئًا، أو نمت عنها، أو شغلت عن شيء؛ فعليك بالترتيب، تبدأ بالعصر، ثم المغرب، ثم العشاء، هكذا بالترتيب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10854/كيفية-اداء-الصلوات-الفاىتة-بسبب-نوم-او-نسيان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45714.mp3","categories":["قضاء الفوائت"]},{"id":12729,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية إفريقيا الوسطى، باعث الرسالة أحد الإخوة المستمعين يقول: تلميذكم محمد أحمد عمر، وجنسيته تشادي، الأخ محمد يقول: إذا فاتتني صلاة وأنا مسافر، هل أقضيها على هيئة صلاة المسافر قصرًا وجمعًا، أم أتمها، وكل صلاة في وقتها؟","title":"حكم من فاتته صلاة في السفر وذكرها في الحضر","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالمسافر إذا فاتته صلاة وهو في السفر، وأداها في الحضر؛ فإنه يؤديها أربعًا، يسردها كلها لقول النبي ﷺ: من نام عن الصلاة، أو نسيها؛ فليصلها إذا ذكرها، لا كفارة لها إلا ذلك فإذا نسيها في السفر، أو نام عنها، فلم يتنبه إلا بعدما جاء بلده؛ فإنه يصليها تامة كاملة، ويسردها في الحال، سواء ثنتين، أو ثلاثًا، أو أكثر، يسردها في الحال، ولا يؤخر. وهكذا لو فاتته صلاة من الحضر، وذكرها في السفر؛ فإنه يصليها في السفر تامة؛ لأنها وجبت عليه تامة، وقد خرج وقتها تامة؛ فيصليها أربعًا في السفر إذا ذكرها، إن كان قد نسيها؛ فإنه يصليها أربعًا إذا ذكرها في السفر. وهكذا صلاة السفر إذا ذكرها في الحضر؛ فإنه يصليها أربعًا؛ لأنه ذكرها حين وجبت عليه الصلاة تامة؛ فيصليها أربعًا، أما لو فاتته صلاة السفر، وذكرها في السفر؛ صلاها ثنتين، مثلًا نسي الظهر يوم الثلاثاء، وذكرها في يوم الأربعاء وهو بالسفر، ما زال في السفر؛ يصليها ثنتين؛ لأنها تركها في السفر وذكرها في السفر؛ فيصليها ثنتين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10942/حكم-من-فاتته-صلاة-في-السفر-وذكرها-في-الحضر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46101.mp3","categories":["قضاء الفوائت"]},{"id":12742,"question":"تقول: أنا عمري الآن سبع وعشرون سنة، وكنت فيما مضى أصلي وأقطع، لكني الآن -والحمد لله- أثابر على الصلاة دون انقطاع، وإنني أصلي لكل فرض في وقت الصلاة المكتوبة مع السنة القبلية والبعدية، والقضاء أيضًا؛ لذلك أطيل في صلاتي، وأنا في بعض الأحيان أكون مشغولة، ولا أملك متسعًا من الوقت لأداء القضاء، فما هو رأي سماحتكم في ذلك، جزاكم الله خيرًا؟","title":"حكم قضاء الصلوات لمن تركها عامداً","answer":"الجواب:  التوبة كافية يا بنتي، التوبة كافية، التوبة مما مضى كافية، والحمد لله، وليس عليك قضاء، وإنما عليك أن تستقيمي على طاعة الله، وأن تحافظي على الصلاة في أوقاتها حتى الموت، أما الماضي فعليك التوبة الصادقة والندم، وعليك أن تسألي الله المغفرة والعفو، ويكفي هذا، والحمد لله؛ لأن الله يقول -جل وعلا-: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ويقول النبي ﷺ: التوبة تهدم ما كان قبلها ويقول -عليه الصلاة والسلام-: التائب من الذنب كمن لا ذنب له نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10956/حكم-قضاء-الصلوات-لمن-تركها-عامدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41813.mp3","categories":["قضاء الفوائت"]},{"id":12905,"question":"أخذني النوم ذات يوم عن صلاة الفجر، ولم أستيقظ إلا بعد طلوع الشمس، واحترت هل أصلي النافلة أولًا -رغيبة الفجر- ثم الفريضة، أم أبدأ بالفريضة، كيف يكون الحال لو تكرر الأمر مرة أخرى، جزاكم الله خيرًا؟","title":"حكم من نام عن صلاة الفجر حتى طلعت الشمس","answer":"الجواب:  السنة أن تبدأ بسنة الفجر بالركعتين، تصلي ركعتين خفيفتين سنة الفجر، ثم تصلي الفريضة، هكذا فعل النبي ﷺ لما ناموا عن الصلاة في بعض أسفاره ﷺ نام عن الصلاة هو وأصحابه في بعض أسفاره، فلم يستيقظوا إلا بحر الشمس، فلما استيقظوا؛ أمر بالأذان، فأذن بلال، وتوضؤوا، وصلى السنة الراتبة، ثم أمر بالإقامة، وصلوا الفريضة، هذا هو المشروع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11120/حكم-من-نام-عن-صلاة-الفجر-حتى-طلعت-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46807.mp3","categories":["قضاء الفوائت"]},{"id":13089,"question":"نختم هذا اللقاء بسؤال للسائل يوسف حسن يقول: هل يجوز لمن فاتته صلاة الظهر أن يصليها مع جماعة مع من يصلون العصر؟","title":"حكم تأخير قضاء الصلاة الفائتة","answer":"الجواب:  إذا كان الجماعة مسافرين؛ يصلونها في وقت الظهر، صلاها معهم وإلا فيجب أن يصلي في وقت الظهر، لا يؤخرها، يصلي الظهر إذا فاتته مع الجماعة، يصليها في المسجد، أو في بيته حالًا، فإن وجد جماعة يصلون؛ صلى معهم، سواء كانوا مقيمين، أو مسافرين، صلى معهم، فإذا سلموا قام وكمل، أما أن يؤخرها إلى العصر لا، ما يجوز تأخيرها. المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11306/حكم-تاخير-قضاء-الصلاة-الفاىتة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50721.mp3","categories":["قضاء الفوائت"]},{"id":13129,"question":"سؤاله الأخير يقول: هل يجهر المصلي في صلاة الفجر بعد طلوع الشمس، سواء كان منفردًا، أو جماعة؟","title":"هل يُجهر في قضاء صلاة الفجر؟","answer":"الجواب:  نعم، إذا فاتته الصلاة في الفجر، وصلاها منفردًا؛ يجهر حتى ولو بعد طلوع الشمس، يصليها جهرًا، صلى النبي ﷺ لما نام عن الصلاة حتى طلعت الشمس هو وأصحابه في بعض أسفاره، صلاها جهرًا -عليه الصلاة والسلام- كما كان يصلي في الوقت -عليه الصلاة والسلام- صلى السنة الراتبة، أمر بالأذان، وصلى السنة الراتبة، ثم أقيمت الصلاة، وصلى الفريضة -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11355/هل-يجهر-في-قضاء-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47407.mp3","categories":["قضاء الفوائت"]},{"id":13361,"question":"هذا السائل أبو محمد من الزلفي يقول في هذا  أثناء فترة الشباب كان يفوتني البعض من الصلوات، مثل العصر والفجر على سبيل المثال، والحمد لله الآن أقضي جميع الصلوات الخمس في المسجد، وأصلي مع الجماعة، وأحرص على ألا يفوتني أي فرض، وأفكر كيف أقضي ما فاتني في فترة الشباب؟ هل ممكن أن أقضي مع كل فرض فرضًا بما فاتني، حتى ولو بين الأذان والإقامة، أرجو منكم بيان ذلك؟","title":"حكم قضاء الصلاة بعد التوبة من تركها","answer":"الجواب: ليس عليك قضاء، والتوبة تجب ما قبلها، والحمد لله؛ لأن ترك الصلاة كفر، ولا خلاص منه إلا بالتوبة، ما دمت تبت من ذلك، والحمد لله فلا قضاء عليك، التوبة تجب ما قبلها؛ لأن من ترك الصلاة كفر، فإذا تاب، ورجع إلى الحق والهدى؛ فليس عليه قضاء، ولم يأمر النبي ﷺ المرتدين أن يقضوا، والصحابة لم يأمروا المرتدين أن يقضوا، فلما أسلموا لم يأمرهم أن يقضوا ما فاتهم من صيام أو صلاة، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11646/حكم-قضاء-الصلاة-بعد-التوبة-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52404.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":13450,"question":"من جدة السائلة التي رمزت لاسمها بـ (ر. خ. ع) تقول: ما حكم الترتيب بين الصلوات إذا كانت هذه الصلوات كثيرة، ويخاف الإنسان إن صلى هذه الفروض الفائتة أن يخرج وقت فرض الصلاة الذي يريد أن يؤديها؟ أفتونا بذلك.","title":"حكم من عليه صلاة فائتة ويخشى خروج الحاضرة","answer":"الجواب: يصلي حسب التيسير، ويبدأ بالفرض الحاضر، إذا خاف الوقت، خروج الوقت؛ يصلي الفرض الحاضر قبل خروج الوقت، ثم يصلي بقية الفوائت التي عليه، وأما إذا كان الوقت واسعًا؛ يبدأ بالفوائت أولًا، فإذا ضاق الوقت؛ صلى الصلاة الحاضرة، ثم صلى بقية ما عليه، وعليه أن يعتني بهذا الأمر، ويكون عنده العناية التامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11749/حكم-من-عليه-صلاة-فاىتة-ويخشى-خروج-الحاضرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52718.mp3","categories":["قضاء الفوائت"]},{"id":13580,"question":"في فقرته الثانية يقول: هل يجب على تارك الصلاة إذا عاد إلى الله، وهداه الله أن يقضي الصلوات التي تركها عمدًا؟","title":"هل تُقضى الصلوات المتروكة عمدًا بعد التوبة؟","answer":"الجواب: ليس عليه قضاء، إذا هداه الله وتاب؛ ليس عليه قضاء، كسائر الكفرة إذا تابوا ليس عليهم شيء، ليس عليهم قضاء ما تركوا من صوم، ولا صلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11912/هل-تقضى-الصلوات-المتروكة-عمدا-بعد-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53302.mp3","categories":["قضاء الفوائت"]},{"id":13607,"question":"هذا سائل للبرنامج إسماعيل سوداني يعمل بالمملكة يقول: هل تارك الصلاة يعيد ما عليه، تارك للصلاة، ثم تاب، هل يقضي ما ترك من الصلوات؟","title":"هل تارك الصلاة يقضي ما ترك من الصلوات؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالتارك للصلاة عامدًا الصواب أنه لا إعادة عليه، وعليه التوبة؛ لأنه يكفر بذلك، والكافر يكفيه الإسلام والتوبة، فمن كفر فلا يعيد ما مضى من صلاة، ولا رمضان، ولا غير ذلك، وعليه العمل من جديد، هذا هو الواجب على من ارتد عن دينه، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال تعالى: وَمَنْ يَكْفُرْ بِالإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الآخِرَةِ مِنَ الْخَاسِرِينَ [المائدة:5]. فالواجب عليه التوبة إلى الله، والرجوع إليه، والإنابة إليه، والعناية بالصلاة، والمحافظة عليها مستقبلًا، وليس عليه قضاء ما مضى؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه؛ ولقوله -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر أخرجه الإمام أحمد، وأهل السنن بإسناد صحيح، وقوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة والأدلة في هذا كثيرة. فالواجب على كل مسلم، وعلى كل مسلمة العناية بالصلاة، والمحافظة عليها في أوقاتها، هذا هو الواجب على جميع المسلمين رجالًا ونساء، الواجب العناية بالصلاة، والمحافظة عليها في الوقت؛ لقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] يعني: العصر. وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238]؛ ولقوله -جل وعلا-: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]؛ ولقوله -عليه الصلاة والسلام-: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45]؛ ولما تقدم من الأحاديث. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11946/هل-تارك-الصلاة-يقضي-ما-ترك-من-الصلوات ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52801.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":13678,"question":"امرأة في حالة ولادة، قبل يومين، أو ثلاثة من الولادة، ولم ينزل منها دم، ولكنها في حالة إغماء، ماذا تعمل؟ هل تقضي الصلاة بعد انتهاء مدة النفاس؟","title":"حكم من فاتتها الصلاة بسبب الإغماء قبل الولادة","answer":"الجواب: تقضي الصلاة إذا طهرت؛ لأن الإغماء مثلما تقدم يومين ثلاث مثل النوم، أقرب ما له النوم، فالأرجح أنها تقضي، يُشبَّه بالنوم، وقد روي عن بعض الصحابة أنه أغمي عليه يومين، أو ثلاثة؛ فقضى. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12027/حكم-من-فاتتها-الصلاة-بسبب-الاغماء-قبل-الولادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52919.mp3","categories":["قضاء الفوائت","قضايا المرأة"]},{"id":13917,"question":"هذه رسالة وصلت من مستمع للبرنامج يقول: من نام عن صلاة الوتر ولم يذكر ذلك إلا بعد صلاة الظهر كيف يقضيها؟","title":"كيفية قضاء صلاة الوتر","answer":"الجواب: يقضيها شفعًا، كان النبي ﷺ إذا فاته ورده من الليل لمرض أو نوم قضاه من النهار شفعًا، كما قالت عائشة رضي الله عنها، يعني إذا كانت عادته ثلاثًا يصلي من النهار أربع تسليمتين، وإذا كان عادته في الليل يوتر بخمس صلى من النهار ست ركعات، يسلم من كل ثنتين، وإذا كان عادته إحدى عشر كالنبي ﷺ صلى من النهار اثنا عشر، ست تسليمات كما كان النبي يفعل عليه الصلاة والسلام، هذا هو الأفضل، وإذا لم يتيسر الضحى وصلاه بعد الظهر فلا بأس، لكن الأفضل أن يكون قبل الظهر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12327/كيفية-قضاء-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54413.mp3","categories":["الوتر وقيام الليل","قضاء الفوائت"]},{"id":13925,"question":"هذه رسالة وصلت من مستمع للبرنامج يقول: من نام عن صلاة الوتر ولم يذكر ذلك إلا بعد صلاة الظهر كيف يقضيها؟","title":"كيفية قضاء صلاة الوتر","answer":"الجواب: يقضيها شفعًا، كان النبي ﷺ إذا فاته ورده من الليل لمرض أو نوم قضاه من النهار شفعًا، كما قالت عائشة رضي الله عنها، يعني إذا كانت عادته ثلاثًا يصلي من النهار أربع تسليمتين، وإذا كان عادته في الليل يوتر بخمس صلى من النهار ست ركعات، يسلم من كل ثنتين، وإذا كان عادته إحدى عشر كالنبي ﷺ صلى من النهار اثنا عشر، ست تسليمات كما كان النبي يفعل عليه الصلاة والسلام، هذا هو الأفضل، وإذا لم يتيسر الضحى وصلاه بعد الظهر فلا بأس، لكن الأفضل أن يكون قبل الظهر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12327/كيفية-قضاء-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54413.mp3","categories":["الوتر وقيام الليل","قضاء الفوائت"]},{"id":13958,"question":"نويت إن استيقظت في منتصف الليل لأصلي الوتر، وعندما استيقظت مبكرًا صليت قبل أن أصلي الوتر لكن أخذني الوقت قبل أن أصلي الوتر فأذن الفجر، فهل أصلي الوتر بعد دخول صلاة الفجر؟ أو أصلي الفجر وأترك الوتر لما بعد الصلاة؟","title":"ما وقت قضاء الوتر؟","answer":"الجواب:\n\nإذا أذن الفجر ولم يوتر الإنسان أخره إلى الضحى، والضحى بعد ارتفاع الشمس يصلي ما تيسر، يصلي ثنتين أو أربع ثنتين ثنتين.\n\nفإذا كانت عادته ثلاثًا ولم يصلها صلها الضحى أربعًا تسليمتين، فإذا كان عادته خمسًا فلم يتيسر فعلها في الليل صلاها الضحى ستًا بثلاث تسليمات، وهكذا، كان ﷺ في الغالب يوتر بإحدى عشر، فإذا شغله مرض أو نوم صلاها من النهار ثنتين عشر ركعة، هكذا قالت عائشة -رضي الله عنها-، صلاها اثنتي عشر ركعة يعني ست تسليمات، يسلم من كل ثنتين ﷺ فهذا هو المشروع للأمة اقتداءً به ﷺ.","link":"https://binbaz.org.sa/fatwas/12370/ما-وقت-قضاء-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60415.mp3","categories":["قضاء الفوائت","الوتر وقيام الليل"]},{"id":14060,"question":"من المملكة الأردنية الهاشمية خريبة السوق هذه رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (م. س. ع) ، أختنا تقول في سؤال لها: إنني كنت في رمضان أفطر دائمًا، وعندما هداني الله، وأحسست بالإيمان لم أعد إلى ذلك، هل هنا أحاسب على جميع ما أفطرته قبل الهداية والتوبة إلى الله؟ أم علي القضاء لجميع ما أفطرت؟ مع العلم أنني لا أحصي ما أفطرت، بماذا تنصحونني أن أفعل؟ كذلك الصلاة لم أكن أصلي من قبل، والحمد لله الآن مداومة عليها وملتزمة بها، أرجو منكم التوضيح. جزاكم الله خيرًا.","title":"حكم قضاء الصلاة والصيام على من تركهما","answer":"الجواب: الواجب عليك التوبة، وقد من الله عليك بذلك والحمد لله، فعليك أن تلزمي التوبة، وأن تكثري من الاستغفار والعمل الصالح وصلاة النافلة، والصدقات إذا استطعت، كثرة التسبيح والتهليل والتحميد والتكبير والاستغفار، كل ذلك من أسباب كمال التوبة، ومن أسباب المغفرة، وليس عليك قضاء الصلاة ولا الصوم؛ لأن ترك الصلاة كفر، والكافر إذا أسلم ليس عليه قضاء، وقد قال عليه الصلاة والسلام في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة؛ فمن تركها فقد كفر، خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة بن الحصيب رضي الله تعالى عنه، وقال عليه الصلاة والسلام أيضًا: بين الرجل وبين الكفر والشرك ترك الصلاة، خرجه الإمام مسلم في صحيحه عن جابر بن عبد الله رضي الله تعالى عنهما، في أحاديث أخرى تدل على كفر تارك الصلاة.\nوقد ذكر عبد الله بن شقيق العقيلي التابعي الجليل عن الصحابة  -أصحاب النبي ﷺ- أنهم كانوا يرون أن ترك الصلاة كفر، وقال: كانوا لا يرون شيئًا من الأعمال تركه كفر إلا الصلاة، فالصلاة أمرها عظيم وهي عمود الإسلام، من حافظ عليها فقد حفظ دينه، ومن ضيعها فقد ضيع دينه.  فأنت إذا من الله عليك بالتوبة من ترك الصلاة وترك الصوم؛ فليس عليك قضاء والحمد لله، وإنما عليك التوبة الصادقة والاستقامة عليها، وحمد الله على ذلك وشكره على ذلك، والاستكثار من أعمال الخير: من صدقات -ولو بالقليل- من الاستغفار الكثير، التسبيح والتهليل والتحميد والتكبير، وغير ذلك من وجوه الخير: كصوم التطوع، وكثرة الدعاء والضراعة إلى الله أن يتقبل منك وأن يعفو عنك.  أما من ترك الصوم، ولكنه يصلي، مسلم يصلي لكن تساهل في الصيام؛ فإنه يقضي، يقضي ما عليه من الصيام؛ لأن ترك الصيام ليس ردة عن الإسلام، ولكنه معصية عظيمة، فمن ترك الصوم شهرًا أو أكثر أو أقل؛ فعليه القضاء؛ مادام مسلمًا يصلي، وليس معه ما يوجب ردته وكفره، فإن عليه القضاء؛ لأن الرسول ﷺ أمر الحيض بقضاء الصوم فعليهن القضاء، وهكذا من تعمدت ترك الصوم بغير عذر، ولكنها تصلي؛ فإن عليها القضاء أيضًا، وهكذا الرجل الذي تساهل في الصيام وهو مسلم يصلي؛ فإنه يقضي أيضًا ويتحرى الأيام التي تركها إذا كان لا يعلمها، يتحرى، ويعمل بظنه في ذلك ويقضي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12485/حكم-قضاء-الصلاة-والصيام-على-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60805.mp3","categories":["قضاء الصيام","قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":14245,"question":"السائل الذي رمز لاسمه (س. ع. ع) ، الرياض، يقول: سماحة الشيخ! أنا شاب في العشرين من العمر ذهبت إلى الدراسة خارج المملكة، وقد مر علي شهر رمضان في إحدى السنوات الأولى في بعثتي ولم أصم ذلك الشهر للأسف من باب التفريط، وكذلك لم أكن أؤدي الصلوات في تلك السنة، ولكن بعدما رجعت تبت إلى الله والحمد لله، ماذا أفعل في هذا الشهر الذي لم أصمه، هل أقضيه متواصل أم متفرق؟ أم ماذا ترون سماحة الشيخ؟","title":"هل يقضي الصلاة والصيام من تاب من تركهما؟","answer":"الجواب: مادمت لا تصلي فالذي ما يصلي كافر، والتوبة تجب ما قبلها، فلا صوم ولا صلاة لا تقضي الصوم ولا الصلاة؛ لأن من ترك الصلاة كفر؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، لكن لو قضيت الصيام خروجًا من خلاف من قال: إنه لا يكفر كفرًا أكبر إذا كان لا يجحد وجوبها فلا بأس، لكن الصواب أنه يكفر تارك الصلاة وإن لم يجحد وجوبها، والكافر يكفيه التوبة، قال الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38]، وقال جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا [الزمر:53]، فالتوبة تجب ما قبلها وليس عليك قضاء إذا كنت لا تصلي كما قلت في السؤال. نعم.\nالمقدم: وبالنسبة للصلوات التي تركها.\nالشيخ: لا يقضي الصوم ولا الصلاة التوبة تجب ما قبلها.\nالمقدم: طيب جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12701/هل-يقضي-الصلاة-والصيام-من-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53015.mp3","categories":["قضاء الصيام","قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":14632,"question":"يسأل أخونا أيضًا ويقول: في أحد الأيام لم أستطع تأدية صلاة الصبح بسبب النوم، فكيف أقضيها لو سمحتم؟","title":"كيفية قضاء صلاة الفجر لمن نام عنها؟","answer":"الجواب: الواجب على المسلم أن يتخذ الأسباب التي تعينه على صلاة الفجر في الجماعة، وهكذا بقية الصلوات، فإذا كان المانع السهر، فالواجب عدم السهر أن ينام مبكرًا حتى يقوم للصلاة في وقتها، فإن كان المانع ما عنده من يوقظه فيتخذ ساعة منبهة يرشدها على الوقت المطلوب، حتى إذا جاء الوقت سمع المنبه، فقام إلى الصلاة، أو يؤكد على أهله الذين يثق بهم أن يوقظوه في الوقت. أما التساهل وعدم المبالاة فهذا معناه الموافقة على ترك الصلاة، وعدم المبالاة بها، والعياذ بالله، فيكون آثمًا ومتشبهًا بأعداء الله المنافقين، الذين قال فيهم سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142] وقال النبي : أثقل الصلاة على المنافقين صلاة العشاء وصلاة الفجر وقال ابن مسعود : لقد رأيتنا ومن يتخلف عنها يعني: الصلاة في الجماعة إلا منافق معلوم النفاق. فالواجب على كل مسلم، وعلى كل مسلمة الحذر من التساهل بالصلاة، والواجب اتخاذ الأسباب المعينة على أدائها في الوقت، الفجر وغيره في جميع الأوقات، فالذي يسهر يجب عليه ألا يسهر حتى يقوم لصلاة الفجر، والذي يتساهل في عدم توكيد الساعة على الوقت المطلوب يعتني بالساعة، ويوكدها على الوقت المطلوب حتى يسمع التنبيه، والذي عنده أهل يوقظونه يوصيهم بذلك، يفعل الأسباب التي تعينه على أداء الصلاة، وليس له التساهل في ذلك أبدًا، وهكذا بقية الصلوات، يعتني بالأسباب التي تعينه على أدائها في الوقت، ولا يتساهل في ذلك حتى يكون في ذلك متشبهًا بالمنافقين، نسأل الله للجميع الهداية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13159/كيفية-قضاء-صلاة-الفجر-لمن-نام-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62711.mp3","categories":["قضاء الفوائت"]},{"id":14668,"question":"المستمع (س. ف. ع) من العراق، يسأل ويقول: فاتتني صلاة الظهر والعصر هل لي أن أقضيهما جمعًا وقصرًا؟","title":"هل تُقضى الصلاة جمعًا وقصرًا؟","answer":"الجواب: هذا فيه تفصيل: إن كنت في السفر وقضيتها في السفر تقضيهما قصرًا ثنتين ثنتين، إن كنت في السفر، تركتها في السفر وقضيتها في السفر نفسه، فأنت تقضيهما قصرًا، ولك أن تجمع بينهما، ولك أن تفرق. أما إن كنت تركتهما في الحضر أو في السفر، ثم أتيت الحضر محل الإقامة، فإنك تقضيهما أربعًا أربعًا، ولا تجمع بينهما، وهكذا إذا تركتهما في الحضر وقضيتهما في السفر، أو في الحضر فإنك تقضيهما أربعًا، كما شرع الله ، وإنما تقضيهما قصرًا إذا كنت تركتهما في السفر وقضيتهما في السفر، ولك أن تجمع بينهما أيضًا في السفر، إذا كنت تركتهما في السفر وقضيتهما في السفر جميعًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13187/هل-تقضى-الصلاة-جمعا-وقصرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_628/nour_62809.mp3","categories":["قضاء الفوائت"]},{"id":14755,"question":"يقول أحدهما: كان لي والد مريض، وكان عاجزًا عن استعمال الماء وعن التيمم، ولم يصل فترة مرضه، وهي مدة خمسة عشر يومًا، ولما شفي من مرضه قضى الصلوات تلك، كل فرض مع ما يقابله من الفروض، فما هو رأيكم؟جزاكم الله خيرًا.","title":"حكم من ترك الصلاة أيام مرضه ثم قضاها","answer":"الجواب: أولاً هو غلطان، الواجب عليه أنه يفعل المستطاع، إن استطاع الماء توضأ، وإلا تيمم، وإن عجز يممه غيره: يممه أخوه أو زوجته أو غير ذلك، يضرب التراب بيديه، ويمسح به وجهه وكفيه بالنية عنه، يقول له: افعل، يأمره وهو ينوي، المريض ينوي والخادم أو وكيله يضرب التراب بيديه ويمسح بها وجهه وكفيه، إذا كان عاجزًا هو، أما أنه يصلي بدون وضوء وبدون تيمم هذا ما يجوز هذا.  وكونه يترك الصلاة لا يجوز أيضًا كل ذلك غلط منه، فإذا كان تركه لهذه العلة يظن أنه معذور بعجزه عن التيمم هذا عليه القضاء، ويقضي حالاً ما هو كل صلاة مع صلاة، لا، يقضيها جميعًا، ولو في وقت واحد، ولو في ضحوة واحدة يسردها. أما قول العامة: كل صلاة مع صلاة هذا لا أصل له، الذي عليه صلوات يسردها سردًا، في الضحى أو في الظهر الحمد لله، أو في الليل حسب طاقته يسردها، وليس لأحد أن يؤخر الصلاة لأجل ما عنده ماء ولا عنده تيمم، لا، بل يلزمه الوضوء، فإن لم يتيسر الماء تيمم، يحضرون له تراب من التراب الطيب ويضرب به يديه ويمسح وجهه وكفيه، فإن عجز لأنه ما يستطيع الحركة مريض، فالخادم الذي عنده الثقة، أو أخوه أو أمه أو أبوه ييممونه، يأمرهم بأن ييممونه وينوي هو بقلبه التيمم، ويضربون التراب ويمسحون وجهه وكفيه بالنية بالنيابة عنه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13244/حكم-من-ترك-الصلاة-ايام-مرضه-ثم-قضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49010.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":14765,"question":"يقول: إذا نام المسلم قبل صلاة العصر، ولم يكن هناك ما يوقظه، فلم يستيقظ إلا في صلاة المغرب أثناء إقامة الصلاة، فهل يصلي المغرب أولًا، أم يصلي العصر؟علمًا بأنه لو صلى العصر ستفوته صلاة جماعة المغرب.","title":"متى يصلي من نام عن العصر حتى المغرب؟","answer":"الجواب: لا بد من الترتيب، يصلي العصر، ثم يصلي المغرب، ما هو معذور في هذا يقدم المغرب؛ ولهذا لما فاتت النبي ﷺ صلاة العصر في يوم الأحزاب، صلاها ثم صلى المغرب -عليه الصلاة والسلام- صلاها بعد المغرب، ثم صلى المغرب. فالحاصل: أنه لو نام عن العصر أو نسيها ثم ذكر، فإنه يصلي العصر، ثم يصلي المغرب، نعم.","link":"https://binbaz.org.sa/fatwas/13252/متى-يصلي-من-نام-عن-العصر-حتى-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49012.mp3","categories":["قضاء الفوائت"]},{"id":14965,"question":"وردتنا رسالة من المستمع (س. ب. ف) يقول في رسالته: عندي امرأة أصيبت في حادث، وأصيبت في غيبوبة، ودامت الغيبوبة شهرًا وخمسة أيام، وثلاثة أشهر لم تحسن الصلاة. أفيدونا -جزاكم الله خيرًا- ما حكم صلاتها التي لم تصليها في السابق؟والسلام عليكم ورحمة الله وبركاته.","title":"حكم قضاء الصلاة لمن كانت في غيبوبة","answer":"الجواب: الصواب أنه لا قضاء عليها، من أصيب بحادث حتى غاب عنه شعوره؛ فهو من جنس المعتوه والمجنون، لا قضاء عليه، أما إن كانت المدة قليلة مثل يوم يومين ثلاثة فلا بأس أن يقضي، كالنائم كالمغمى عليه، أما إذا طالت المدة حتى صارت كثيرة؛ فإنه أشبه بالمجنون والمعتوه، فلا قضاء عليه، هذا هو الصحيح من أقوال العلماء.  أما إن كانت الغيبة يومين أو ثلاثة فهو أشبه بالنائم فيقضي، كما روي عن بعض الصحابة أنهم أغمي عليهم المدة اليسيرة اليوم واليومين والثلاث فقضوا، نعم.","link":"https://binbaz.org.sa/fatwas/13467/حكم-قضاء-الصلاة-لمن-كانت-في-غيبوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_650/nour_65006.mp3","categories":["قضاء الفوائت","قضايا المرأة"]},{"id":15053,"question":"ما حكم من منعه المرض أثناء عملية جراحية عن أداء الصلاة، هل يقضيها؟","title":"حكم من ترك الصلاة بسبب عملية جراحية","answer":"الجواب: نعم يقضيها، إذا لم يتيسر له فعلها بسبب العملية يقضيها، ولو بعد خروج الوقت، واجب عليه؛ لأنه تركها لعذر فيقضيها، والحمد لله، مثل الذي غلبه المرض حتى شغله عن الوقت، أو غلبه النوم يقضيها بعد ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13543/حكم-من-ترك-الصلاة-بسبب-عملية-جراحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49312.mp3","categories":["قضاء الفوائت"]},{"id":15068,"question":"نختم هذا اللقاء بهذا السؤال سماحة الشيخ، يقول السائل: هل يقضي الصلاة من تركها عمدًا إذا وفقه الله للتوبة، سواء كان ما تركه وقتًا واحدًا أو أكثر؟","title":"ما يلزم من تاب من ترك الصلاة؟","answer":"الجواب: التوبة تجب ما قبلها، ليس عليه قضاء، والتوبة تجب ما قبلها، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/13555/ما-يلزم-من-تاب-من-ترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56317.mp3","categories":["قضاء الفوائت"]},{"id":15080,"question":"هذا سائل سوداني، ومقيم بالمنطقة الشرقية، يقول سماحة الشيخ، يذكر في أنه في الحادية والثلاثين من العمر، يقول: كنت لا أصلي، ولا أصوم إلا القليل، وكنت لا أبالي في ارتكاب الآثام قبل ثماني سنين، وقد من الله علي  بالتوبة والاستقامة، أحمد الله على ذلك. فأرجو من سماحتكم أن توضحوا لي ماذا أعمل بالصوم الذي لم أصمه، ولا أدري عدد الشهور والأيام، وهل يلزمني إعادة الصلوات وهل علي الحج؟","title":"حكم قضاء الصلاة والصوم لمن تاب من تركهما","answer":"الجواب: التوبة تكفي، والحمد لله، التوبة تكفي، يقول النبي ﷺ: التوبة تجب ما قبلها ويقول ﷺ: التائب من الذنب كمن لا ذنب له وهذا هو معنى قوله سبحانه: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] أجمع العلماء على أن هذه الآية الكريمة في التائبين، وأن من تاب إلى الله من شركه وكفره تاب الله عليه، وهكذا من جميع المعاصي، فليس عليك -يا أخي- قضاء للصلاة الفائتة التي تركتها، ولا للصوم، الحمد لله، قد عفا الله عنك ذلك بتوبتك، وعليك بالجد والاجتهاد في طاعة ربك، والإكثار من العمل الصالح، والله يقول سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13571/حكم-قضاء-الصلاة-والصوم-لمن-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15126,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يبدو أنه نسي أن يذكر اسمه، إنما ضمن الرسالة جمعًا من الأسئلة، في بعضها يقول: إنسان تعوّد أن يصلي الوتر في آخر الليل، ولكن في بعض الأيام، لا يستيقظ إلا عند أذان الفجر، فهل يصليها بعد الأذان أو متى؟جزاكم الله خيرًا.","title":"متى يصلى الوتر لمن فاته بالليل؟","answer":"الجواب: يصليها في النهار، والحمد لله، كان النبي ﷺ إذا شغله مرض، أو نوم، صلى من النهار، تقول عائشة -رضي الله عنها-: كان ﷺ إذا شغله مرض أو نوم، صلى من النهار ثنتي عشرة ركعة وكان وتره ﷺ في الغالب بإحدى عشرة ركعة، فإذا نام ولم يستيقظ، أو شغله مرض، صلى من النهار ست تسليمات، ثنتي عشرة ركعة.  والأفضل أن يكون في الضحى، هذا هو الأفضل، وإن صلاها بعد الظهر فلا بأس، وليس بواجب، هذا سنة مستحب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13626/متى-يصلى-الوتر-لمن-فاته-بالليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49510.mp3","categories":["قضاء الفوائت","الوتر وقيام الليل"]},{"id":15302,"question":"هذا سؤال من المستمعة (ن. أ. ف) من حائل، تقول: سؤالي عن الصلاة؛ حيث أنني كنت مريضة لمدة ثلاث سنوات، ولم أصل في هذه الفترة إلا بعض الأوقات، أما الأوقات الأخرى فإني لم أستطع أن أصليها؛ لأنني كنت في حالة غيبوبة.وأيضًا أسأل عن الصيام فقد مضت سنتان لم أصم شهر رمضان فيهما من شدة المرض، وإلى الآن لم أستطع الصيام، أرجو إفادتي عماذا يجب علي فعله نحو الصيام والصلاة؟جزاكم الله خيرًا.","title":"حكم من تركت الصلاة والصيام لشدة المرض","answer":"الجواب: أما الصيام فعليك قضاء الصيام، فإذا كان تركه من أجل شدة المرض، فعليك قضاء الصيام إذا شفاك الله ؛ لأن الله قال : وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ[البقرة:185] أما إذا كان تركهما عن زوال عقل أصابك مرض أزال العقل، وصادف رمضان وأنت غير عاقلة قد زال العقل منك، فلا صيام عليك، إذا كانت المدة التي في رمضان والعقل مفقود فلا صيام؛ لأن التكليف مربوط بالعقل، فإذا زال العقل زال التكليف، أما إذا كان من شدة المرض فقط فعليك القضاء. وهكذا الصلاة؛ إن كنت تركت الصلاة من أجل زوال العقل، بسبب ما أصابك من الإغماء الذي فقدت معه العقل، حتى مضى عليك سنة أو سنتان وأنت غير عاقلة، قد ذهب عقلك فلا قضاء؛ لأن من ذهب عقله فهو شبه المجنون والمعتوه، لا قضاء عليه، أما إن كان من أجل المرض شدة المرض تساهلت ولم تصلي تحسبين أنه يجوز لكِ ذلك فعليك أن تقضي ما تركت من الصلوات التي غلب على ظنك أنك تركتيها بسبب شدة المرض، تقضينها حسب الطاقة، تسردين ما ظننت أنك تركتيه في كل وقت، تجمعين جملة من الصلوات فتقضينها لأنك تركتيها عن جهل منك وعن غلط منك بسبب المرض. والمريض يصلي على حسب حاله، يصلي قاعدًا، فإن عجز صلى على جنبه، فإن عجز صلى مستلقيًا لا يتساهل، النبي ﷺ قال للمريض: صل قائمًا فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هكذا يجب على المؤمن إذا مرض إن استطاع القيام صلى قائمًا، فإن عجز صلى وهو قاعد، ويركع ويسجد في الأرض، فإن عجز عن القعود صلى على جنبه، والأفضل على جنبه الأيمن، يقرأ ويكبر ويتعاطى ما شرع الله بالكلام، وينوي الأفعال بالنية، ينوي الركوع بالنية، ينوي السجود، ينوي الجلوس بين السجدتين بالنية، ينوي الجلوس في التحيات بالنية، ويأتي بالأقوال المشروعة من القراءة وغيرها، فإن عجز صلى مستلقيًا، يستلقي ويجعل رجليه إلى القبلة، ويصلي وهو مستلقي يكبر ويقرأ، يكبر ويركع بالنية، يقول: سمع الله لمن حمده بالنية، ويرفع بالنية، يقول: ربنا ولك الحمد، ثم يكبر ناويًا السجود، وهكذا من المضطجع على جنبه ومن المستلقي. أما إذا كنت قد فقدت الشعور قد فقدت عقلك فالمدة التي فقدت فيها عقلك المدة الطويلة، هذه لا صلاة فيها لا قضاء فيها، أما إذا كان المدة قليلة اليوم واليومين التي فقدت فيها عقلك، والباقي صاحية، فاليوم واليومين والثلاث تقضى كالنائم يقضي، فإذا طالت المدة أكثر من ثلاثة أيام طالت المدة بسبب فقد العقل والإغماء فلا قضاء على الصحيح. المقصود: أن عليك قضاء المدة التي تركت فيها الصلاة من أجل شدة المرض لا من أجل زوال العقل، فإذا كان من أجل شدة المرض هذا تساهل منك، وعليك القضاء مرتبًا؛ ظهر عصر مغرب عشاء فجر ظهر عصر، وهكذا مرتب، ولو في أيام قلائل، كل وقت تصلي فيه عدة صلوات حسب ظنك وغلبة ظنك تجتهدين وتصلينها -إن شاء الله-، هذا هو الأحوط لك والأفضل لك، نعم.\nالمقدم: بالنسبة للصيام؟\nالشيخ: والصيام كذلك، ما ترك من أجل شدة المرض تقضيه، وما كان عن زوال العقل يعني: ذهب عقلها، ولم يكن معها عقل فلا قضاء مثل المعتوه. المقدم: لا يلزمها شيء مع القضاء.\nالشيخ: ولا يلزمها إلا الصيام؛ لأنها معذورة. أما إذا كان تركك -أيها السائلة- للصلاة عن عمد وقلة مبالاة ما هو عن شبهة، وتظنين أن المرض عذر، فتركتها قلة مبالاة، وتساهلًا بها، هذا كفر وضلال، فلا تقضى بعد ذلك، التوبة تكفي، التوبة تكفي فقط؛ لأن الرسول ﷺ أخبر أن ترك الصلاة كفر، فقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فإذا كنت تركتها عمدًا لا عن شبهة، ولا عن ظن أنه يجوز لك تأخيرها من أجل المرض، فهذا منكر عظيم، وكفر صريح، فالتوبة تكفي، ولا قضاء عليك لما مضى؛ لأن تركها من غير عذر كفر وضلال وردة عن الإسلام في أصح قولي العلماء، فإذا تاب العبد من ذلك كفته التوبة فقط، نعم، نسأل الله السلامة، نعم.\nالمقدم: نسأل الله السلامة، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13821/حكم-من-تركت-الصلاة-والصيام-لشدة-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_682/nour_68205.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":15438,"question":"سؤاله الثالث يقول: أنا الآن أبلغ من العمر الثامنة والعشرين، ومنذ كان عمري سبع عشرة سنة، وأنا أصلي وأصوم، ولكن أحيانًا أترك الصلاة مدةً، ثم أعود إليها، فماذا علي الآن؟ هل يلزمني قضاء أم تكفي التوبة؟ وكيف أعمل وأنا ربما أجهل عدد الأيام التي تركت الصلاة فيها؟ وكذلك بالنسبة للصيام فقد أفطرت بعض الأيام بدون عذر، وأفطرت خلال أربع سنوات بسبب مرض، ولم يمنعني الأطباء من الصيام، ولكني أنا شعرت بضعف شديد، وهبوط في صحتي، فأفطرت، فماذا أفعل الآن؟أرشدوني، بارك الله فيكم.","title":"حكم قضاء الصيام والصلاة لمن يترك أحيانًا","answer":"الجواب: ترك الصلاة كفر أكبر، نعوذ بالله، تعمد ترك الصلاة كفر أكبر، يقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر ويقول -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة فترك الصلاة وإن كان تهاونًا كفر أكبر في أصح قولي العلماء. \nأما إن كان عن جحد لوجوبها، فهذا كفر أكبر عند جميع العلماء، لكن إذا كان عن تساهل وعن تهاون، فهذا كفر أكبر في أصح قولي العلماء. فعليك التوبة إلى الله، وليس عليك القضاء عليك التوبة الصادقة النصوح بالندم على ما مضى منك، والعزم الصادق على ألا تعود إلى هذا الشيء، والاستمرار في الصلاة، وليس عليك قضاء ما فات من الصيام والصلوات السابقة التي تركتها تهاونًا، فالصوم تابع لذلك؛ لأن ترك الصلاة كفر فليس عليك قضاء الصلاة، ولا قضاء الصيام. أما ما تركت من الصيام وأنت تصلي بعدما تاب الله عليك، وتركت هذا الذنب العظيم، فإنك تقضي الصيام. وأما إذا كان ترك الصيام في وقت ترك الصلاة، فإنك لا تقضيه، ولا تقضي الصيام؛ لأن المسلم إذا ارتد عن دينه لا يقضي، قال الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ[الأنفال:38] والنبي ﷺ يقول: الإسلام يهدم ما كان قبله، والتوبة تجب ما قبلها فإذا تاب الرجل من ترك الصلاة بعدما تركها تاب ورجع إلى الله، فإنه يستمر في العبادة، والعمل الصالح، ويسأل ربه المغفرة والعفو، وليس عليه قضاء، لا لصلاته ولا لصومه السابق الذي تركه في حال ترك الصلاة، نسأل الله السلامة. وعليك الصدق مع الله ودعائه -جل وعلا- أن يثبتك على الحق، وعليك الإكثار من العمل الصالح، كما قال الله -جل وعلا-: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى[طه:82] ولما ذكر سبحانه الشرك والقتل والزنا قال بعد هذا: إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا[الفرقان:70]. فنوصيك وجميع المسلمين بالتوبة إلى الله الصادقة النصوح من جميع الذنوب، ولا سيما ترك الصلاة، فإنه ذنب عظيم، وكفر عظيم، فعليك بالمبادرة والمسارعة إلى التوبة الصادقة، والعزم الصادق أن لا تعود، والاستمرار في الصلاة، وهكذا نوصي جميع من ترك الصلاة أن يتوب إلى الله، وأن يبادر بالتوبة الصادقة النصوح، وليس عليه قضاء لما ترك قبل ذلك، نعم. المقدم: بالنسبة لتعين القضاء هل بالنسبة للعدد هو يجهل عدد الأيام التي أفطرها؟\nالشيخ: ما دام أنه في حال ترك الصلاة ما عليه قضاء، أماإذا كان مسلمًا وهو يصلي، ما عنده ناقض من نواقض الإسلام فإنه يصوم ما غلب على ظنه. المقدم: يجتهد في التقدير. الشيخ: يجتهد ويصوم ما غلب على ظنه أنه تركه، أنه أفطر فيه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13965/حكم-قضاء-الصيام-والصلاة-لمن-يترك-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_686/nour_68603.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15470,"question":"هذان سؤالان بعثت بهما الأخت (ر. ف. ي. ل) من العراق، تقول: كانت والدتي تصوم وتصلي، وقد مرضت مرضًا شديدًا منذ سنتين توفيت على إثره، ولم تكن تصوم ولا تصلي في وقت مرضها؛ لعدم الاستطاعة، فهل يلزمني دفع كفارة عنها، أو الصيام والصلاة عنها؟أفيدوني، بارك الله فيكم.","title":"حكم قضاء الصلاة والصيام عمن مات مريضًا","answer":"الجواب: ما دامت ماتت وهي مريضة ما استطاعت الصيام، فليس عليك صيام عنها، إذا كانت ماتت وهي في مرضها، لم تستطع صيامها المدة الطويلة، فإنك لا تقضين عنها شيئًا، وليس عليك إطعام أيضًا، والحمد لله. أما الصلاة فقد غلطت في ترك الصلاة، كان الواجب عليها أن تصلي، ولو كانت مريضة، ولا تؤجل الصلاة، الواجب على المريض أن يصلي على حسب حاله، إن استطاع القيام صلى قائمًا، وإن عجز صلى قاعدًا، فإن لم يستطع القعود صلى على جنبه الأيمن -وهو الأفضل- أو الأيسر على حسب طاقته، فإن لم يستطع الصلاة على جنبه صلى مستلقيًا، هكذا أمر النبي ﷺ، لما شكا إليه بعض الصحابة  المرض قال له: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا. هذا هو الواجب على المريض ذكرًا كان أو أنثى، أن يصلي قاعدًا إذا عجز عن القيام، سواء قاعدًا مستوفزًا أو متربعًا، أو كجلسته بين السجدتين، كل ذلك جائز، فإن عجز عن القعود صلى على جنبه الأيمن أو الأيسر، والأيمن أفضل إذا استطاع، ينوي أذكار الصلاة وواجباتها، ويتكلم بما يستطيع يكبر، يقرأ الفاتحة أول  شيء، يقرأ ما تيسر ثم يكبر، وينوي الركوع، ثم يقول: سمع الله لمن حمده ناويًا الرفع: ربنا ولك الحمد، إلى آخره، ثم يكبر ناويًا السجود، يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم يرفع مكبرًا، ناويًا الجلوس بين السجدتين يقول: رب اغفر لي، رب اغفر لي، ثم يكبر ناويًا السجدة الثانية، وهكذا بالنية والكلام حسب طاقته. ولا تقضى الصلاة، الصلاة لا تقضى، وإنما عليك الدعاء لها، والترحم عليها، والاستغفار إذا كانت موحدة، إذا كانت مسلمة موحدة، أما إن كانت تدعو الأموات تستغيث بالأموات والقبور، تدعو غير الله، هذه لا يدعى لها؛ لأن هذا شرك أكبر، فإذا كانت في حياتها تدعو الأموات، تستغيث بالأموات، أو بأصحاب القبور، أو تسأل البدوي، أو عبد القادر، أو غير عبد القادر الجيلاني، هذا من الشرك الأكبر؛ لأن دعاء الأموات، والاستغاثة بالأموات، كأن يقول: يا سيدي عبد القادر، اشف مريضي، أو انصرني، أو عافني، أو يا سيدي فلان -من الأموات- افعل بي كذا، أو يا رسول الله، افعل بي كذا، أو يا سيدي البدوي، افعل كذا، أو يا فلان افعل كذا من الأموات، كل هذا من الشرك الأكبر، والذي يموت على هذه الحالة لا يدعى له؛ لأنه مات على ظاهر الشرك، نسأل الله السلامة. أما إن كانت موحدة بحمد الله، لا تدعو غير الله، بل تعبد الله وحده، يدعى لها، ويستغفر لها، ولا يصلى عنها؛ لأن الصلاة لا تقضى، نعم.","link":"https://binbaz.org.sa/fatwas/14000/حكم-قضاء-الصلاة-والصيام-عمن-مات-مريضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68803.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":15672,"question":"صلاة سنة الفجر إذا فاتت، متى يكون قضاؤها، وكذلك الوتر؟","title":"وقت قضاء سنة الفجر","answer":"الجواب: سنة الفجر إذا فاتت صلاها بعد الفجر في المسجد أو في البيت، وإن أجلها إلى طلوع الشمس وارتفاعها كان أفضل، كل هذا جاءت به السنة عن النبي ﷺ، فإن صلاها بعد الصلاة في المسجد أو البيت فلا بأس، وإن أخرها حتى تطلع الشمس وصلاها في المسجد أو في البيت فلا بأس، كله طيب كله، جاءت به السنة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14216/وقت-قضاء-سنة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70603.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":15859,"question":"هل على الإنسان الذي كان لا يصلي سابقًا، هل عليه قضاء الأوقات التي لم يصلها سابقًا؟ وهل يجوز القضاء في الأوقات الخمسة التي نهى النبي ﷺ عن الصلاة فيها؟","title":"هل يلزم تارك الصلاة قضاء الأوقات التي لم يصلها؟","answer":"الجواب: ليس عليه قضاء، إذا تاب اللهُ عليه، ليس عليه قضاء، إذا كان لا يصلي ثم تاب اللهُ عليه ليس عليه قضاء، التوبة تكفي، تجب ما قبلها، والحمد لله. والذي عليه قضاء الصلاة يقضيها ما لها وقت نهي، يقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك فإذا نسي -مثلًا- صلاة الظهر، ولم يذكرها إلا بعد العصر يبادر بقضائها، أو نسي صلاة العشاء فلم يذكرها إلا بعد صلاة الفجر يبادر بقضائها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14450/هل-يلزم-تارك-الصلاة-قضاء-الاوقات-التي-لم-يصلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57621.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":15882,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين آثر فيها عدم ذكر اسمه يسأل سؤالًا فيقول فيه: أنا شاب وعازب، في فترة شبابي الأولى كنت أصلي فترة، وأقطع الصلاة، والحمد لله، الآن تبت إلى الله وحده، إنني لا أقطع الصلاة، ومحافظ عليها في أوقاتها، فهل أقضي ما فاتني في تلك الفترة التي ذكرتها لكم، أو كيف يكون التوجيه؟جزاكم الله خيرًا.","title":"حكم قضاء الصلاة لمن كان يتركها أحيانًا","answer":"الجواب: الحمد لله الذي منَّ عليك بالتوبة، وهذه من نعم الله العظيمة، فعليك أن تشكر الله على ذلك، وأن تلزم التوبة، وتستقيم عليها.  وأما ما فات في بعض الصلوات التي أضعتها، فإنه لا قضاء عليها على الصحيح؛ لأن ترك الصلاة ولو كسلًا كفر أكبر على الصحيح، فإذا تاب العبد من ذلك ورجع إلى الله -جل وعلا- كفاه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14475/حكم-قضاء-الصلاة-لمن-كان-يتركها-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74502.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":16088,"question":"من سوريا الرقة السائل يوسف إبراهيم يقول: سماحة الشيخ! أسأل عن قضاء الصلاة في حال كون الإنسان لم يكن يصلي، وبلغ من العمر بعد سن البلوغ، والتكاليف، وهداه الله إلى الصلاة؛ هل يجب عليه أن يقضي ما فاته من صلاة؟ أم أن حديث الرسول ﷺ: الإسلام يجب ما قبله يشمله؟","title":"ما الواجب على من تاب من ترك الصلاة؟","answer":"الجواب: نعم، إذا كان الإنسان لا يصلي، ثم هداه الله؛ فالتوبة تجب ما قبلها، والإسلام يجب ما قبله، وهكذا المرأة إذا كانت لا تصلي، ثم هداها الله؛ ليس عليهما قضاء، التوبة تكفي، والحمد لله. يقول ﷺ: الإسلام يجب ما قبله، والتوبة تجب ما قبلها فمن كان لا يصلي؛ فالواجب عليه التوبة إلى الله، والرجوع إلى الله، والإنابة إليه، وليس عليه قضاء ما فات.. والحمد لله. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14728/ما-الواجب-على-من-تاب-من-ترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57908.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":16142,"question":"أخ لنا من السودان يقول: عبدالعزيز حسن من محافظة الجزيرة المسيب يسأل ويقول: أذن المؤذن لصلاة العصر، وذهبت للمسجد، وكانت علي صلاة الظهر لم أصليها لسبب ما، وكان الوقت قد أقيمت صلاة العصر، هل يكفيني أن أصلي العصر، أم لابد من صلاة الظهر أولًا، ثم أصلي العصر؟","title":"ما يفعل من حضرت صلاة العصر ولم يصل الظهر؟","answer":"الجواب: إذا كان هذا الواقع صل معهم بنية الظهر، صل معهم العصر وأنت ناويًا الظهر، والحمد لله، ثم تصلي العصر وحدك، أو مع جماعة إذا تيسر جماعة، ولا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14811/ما-يفعل-من-حضرت-صلاة-العصر-ولم-يصل-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80409.mp3","categories":["قضاء الفوائت"]},{"id":16213,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول في أسئلته في هذه الرسالة: إذا كان الإنسان لا يصلي، ولا يصوم في فترة من حياته، ثم تاب، وأقام الصلاة، وصام رمضان، هل يلزمه قضاء الصلاة، والصيام؟ أم لا؟","title":"حكم قضاء الصلاة والصيام على من تاب من تركهما","answer":"الجواب: الصواب أنه لا يلزمه ذلك، والتوبة تكفي، والحمد لله، التوبة الصحيحة النصوح تكفي، والحمد لله يقول النبي ﷺ: التوبة تجب ما قبلها، والإسلام يهدم ما كان قبله وتارك الصلاة يكفر بذلك، فإذا أسلم، وتاب؛ فليس عليه إعادة كسائر الكفار، إذا أرتد كسائر من ارتد، ثم رجع لا يقضي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14893/حكم-قضاء-الصلاة-والصيام-على-من-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75110.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":16484,"question":"من القصيم أخوكم الذي رمز لاسمه بـ (س. ر) يقول بأنه شاب يبلغ من العمر الثالثة والعشرين، يقول: وكنت فيما مضى من الأيام من عمري متهاونًا في أداء الصلوات، وحتى الصوم، فقد مرت علي شهور من رمضان أفطرت فيها أيامًا بدون عذر شرعي، وإنما تهاونًا، فإذا شعرت بالجوع، أو العطش؛ أفطرت، وبعد أن من الله علي بالتوبة، والهداية، وأيقنت بخطورة هذا الأمر؛ واظبت على الصلاة، ولكن الذي يؤلمني يا سماحة الشيخ هذه الأيام التي مضت من عمري عن تلك الصلوات، وعن أيام الصيام التي أفطرت فيها، كيف أبرئ ذمتي؟ جزاكم الله خيرًا.","title":"ما الواجب على من ترك الصلاة والصوم ثم تاب؟","answer":"الجواب: الواجب عليك يا أخي التوبة إلى الله، والحمد لله، ما دمت تبت إلى الله، وندمت، وأقلعت، وأصلحت؛ كفى ذلك، والحمد لله، ولا يلزمك قضاء الصلوات، ولا قضاء الصيام؛ لأن ترك الصلاة كفر، والتوبة تكفي، تجب ما قبلها، ما دمت تبت إلى الله؛ فالتوبة تجب ما قبلها، يقول النبي ﷺ: التوبة تجب ما قبلها ويقول ﷺ: التائب من الذنب كمن لا ذنب له. فالذي تاب من ترك الصلاة، وتاب من ترك الصيام، لا قضاء عليه، أما الصيام الذي تركته بعدما حافظت على الصلاة، إذا كنت تركت شيئًا من الصيام بعد أن حافظت على الصلوات؛ فإنك تقضي، أما الصيام الذي تركته مع ترك الصلاة؛ فالتوبة تكفي فيه، والحمد لله، أما إذا كان هناك أيام تركت صومها بعدما من الله عليك بالتوبة من ترك الصلاة؛ فإنك تقضيها. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15191/ما-الواجب-على-من-ترك-الصلاة-والصوم-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58213.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":16590,"question":"يسأل يقول: كيف تقضي المرأة التي تركت الصلاة، والصيام لعذرها الشرعي، كيف تقضي ما فاتها؟","title":"كيفية القضاء لمن تركت الصلاة لعذر أو متعمدة","answer":"الجواب: إن كان عذرها الحيض والنفاس؛ فليس عليها قضاء الصلاة، إنما تقضي الصوم فقط، صوم رمضان، أما إن كان عذرها نومًا، واستيقظت؛ تقضي إذا استيقظت من نومها، وأما إن كانت مجنونة، ثم رد الله عليها العقل؛ فليس عليها قضاء. أما إن كانت مريضة؛ فالواجب عليها أن تصلي في حال المرض، ولو على جنب، ولو مستلقية، فإن تساهلت جهلًا منها، ولم تصل لأجل المرض؛ تقضيها مرتبة، ولو في وقت واحد، حسب طاقتها مرتبة؛ ظهر، عصر، مغرب، عشاء، فجر، هكذا مرتبة، ولو في وقت واحد، ولو في ضحوة، أو في ظهر، أو في ليلة حسب طاقتها، إذا كان تركها لها عن مرض، تجهل أنها تصلي وهي قاعدة، أو على جنبها؛ تقضي. أما إن كان التساهل بالصلاة، تتركها عمدًا؛ فليس عليها قضاء، عليها التوبة، وهكذا الرجل الذي لا يصلي، ثم يتوب، ليس عليه قضاء، عليه التوبة إلى الله، والرجوع إلى الله، والاستقامة على الصلاة، وما فات قبل ذلك مما تركه عمدًا تساهلًا منه؛ فهذا فيه التوبة، وتكفيه التوبة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15323/كيفية-القضاء-لمن-تركت-الصلاة-لعذر-او-متعمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81706.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":16601,"question":"يسأل يقول: كيف تقضي المرأة التي تركت الصلاة، والصيام لعذرها الشرعي، كيف تقضي ما فاتها؟","title":"كيفية القضاء لمن تركت الصلاة لعذر أو متعمدة","answer":"الجواب: إن كان عذرها الحيض والنفاس؛ فليس عليها قضاء الصلاة، إنما تقضي الصوم فقط، صوم رمضان، أما إن كان عذرها نومًا، واستيقظت؛ تقضي إذا استيقظت من نومها، وأما إن كانت مجنونة، ثم رد الله عليها العقل؛ فليس عليها قضاء. أما إن كانت مريضة؛ فالواجب عليها أن تصلي في حال المرض، ولو على جنب، ولو مستلقية، فإن تساهلت جهلًا منها، ولم تصل لأجل المرض؛ تقضيها مرتبة، ولو في وقت واحد، حسب طاقتها مرتبة؛ ظهر، عصر، مغرب، عشاء، فجر، هكذا مرتبة، ولو في وقت واحد، ولو في ضحوة، أو في ظهر، أو في ليلة حسب طاقتها، إذا كان تركها لها عن مرض، تجهل أنها تصلي وهي قاعدة، أو على جنبها؛ تقضي. أما إن كان التساهل بالصلاة، تتركها عمدًا؛ فليس عليها قضاء، عليها التوبة، وهكذا الرجل الذي لا يصلي، ثم يتوب، ليس عليه قضاء، عليه التوبة إلى الله، والرجوع إلى الله، والاستقامة على الصلاة، وما فات قبل ذلك مما تركه عمدًا تساهلًا منه؛ فهذا فيه التوبة، وتكفيه التوبة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15323/كيفية-القضاء-لمن-تركت-الصلاة-لعذر-او-متعمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81706.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت","قضاء الصيام","قضايا المرأة"]},{"id":16627,"question":"من إحدى الأخوات المستمعات تقول: المرسلة فاطمة، أختنا تقول عن نفسها: إنني امرأة متزوجة، لم أصل منذ سبعة وثلاثين عامًا، جاء لي الأبناء، وأصبحوا يعلمونني الصلاة -جزاهم الله خيرًا- لكني محتارة في المدة الماضية، هل سيحاسبني الله عليها، أم توصونني بقضائها؟ أم كيف يكون توجيهكم؟ جزاكم الله خيرًا.","title":"ما النصيحة لمن تاب من ترك الصلاة؟","answer":"الجواب: نوصيك بالتوبة النصوح، التوبة التوبة، الندم على الماضي، والعزم على ألا تعودي فيه، والمحافظة على الصلاة من حين هداك الله، الزميها، وحافظي عليها في أوقاتها بالطمأنينة، والخشوع، وأبشري بالخير، التوبة تجب ما قبلها، يقول النبي ﷺ في الحديث الصحيح: التوبة تجب ما قبلها يعني تهدم ما قبلها، تمحوه، ويقول -عليه الصلاة والسلام-: التائب من الذنب كمن لا ذنب له. فأبشري بالخير، التوبة بحمد الله تكفي، ومعناها الندم على ما مضى منك من الترك، والحزن على ذلك، والعزم على ألا تعودي إليه، وتستمري على المحافظة، والاستقامة على الصلاة، وأبشري بالخير، وليس عليك قضاء، والذنب يمحى بالتوبة، والحمد لله. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15356/ما-النصيحة-لمن-تاب-من-ترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71608.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":16651,"question":"ما قول سماحتكم فيمن بلغت في سن صغيرة، ولم تتعرف على أحكام الدين، وأمور الشرع المتعلقة بها بالقدر الذي وصلت إليه من المعرفة بها حاليًا، فلم تصل، ولم تصم، ولم تتحجب عن الأجانب، ثم بعد أن عرفت أحكام الدين في هذا الأمر احتجبت، وأصبحت تصلي، وتصوم بعد أن كانت تصوم صيام الأطفال، تفطر متى شاءت، وتصوم متى طاقت ذلك، الآن هل يلزمها قضاء ما فاتها من الصيام، والصلاة؟ وهل يلزمها إلى جانب قضاء الصيام صدقة؟ وإذا كان هناك صدقة، فما مقدارها؟ علمًا بأن الفترة التي أمضتها، وهي جاهلة بأحكام الشرع، ولا تلتزم بها سنتان ونصف، جزاكم الله خيرًا.","title":"حكم قضاء الصلاة والصوم لمن تركهما بلا عذر","answer":"الجواب: الصواب أنه لا يلزمها شيء، ويكفي التوبة؛ لأن الرسول ﷺ لم يأمر الذين أسلموا أن يقضوا ما فاتهم من صلاة، وصيام؛ولأن ترك الصلاة كفر، فالتوبة تكفي في هذا، فإذا كانت لا تصلي، ولا تصوم، فالتوبة كافية، وليس عليها قضاء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15384/حكم-قضاء-الصلاة-والصوم-لمن-تركهما-بلا-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71714.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":16975,"question":"إذا فات الإنسان صلاة جهرية، وأراد أن يقضيها، فهل يكون ذلك سرًا، أو جهرًا؟","title":"كيف يقضي من فاتته صلاة جهرية؟","answer":"الجواب: السنة أن يقضيها جهرًا، في النهار إذا قضاها يقضيها جهرًا، النبي ﷺ لما نام عن صلاة الفجر، فلم يوقظه إلا حر الشمس في بعض أسفاره صلاها بعد طلوع الشمس جهرًا -عليه الصلاة والسلام- فجهر فيها بالقراءة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15763/كيف-يقضي-من-فاتته-صلاة-جهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_720/nour_72004.mp3","categories":["قضاء الفوائت"]},{"id":17153,"question":"إحدى الأخوات المستمعات عرضنا لها سؤالًا قبل هذا السؤال، تقول أختكم في الله (س. ع) من ليبيا، أختنا تسأل في هذه الحلقة عن قضية طولت في السؤال عنها، ملخص ما سألت عنه سماحة الشيخ: أنه مر فترة من عمرها، وكانت تصلي مرة، وتترك مرة حتى أنها أحصت عدد الركعات التي فاتتها، فما هو توجيهكم لها؟ جزاكم الله خيرًا.","title":"حكم قضاء الصلوات المتروكة بعد التوبة","answer":"الجواب: عليها التوبة ويكفي والحمد لله، عليها التوبة مما سلف، ومن تاب تاب الله عليه؛ لأن ترك الصلاة كفر، فالتوبة تكفي، ولا يلزمها القضاء، النبي ﷺ لم يلزم من ارتد، ثم أسلم بالقضاء، والصحابة كذلك لما أسلم من أسلم من المرتدين لم يأمروهم بالقضاء.  فالمقصود: أنه إذا أسلم بعد تركه الصلاة فإن عليه التوبة الصادقة والحمد لله، والعمل الصالح، ويكفي، يقول الله سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] فليس على من أسلم قضاء ما ترك من صيام ولا صلاة، إذا كان قد أتى ناقضًا من نواقض الإسلام كترك الصلاة، أو جحد بعض ما أوجب الله من صلاة، أو زكاة، أو نحو ذلك مما هو معروف من الدين بالضرورة، وقد أجمع عليه المسلمون، كل من حكمنا بكفره، ثم أسلم فإنه لا يقضي ما سلف. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15977/حكم-قضاء-الصلوات-المتروكة-بعد-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72213.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":17160,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل فيها جمعًا من الأسئلة في أحد أسئلته يقول: شاب كان تاركًا للصلاة، فمنَّ الله عليه بالتوبة، أفتى له بعض العلماء أن يقضي الصلاة التي فاتته، وإن لم يقضها قضاها في جهنم، أفتونا جزاكم الله خيرًا.","title":"هل يقضي فوائت الصلاة من تاب من تركها؟","answer":"الجواب: إذا كان تاركًا للصلاة، جاحدًا لوجوبها؛ فهذا لا قضاء عليه، وعليه التوبة، الرسول ﷺ لم يأمر الذين أسلموا بأن يقضوا ما مضى من الصلوات، والمرتدون في عهد الصحابة لما أسلموا لم يأمرهم الصحابة أن يقضوا ما تركوا من الصلوات. أما إن كان غير جاحد لوجوبها، بل تساهل، وتكاسل، وترك بعض الصلوات؛ فهذا في كفره خلاف؛ من أهل العلم من قال: يكفر كفرًا أكبر، وهو الأصح لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وذهب الجمهور إلى أنها كفر دون كفر، إذا كان ما جحد الوجوب يكون كفرًا دون كفر، وعليه القضاء، فهذا إن قضى من باب الاحتياط حسن. أما قول هذا المفتي: إنه يقضيها في جهنم! هذا لا أعلم له أصلًا، هذا لا أعلم له أصلًا، لكن على كل حال الصحيح أنه لا يلزمه القضاء، فإن قضى من باب الاحتياط، والخروج من الخلاف إذا كان ما جحد الوجوب، ولكن تكاسل، إن قضى فهذا حسن من باب الاحتياط، وإلا فلا يلزمه القضاء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15981/هل-يقضي-فواىت-الصلاة-من-تاب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76713.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":17246,"question":"تقول السائلة -سماحة الشيخ- أم أمل من ينبع: لقد بلغها الحيض، وهي في الرابعة عشرة من العمر، ومنذ أن بلغها الحيض -تقول:- حتى التاسعة عشرة من عمرها، لم تصل، ولم تصم، والآن تقول أم أمل: بأنها تابت إلى الله توبةً نصوحًا، وبدأت تصلي، وتحافظ على الصلوات، وتصوم، وتكثر من النوافل، وتحمد الله، تقول: وجهوني سماحة الشيخ تجاه ما فرطت، هل أقضي الصوم، والصلاة، ما مضى؟","title":"حكم قضاء الصلاة والصوم لمن تركهما عدة سنوات","answer":"الجواب: ليس عليك قضاء، التوبة تكفي، التوبة تجب ما قبلها، أسلمت على ما أسلفت من خير، والحمد لله، ليس عليك قضاء صلاة، ولا صوم، التوبة تجب ما قبلها، نسأل الله لنا ولك الثبات على الحق، الذين أسلموا لم يأمرهم النبي ﷺ بقضاء صوم، ولا صلاة، اللهم صل عليه وسلم.","link":"https://binbaz.org.sa/fatwas/16078/حكم-قضاء-الصلاة-والصوم-لمن-تركهما-عدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59123.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":17311,"question":"يسأل ويقول: هل على الجنب قضاء الصلاة التي فاتته؟","title":"حكم قضاء الصلاة الفائتة للجُنُب","answer":"الجواب: نعم، إذا فاتته الصلاة قبل أن يغتسل يقضيها، وهكذا الحائض لو أخرت الغسل إلى طلوع الشمس وهي طهرت في أول الوقت، أو في آخر الليل عليها أن تقضي صلاة الفجر، تصلي صلاة الفجر، ولا يجوز لها هذا العمل، ولا يجوز للجنب هذا العمل، يجب على الجنب أن يغتسل في الوقت، وهكذا الحائض يجب عليها أن تغتسل في الوقت، وتصلي في الوقت، لكن لو أخرا أثما.. أثما بهذا، وعليهما التوبة مع فعل الصلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16158/حكم-قضاء-الصلاة-الفاىتة-للجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83303.mp3","categories":["قضاء الفوائت"]},{"id":17325,"question":"يسأل ويقول: هل على الجنب قضاء الصلاة التي فاتته؟","title":"حكم قضاء الصلاة الفائتة للجُنُب","answer":"الجواب: نعم، إذا فاتته الصلاة قبل أن يغتسل يقضيها، وهكذا الحائض لو أخرت الغسل إلى طلوع الشمس وهي طهرت في أول الوقت، أو في آخر الليل عليها أن تقضي صلاة الفجر، تصلي صلاة الفجر، ولا يجوز لها هذا العمل، ولا يجوز للجنب هذا العمل، يجب على الجنب أن يغتسل في الوقت، وهكذا الحائض يجب عليها أن تغتسل في الوقت، وتصلي في الوقت، لكن لو أخرا أثما.. أثما بهذا، وعليهما التوبة مع فعل الصلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16158/حكم-قضاء-الصلاة-الفاىتة-للجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83303.mp3","categories":["قضاء الفوائت"]},{"id":17424,"question":"رسالة وصلت إلى البرنامج من المستمع خالد الحربي يقول في رسالته: يوجد لي جد مصاب بالجلطة، غاب عن ذهنه لمدة ثلاثة أشهر، وهو الآن قد عاد، وبدأ يذكر الصلاة، وبدأ يصلي، لكنه لم يصم بطبيعة الحال، فكيف توجهوننا وحاله ما ذكر؟ جزاكم الله خيرًا.","title":"حكم قضاء الفرائض لمن فقد عقله مدة من الزمن","answer":"الجواب:  ليس عليه قضاء ما فات في حال ذهاب عقله، وليس عليه قضاء الصوم إذا كان رمضان صادفه في المدة التي غاب فيها عقله؛ لأنه قد رفع عنه القلم، وإنما يصلي مستقبلًا بعدما رجع إليه عقله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16286/حكم-قضاء-الفراىض-لمن-فقد-عقله-مدة-من-الزمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83515.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":17607,"question":"يقول: يا سماحة الشيخ ماذا يفعل المريض بالصلوات التي فاتته وهو في العملية الجراحية تحت التخدير؟","title":"حكم من فاتته صلاة بسبب التخدير","answer":"الجواب: يقضيها إذا رجع إليه عقله يقضيها، يقضيها مثل النائم. نعم.","link":"https://binbaz.org.sa/fatwas/16536/حكم-من-فاتته-صلاة-بسبب-التخدير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59415.mp3","categories":["قضاء الفوائت"]},{"id":17756,"question":"تقول السائلة في آخر أسئلتها: كنت من قبل أضيع بعض الصلوات وأؤخرها عن وقتها ولكنني الآن تبت إلى الله توبة نصوحًا وأحافظ على الصلوات الخمس ماذا علي أن أفعل فيما سبق هل أعيد ما تركت؟","title":"حكم قضاء الصلاة للتائب من تركها","answer":"الجواب: التوبة كافية، الإنسان اللي ما يصلي أو يصلي تارة ويخلي تارة إذا تاب كفاه وليس عليه قضاء قال الله جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ[الأنفال:38]، ويقول النبي ﷺ: التوبة تجب ما قبلها، وفي الحديث الآخر: التائب من الذنب كمن لا ذنب له فليس على من ترك الصلاة ثم هداه الله، وتاب الله عليه ليس عليه القضاء لما مضى، ويكفيه التوبة، والحمد لله، التوبة والعمل الصالح، والاجتهاد في الخير كما قال تعالى في كتابه العظيم: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى[طه:82]. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16735/حكم-قضاء-الصلاة-للتاىب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77715.mp3","categories":["قضاء الفوائت"]},{"id":17870,"question":"من إحدى الأخوات المستمعات رسالة سمت نفسها أمة الله أم عبد الرحمن من المنطقة الشرقية، تسأل عن كيفية قضاء الوتر في النهار إذا نام عنه صاحبه؛ لأنه بلغنا أن بعض العلماء يقول بقضاء الوتر؟ جزاكم الله خيرًا.","title":"كيفية قضاء الوتر","answer":"السنة أن يقضى الوتر، كان النبي ﷺ إذا شغله مرض أو نوم عن وتره من الليل صلى من النهار، تقول عائشة رضي الله عنها: \"كان النبي ﷺ إذا شغله عن وتره مرض أو نوم صلى من النهار ثنتي عشرة ركعة\"، وكان وتره في الغالب إحدى عشرة، فإذا شغله عنه شاغل صلى ثنتي عشرة، زاد واحدة، فهذا هو السنة، أنه يقضى من النهار ولكن شفعًا لا وترًا، يزيدها ركعة اقتداءً بالنبي ﷺ، فإذا كانت عادته في الليل ثلاث ركعات تسليمة واحدة صلى من النهار أربع ركعات تسليمتين، وإذا كانت عادته خمس ركعات صلى من النهار ست ركعات ثلاث تسليمات، وإذا كانت عادته سبع ركعات من الليل صلى من النهار ثمان ركعات أربع تسليمات وهكذا، وإذا كانت عادته إحدى عشرة كفعل النبي ﷺ صلى من النهار ثنتي عشرة ركعة ست تسليمات، وإذا كانت عادته ثلاثة عشر صلى من النهار سبع تسليمات أربعة عشر، هذا هو الأفضل، وهو سنة نافلة ليس بواجب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16890/كيفية-قضاء-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_845/nour_84507.mp3","categories":["قضاء الفوائت","الوتر وقيام الليل"]},{"id":17955,"question":"سماحة الشيخ! هذه سائلة تقول: عندما كنت صغيرة وحتى كبرت كنت أعيش تحت رعاية أبي ولم أكن أصلي ولم أكن أصوم وذلك جهلًا مني، وعندما تزوجت هذه المرأة تقول: ومن ذلك الوقت وأنا أصوم وأصلي والحمد لله، ماذا يجب علي أن أفعل في الصلاة والصيام السابق أيام شبابي مع العلم بأنني تبت إلى الله وندمت على هذا العمل؟","title":"حكم من كان لا يصلي ولا يصوم ثم تاب","answer":"الجواب: التوبة كافية، إنسان ما يصلي ولا يصوم ثم تاب التوبة كافية وليس عليه قضاء، الحمد لله، يقول جل وعلا: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ[الأنفال:38]، ويقول النبي ﷺ: التوبة تجب ما قبلها فالكافر إذا أسلم وتاب تاب الله عليه، ولم يلزمه قضاء ما مضى، وهكذا الذي لا يصلي إذا تاب تاب الله عليه، ولا يلزمه القضاء، لا صوم، ولا صلاة، ولا غير ذلك، التوبة تجب ما قبلها نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16977/حكم-من-كان-لا-يصلي-ولا-يصوم-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78017.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":18080,"question":"ما حكم من تذكر الفائتة بعد أن شرع في الحاضرة؟ هل يغير نيته؟ أو يبقى على وضعه؟ جزاكم الله خيرًا.","title":"حكم من تذكّر الصلاة الفائتة بعد أن شرع في الحاضرة","answer":"الجواب: إن كان إمامًا، أو مأمومًا؛ فله حال، وإن كان مفردًا؛ له حال، إن كان عليه فريضة نسيها، أو نام عنها، ثم أحرم بالتي بعدها ناسيًا؛ يقطعها، يصلي الفريضة الفائتة قبل، على الترتيب، فلو كان نام عن الظهر مثلًا، نسي، فلما صلى العصر، تذكر؛ فإنه يقطعها، وينوي الظهر، ولو كان مأمومًا، يقطعها وينوي الظهر، وإن كان إمامًا نوى في صلاته الظهر، والذي وراءه ناوين العصر، وتصح صلاته، مثلما صلى معاذ بأصحابه، صلى معاذ بأصحابه وهو كان قد صلى مع النبي ﷺ العشاء، ويصلي بهم صلاة الفريضة هو. فالمقصود؛ أنه إن كان إمامًا، وتذكر أن عليه فريضةً سابقة، يصليها نافلة، ينويها نافلة، ويكمل هو نافلة، ثم يقوم هو يصلي، هم صلاتهم صحيحة، وإن كان عند الإحرام، بعد أن أحرم، ونواها الفائتة التي عليه، صحت منه أيضًا، وصلاتهم صحيحة هم، لأن اختلاف النية على الصحيح ما يؤثر. وإن كان مأمومًا أحرم معهم بالعصر، يحسب أنه ما عليه الظهر، ثم تذكر أن عليه الظهر، ينوي قطع الصلاة، ثم يحرم إحرامًا جديدًا بنية الظهر، وتجزي خلف العصر، فإذا صلى العصر، صلى بعدها العصر، سواءً في المسجد، أو في بيته، إن كان وجد جماعة صلى معهم العصر، وإلا صلاها في بيته، الحمد لله. نعم. المقدم: جزاكم الله خيرًا، إذًا الفائتة مقدمة بكل حال؟ الشيخ: نعم؛ إلا إذا ما تذكر إلا بعد ذلك، ما عليه شيء، إذا ما تذكر أن عليه الظهر، ولا تذكر إلا بعدما صلى العصر؛ تجزئ صلاة العصر، ويصلي الظهر بعدين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17115/حكم-من-تذكر-الصلاة-الفاىتة-بعد-ان-شرع-في-الحاضرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73004.mp3","categories":["قضاء الفوائت"]},{"id":18178,"question":"كنت من قبل لا أواظب على الصلاة والصوم، ثم تبت إلى الله والحمد لله، وقد سمعت في برنامجكم أن الصلاة لا تقضى، فهل الصوم كذلك، أم أن الصوم يجب قضاؤه؟ علمًا بأنني لا أعلم كم صمت وكم أفطرت.","title":"حكم قضاء الصلاة والصوم لمن تاب من تركهما","answer":"الجواب: أما الصلاة فمن تركها عمدًا لا يقضي بل عليه التوبة إلى الله ؛ لأن تركها ردة عن الإسلام والمرتد لا يقضي ما ترك، فعليه أن يتوب إلى الله، وأن يبادر بالصلاة، ويسأل الله العفو عما مضى. أما إذا كان المؤمن يصلي والمؤمنة تصلي ولكن تتساهل في بعض الصيام فإنه يقضي؛ لأن ترك الصيام ليس بردة عن الإسلام، ولكنه معصية كبيرة؛ فإذا تركت المرأة قضاء الصوم أو الرجل قضاء الصوم؛ فإنه يلزمه التوبة إلى الله مع قضاء الصوم، وعليه مع ذلك إطعام مسكين عن كل يوم إذا تأخر القضاء عن رمضان الذي يلي رمضان الذي تركه منه؛ فإنه يقضي ويطعم مسكين عن كل يوم نصف صاع من قوت البلد مقداره كيلو ونص تقريبًا من جهة الوزن مع الصوم ومع التوبة إلى الله  وقد أفتى بالطعام جماعة من أصحاب النبي ﷺ كفارة وتعزيرًا للمتخلف في قضاء صومه. نعم.","link":"https://binbaz.org.sa/fatwas/17223/حكم-قضاء-الصلاة-والصوم-لمن-تاب-من-تركهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85407.mp3","categories":["قضاء الفوائت","قضاء الصيام","حكم الصلاة وأهميتها"]},{"id":18226,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع خليفة محمود جاد مصري الجنسية، ويعمل في بيشة، أخونا يقول: إنني لم أبدأ الصلاة إلا بعد سن العشرين، فماذا علي في المدة السابقة؟ جزاكم الله خيرًا.","title":"حكم من ترك الصلاة لسنوات ثم تاب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فليس عليك -يا أخي- إلا التوبة إلى الله  والندم على ما فعلت من الترك، والله  يقول: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]، وترك الصلاة كفر، وإنما علاجه بالتوبة، فإذا تاب الرجل من ذلك أو المرأة من ذلك كفى ولا قضاء؛ لقول الله : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] وقوله ﷺ: الإسلام يهدم ما كان قبله، والتوبة تجب ما كان قبلها. فاحمد الله -يا أخي- على الهداية، واسأله الثبات، واندم على ما مضى من تقصيرك، والتزم التوبة النصوح، واستكثر من الخير والعمل الصالح، وأبشر بالخير والعاقبة الحميدة. نسأل الله لنا ولك الثبات على الحق. نعم.","link":"https://binbaz.org.sa/fatwas/17269/حكم-من-ترك-الصلاة-لسنوات-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_857/nour_85701.mp3","categories":["قضاء الفوائت","حكم الصلاة وأهميتها"]},{"id":18667,"question":"يسألن عن شخص كان يصلي، ولكنه كان يترك الصلاة أحيانًا، ويتابع أحيانًا أخرى، لكنه الآن -ولله الحمد والشكر- مداوم على الصلاة وبانتظام، هل عليه أن يقضي ما فاته من تلك الصلوات، أم التوبة تكفيه؟جزاكم الله خيرًا.","title":"كيف يقضي مَن كان يترك الصلاة أحيانًا؟","answer":"الجواب: التوبة تكفيه، والحمد لله، وليس عليه قضاء؛ لقول الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] وقول النبي ﷺ: التوبة تجب ما قبلها وقوله -عليه الصلاة والسلام-: التائب من الذنب كمن لا ذنب له. ترك الصلاة كفر، والتوبة تجب ذلك، وتمحو ذلك، والحمد لله، إذا تاب توبة صادقة، بالندم على الماضي، والمحافظة على الصلاة، والعزم الصادق ألا يعود، فالله يعفو عنه...، ليس عليه قضاء. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17778/كيف-يقضي-من-كان-يترك-الصلاة-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73507.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":18936,"question":"أخت لنا من الرياض بعثت برسالة تقول: ابنتكم: (م. م. ش) أختنا تقول: لي سؤال يتلخص في: أنني أريد قضاء بعض الصلوات التي فاتتني، وأريد أن أعرف كيفية الإعادة، حيث أني فيما مضى لا أستطيع تقدير وقت عادتي الشهرية، وتمر علي بعض الأيام، ولا أعرف الطهر منها، فتفوتني الصلاة، وكنت أقضيها، ولكن كيفية القضاء كانت خاطئة فيما علمت بعد ذلك. الرجاء من سماحة الوالد الشيخ عبد العزيز أن يوضح لي وللأخوات المسلمات كيفية القضاء، وحبذا لو بعث برسالة خاصة إلى النساء في هذا الموضوع. جزاكم الله خيرًا.","title":"حكم قضاء المرأة صلاة ما فاتها جهلًا بأحكام الحيض","answer":"الجواب: الواجب على المرأة أن تعتني بحيضها وطهرها، فإذا مضت العادة التي تعرفها خمسًا أو ستًا، أو أكثر أو أقل، اغتسلت وصلت وصامت وحلت لزوجها، حتى تجيء العادة، حتى تجيء الدورة، وإذا كانت الدورة تزيد وتنقص فلا بأس، عادة النساء قد تتغير، تزيد تنقص، قد تكون في بعض الشهور خمسة أيام، وفي بعض الشهور ستة أيام، سبعة أيام، فلا حرج، متى رأت الدم لا تصلي، ولا تصوم، ولا تحل لزوجها، ومتى رأت الطهارة -القصة البيضاء- أو تلطفت بقطن ونحوه، ورأته نظيفًا اغتسلت وصلت وصامت، والحمد لله. أما إن استمر معها الدم هذه تكون مستحاضة إذا استمر معها الدم أكثر من خمسة عشر يومًا، استمر معها فإنها تكون مستحاضة تصلي وتصوم في كل وقت وتقف عن الصلاة في وقت العادة، فإذا جاءت الدورة وقفت لم تصل ولم تصم بعدد أيام الدورة خمسًا أو ستًا أو سبعًا، أو نحو ذلك. فإذا ذهبت الدورة اغتسلت وصلت وصامت وصارت هذه الدماء التي معها تعتبر استحاضة دم فساد، تصلي معها وتصوم معها وتحل لزوجها؛ لأنها دماء غير مانعة من الصلاة، بل هي تسمى استحاضة، فهي تتوضأ لوقت كل صلاة تتحفظ بقطن أو غيره مما يخفف عنها الدم وتصلي كل وقت في وقته. وإن جمعت بين وقتين الظهر والعصر والمغرب والعشاء فلا بأس، كما علم النبي ﷺ حمنة بنت جحش لما كثر عليها الدم، وإذا اغتسلت للظهر والعصر غسلًا واحدًا والمغرب والعشاء غسلًا واحدًا كان أفضل وللفجر غسلًا واحدًا كذلك مع الوضوء تتوضأ لكل صلاة، ولكن الغسل هو أفضل وليس بواجب في حال الاستحاضة -يعني: في الأيام التي بين الدورتين- والدم يمشي فيها، فهذه يقال لها: أيام استحاضة، فإن صلت فيها كل وقت في وقته فلا بأس الظهر في وقتها والعصر في وقتها والمغرب في وقتها والعشاء في وقتها، تتوضأ إذا دخل الوقت تستنجي وتتوضأ أو تستجمر بالمناديل، ونحوها، حتى تزيل الأذى من فرجها، ثم تتوضأ وضوء الصلاة وتصلي كل صلاة في وقتها فهذا جائز، وإن جمعت بين الصلاتين الظهر والعصر وبين المغرب والعشاء فهذا أفضل، كما علم النبي ﷺ حمنة بنت جحش، وإذا اغتسلت مع ذلك فهو أفضل للظهر والعصر غسل، وللمغرب والعشاء غسل وللفجر غسل على سبيل الاستحباب، نعم. المقدم: جزاكم الله خيرًا. ترجو من سماحة الشيخ توجيهها في موضوع إعادة الصلاة أي القضاء؟ الشيخ: إذا كانت تعلم شيئًا تقضيه، أما إذا كانت لا تعلم فالوساوس ينبغي اطراحها، إذا كانت تعلم أنها قصرت في شيء من الصلوات التي وجبت عليها في حال الطهر، وأنها التبس عليها الأمر إن كانت تعلم شيئًا تقضيه، أما إن كانت لا تعلم شيئًا، وإنما هي وساوس وظنون فلا تلتفت إليها، وتتعوذ بالله من الشيطان، ولا تلتفت إليها. أما الشيء الذي يترك عمدًا وتساهلًا وقلة مبالاة، فهذا ليس له دواء إلا التوبة، التوبة إلى الله والندم على ما فعلت، ويكفي هذا ولا قضاء في ذلك، فإن المسلم إذا ترك الصلاة عمدًا ليس لها كفارة إلا التوبة؛ لأن تركها كفر، نعوذ بالله من ذلك، كما قال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر. إذا تركها عمدًا عدوانًا متعمدًا ليس عن نسيان ولا عن جهل في بعض الأحكام، وإنما تعمد تركها، فهذا قد أتى كفرًا عظيمًا، نعوذ بالله، وعليه التوبة إلى الله من ذلك، ولا يقضي شيئًا.  أما الذي يترك ذلك لمرض أو اشتباه ثم انتبه وعرف أن الواجب عليه أن يصلي، ولم يتعمد تركها تساهلًا، ولكن بعض الناس قد يظن أنه إذا أخرها حتى يزول عنه المرض يكون أصلح، فهذا غلط منه يصلي على حسب حاله ولو أنه مريض، يصلي قاعدًا إن عجز عن القيام، يصلي على جنبه إن عجز عن القعود، يصلي مستلقيًا إن عجز عن الصلاة على الجنب، ولا يؤخرها، ولا يتركها، بل يجب أن يصليها في الوقت على أي حال كان قائمًا أو قاعدًا، أو على جنب أو مستلقيا حسب طاقته: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وهكذا أمر النبي ﷺ المريض، قال لـعمران بن حصين وهو مريض: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هكذا علمه النبي -عليه الصلاة والسلام-، وهذا هو الواجب على المرضى أينما كان، ولا يؤخرون الصلاة، ليس لأحد تأخيرها عن وقتها، بل إما أن يصليها في وقتها، وإما أن يجمعها مع قرينتها كالظهر مع العصر، والمغرب مع العشاء لمرض أصابه، وعلة أصابته، وكالمستحاضة أيضًا، وكالمسافر، نعم. المقدم: بارك الله فيكم، إذًا كيفية القضاء سماحة الشيخ؟ الشيخ: كيفية القضاء مثلما سمعت، عليها أن تقضي ما تركته نسيانًا، أو تركته لمرض تظن أن تأخيره أصلح، فعلمت أنها مخطئة في تأخيره تقضي، فتقضي كما يقضي الناسي، وكما يقضي من نام عنها، ونحو ذلك. أما الذي تركها عمدًا تساهلاً منه قلة مبالاة فهذا ليس له إلا التوبة، ولا يلزمه القضاء على الصحيح من أقوال العلماء. المقدم: بارك الله فيكم، إذاً: ليس للقضاء وقت معين، ولا يلزم أن يقضى كل فرض مع مثيله؟ الشيخ: لا، القضاء يلزم في الحال إذا كان عن نوم أو نسيان يبادر به؛ لقول النبي ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها، لا كفارة لها إلا ذلك هذا المعذور، أما الذي تركها غير معذور عامدًا متساهلًا، فهذا عليه التوبة الصادقة، ولا قضاء عليه على الصحيح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18081/حكم-قضاء-المراة-صلاة-ما-فاتها-جهلا-باحكام-الحيض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92404.mp3","categories":["قضاء الفوائت","قضايا المرأة"]},{"id":18978,"question":"له سؤال لعله يوضح جانبًا آخر من جوانب حياته، فيسأل سماحة الشيخ ويقول: في فترة شبابي تمر علينا بعض الأيام فلا نصلي فيها الفروض، الأيام كثيرة سامحنا الله وإياكم، ولقد قرأت في إحدى الصحف بأنه لا بد من قضائها رغم فوات المدة عليها؛ وذلك بعد الصلوات المفروضة، أنا الآن الحمد لله أصلي جميع الفروض، وفي أوقاتها، دلوني على الجواب الصحيح.جزاكم الله خيرًا.","title":"حكم قضاء الصلاة لمن تاب من تركها","answer":"الجواب: الواجب التوبة من ذلك، وليس عليها قضاء، هذا هو الصحيح من قولي العلماء؛ لأن ترك الصلاة كفر، والكفر لا يزول إلا بالتوبة، فإذا ترك الإنسان الصلاة، ثم تاب، فإنه لا قضاء عليه، هذا هو المختار، وهو الصواب، وليس عليك شيء -إن شاء الله- إلا التوبة، فعليك التوبة الصادقة، والندم على ما مضى منك، والعزم ألا تعود في ذلك، والاستكثار من الحسنات، والأعمال الصالحات، كما قال الله سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]. والتوبة تجب ما كان قبلهاكما قاله النبي -عليه الصلاة والسلام- نسأل الله أن يمنحنا وإياك التوبة الصادقة، وأن يعيذنا وإياك والمسلمين من نزغات الشيطان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18126/حكم-قضاء-الصلاة-لمن-تاب-من-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92502.mp3","categories":["حكم الصلاة وأهميتها","قضاء الفوائت"]},{"id":19084,"question":"تسأل في سؤالها الثاني: هل يجب قضاء الصلاة إذا حاضت المرأة وقت .........","title":"حكم من جاءها الحيض وقد دخل وقت صلاة ولم تصلها","answer":"الجواب: .........\nالدخول فلا قضاء لأنها: ما أدركت الوقت، وأما بعد الدخول فلا حرج عليها ولا تفريط فلا قضاء عليها، ولكن إذا طهرت في الوقت تقضي الصلاة التي طهرت في وقتها، طهرت في وقت الظهر تصلي الظهر والعصر، طهرت في وقت المغرب أو العشاء تصلي المغرب والعشاء، طهرت في وقت الفجر تصلي الفجر. أما لو جاءها الحيض بعد الزوال فإنها لا تقضي الظهر، وكذلك لو جاءها الحيض بعد أذان الفجر وبعد طلوع الفجر لا يلزمها بعد الطهر قضاء صلاة الفجر، وبعض أهل العلم قالوا: عليها أن تقضي هذا الوقت، ولكن ليس عليه دليل، وإن قضت فلا بأس، إن قضته فلا حرج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18228/حكم-من-جاءها-الحيض-وقد-دخل-وقت-صلاة-ولم-تصلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92810.mp3","categories":["الحيض والنفاس","قضاء الفوائت","قضايا المرأة"]},{"id":19458,"question":"يقول هذا السائل أيضًا من ليبيا يا سماحة الشيخ: هل يجوز قضاء الصلوات الفائتة؟ أم تكفي التوبة فقط؟","title":"حكم قضاء الفائتة من الصلوات","answer":"الجواب: بل يجب قضاء الفائتة، إذا فاته شيء من الصلوات وجب عليه القضاء؛ لقوله ﷺ: ما أدركتم فصلوا وما فاتكم فاقضوا ولأنها فريضة فهي واجبة عليه، فإذا نام عنها أو نسيها أو تعمد تركها وجب عليه القضاء، أما إذا نام أو نسي وجب القضاء؛ لقوله ﷺ: من نام عن الصلاة أو نسيها فليصلها إذا ذكرها. أما إذا كان تعمدها فهذا منكر عظيم، لكن إذا قضاها احتياطًا إن كانت قليلة وإلا فالتوبة تجب ما قبلها، لكن إذا كانت قليلة صلاتين أو ثلاث قضاها احتياطًا وخروجًا من الخلاف حسن إن شاء الله، أما إذا كانت كثيرة فلا قضاء، التوبة تكفي؛ لأن تركها كفر، نسأل الله العافية. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18700/حكم-قضاء-الفاىتة-من-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93901.mp3","categories":["قضاء الفوائت"]},{"id":19632,"question":"السائلة تقول: امرأة أسقطت أربع مرات، وعمر الجنين أقل من شهرين، ولم تصل حتى تطهر، هل عليها قضاء؟","title":"حكم صلاة من أسقطت جنينًا أقل من شهرين","answer":"الجواب: إذا كان فيه بيان، إذا كان فيه علامة إنسان: رأس، أو يد، أو رجل؛ فهو نفاس، تترك الصلاة أربعين ليلة إلا أن تطهر قبل الأربعين، أما إذا كان دم ما فيه رأس، ولا رجل؛ فالواجب عليها الصلاة، وقضاء الصلاة التي تركت؛ لأنه ما هو بنفاس مجرد الدم ليس بنفاس، إلا إذا كان فيه علامة إنسان إما يد، أو رجل، أو رأس؛ شيء يبين أنه طفل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18901/حكم-صلاة-من-اسقطت-جنينا-اقل-من-شهرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94832.mp3","categories":["الحيض والنفاس","قضاء الفوائت","قضايا المرأة"]},{"id":19713,"question":"إذا فاتته صلاة بالليل أو بالنهار، فمتى يقضيها؟","title":"متى يقضي من فاتته صلاة بالليل أو بالنهار؟","answer":"متى ذكرها ليلاً أو نهارًا.","link":"https://binbaz.org.sa/fatwas/27367/متى-يقضي-من-فاتته-صلاة-بالليل-او-بالنهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%85%D8%AA%D9%89%20%D9%8A%D9%82%D8%B6%D9%8A%20%D9%85%D9%86%20%D9%81%D8%A7%D8%AA%D8%AA%D9%87%20%D8%B5%D9%84%D8%A7%D8%A9%20%D8%A8%D8%A7%D9%84%D9%84%D9%8A%D9%84%20%D8%A3%D9%88%20%D8%A8%D8%A7%D9%84%D9%86%D9%87%D8%A7%D8%B1%D8%9F.mp3","categories":["قضاء الفوائت"]},{"id":19723,"question":"بعد هذا رسالة بعث بها مستمع يقول: أخوكم أحمد الزين، أخونا أحمد يقول: إنني مريض في الفراش منذ فترة -أدام الله عليكم الصحة- هل لي أن أقضي الصلاة التي فاتتني من قبل؛ إذ أنني لا أعرف متى سيكون الشفاء، فهذا في علم الله؟","title":"حكم قضاء الصلاة لمن تركها بسبب المرض","answer":"الجواب: شفاكم الله وعافاكم، ونسأل الله لنا ولكم الشفاء والعافية.\nوالواجب عليك أن تصلي في مرضك، وأن تتوضأ الوضوء الشرعي؛ فإن عجزت تيممت بالتراب وتصلي كل صلاة في وقتها، وإن جمعت بين الظهر والعصر والمغرب والعشاء فلا بأس، هذا الواجب عليك. وإن كنت تركت شيئًا فعليك القضاء، إن كنت تركت شيئًا من الصلوات الخمس فعليك القضاء مع التوبة والاستغفار والندم، فهذه أمور عظيمة، والصلاة عمود الإسلام، والتعمد لتركها كفر؛ فالواجب عليك الحذر، وعدم التساهل، تصلي الصلاة لوقتها ولو جمعًا بين المغرب والعشاء والظهر والعصر، وإذا كنت عاجزًا عن الماء تيمم فإن استطعت الماء فافعل الماء. فالمقصود أن الواجب عليك أن تصلي كما شرع الله، ربك يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ.. [التغابن: 16]، فعليك أن تصلي حسب الطاقة، قائمًا إن قدرت، قاعدًا إن لم تستطع القيام، فإذا عجزت عن القعود صليت على جنبك، عجزت على الجنب تصلي مستلقيًا، وتقرأ وتنوي بقلبك أعمال الصلاة حسب الطاقة، ولا يجوز لك ترك الصلاة، فإذا كنت تركت شيئًا منها ظنًا منك أنه جائز فعليك القضاء، عليك القضاء. أما إن كنت تعمدت الترك تساهلاً منك فعليك التوبة ولا قضاء، عليك التوبة إلى الله والندم والإقلاع وعدم الرجوع إلى هذا الشيء ولا قضاء عليك؛ فإن قضيت فلا حرج؛ لأن بعض أهل العلم رأى عليك القضاء وأنك لا تكفر إلا بجحد الوجوب. ولكن الصواب أن من ترك الصلاة وإن لم يجحد الوجوب يكفر ولا قضاء عليه وعليه التوبة.","link":"https://binbaz.org.sa/fatwas/28601/حكم-قضاء-الصلاة-لمن-تركها-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D9%82%D8%B6%D8%A7%D8%A1%20%D8%A7%D9%84%D8%B5%D9%84%D8%A7%D8%A9%20%D9%84%D9%85%D9%86%20%D8%AA%D8%B1%D9%83%D9%87%D8%A7%20%D8%A8%D8%B3%D8%A8%D8%A8%20%D8%A7%D9%84%D9%85%D8%B1%D8%B6.mp3","categories":["قضاء الفوائت","صلاة المريض"]}]
